s=A.p([m,A.p(["M\u1ec7nh","L\xe0 ng\u01b0\u1eddi th\xf4ng minh, kh\xf4n lanh, t\u01b0 t\u01b0\u1edfng ph\xf3ng kho\xe1ng trong t\xecnh c\u1ea3m, c\xf3 nh\u1eefng quan ni\u1ec7m \u0111\u1ed9c \u0111\xe1o v\u1ec1 t\xecnh y\xeau nh\u01b0ng \u0111\xf4i khi thi\u1ebfu th\u1ef1c t\u1ebf, th\xedch s\u1ef1 l\xe3ng m\u1ea1n, hay gi\u1ea3 ngu. Gi\u1ecfi v\u1ec1 v\u0103n ch\u01b0\u01a1ng ngh\u1ec7 thu\u1eadt, \u0111\xe0n ca s\xe1o nh\u1ecb, d\u1ec5 b\u1ecb thu h\xfat b\u1edfi nh\u1eefng m\u1ed1i quan h\u1ec7 kh\xf4ng ch\xednh th\u1ed1ng ho\u1eb7c c\xf3 t\xednh ch\u1ea5t \u0111\u1eb7c bi\u1ec7t. Xinh \u0111\u1eb9p, c\xf3 gu \u0103n m\u1eb7c th\u1ea9m m\u1ef9, hay thu h\xfat \xe1nh nh\xecn c\u1ee7a ng\u01b0\u1eddi kh\xe1c, lu\xf4n l\xe0 trung t\xe2m \xe1nh nh\xecn. Th\xf4ng minh h\u01a1n ng\u01b0\u1eddi nh\u01b0ng kh\xf4ng l\u1ea1i v\u1edbi tr\u1eddi, \u0111\u1ec3 r\u1ed3i sau n\xe0y \u0111\u01b0\u01a1ng s\u1ed1 s\u1ebd l\xe0 m\u1ed9t ng\u01b0\u1eddi m\u1ed9 \u0111\u1ea1o sau khi tr\u1ea3i qua m\u1ed9t lo\u1ea1t th\u1ea5t b\u1ea1i trong cu\u1ed9c s\u1ed1ng, trong h\xf4n nh\xe2n. Ng\u01b0\u1eddi thi\xean kh\xf4ng \u0111i chung v\u1edbi \u0111\xe0o hoa th\xec r\u1ea5t d\u1ec5 g\u1eb7p nh\u1eefng chuy\u1ec7n \xe9o le trong t\xecnh c\u1ea3m, h\xf4n nh\xe2n."],d4,d4),l,A.p(["M\u1ec7nh","T\xe2m h\u1ed3n l\xe3ng m\u1ea1n nh\u01b0ng c\xf4 \u0111\u1ed9c, c\xf3 nh\u1eefng quan ni\u1ec7m \u0111\u1ed9c \u0111\xe1o v\u1ec1 t\xecnh y\xeau v\xe0 t\xe2m linh. D\u1ec5 r\u01a1i v\xe0o nh\u1eefng m\u1ed1i t\xecnh \u0111\u1eb9p nh\u01b0ng vi\u1ec3n v\xf4ng, c\u1ea3m th\u1ea5y kh\xf3 t\xecm \u0111\u01b0\u1ee3c ng\u01b0\u1eddi th\u1ea5u hi\u1ec3u s\xe2u s\u1eafc t\xe2m h\u1ed3n m\xecnh. C\xf3 \u0111\u1eddi s\u1ed1ng n\u1ed9i t\xe2m phong ph\xfa v\u1edbi ni\u1ec1m \u0111am m\xea nghi\xean c\u1ee9u nh\u1eefng \u0111i\u1ec1u huy\u1ec1n b\xed, nh\u01b0ng d\u1ec5 c\u1ea3m th\u1ea5y c\xf4 \u0111\u01a1n trong th\u1ebf gi\u1edbi ri\xeang \u0111\u1ea7y m\u01a1 m\u1ed9ng v\xe0 t\xe2m linh. S\u1ef1 th\xf4ng minh (thi\xean kh\xf4ng) \u1edf \u0111\xe2y h\u01b0\u1edbng n\u1ed9i, d\xf9ng \u0111\u1ec3 suy ng\u1eabm v\u1ec1 nh\u1eefng tri\u1ebft l\xfd s\xe2u xa c\u1ee7a cu\u1ed9c \u0111\u1eddi, nh\u01b0ng c\xe0ng hi\u1ec3u l\u1ea1i c\xe0ng th\u1ea5y c\xf4 \u0111\u1ed9c. C\xf3 duy\xean v\u1edbi Ph\u1eadt ph\xe1p ho\u1eb7c c\xe1c m\xf4n tu t\u1eadp t\xe2m linh \u0111\u1ec3 t\xecm ki\u1ebfm s\u1ef1 b\xecnh an n\u1ed9i t\u1ea1i."],d4,d4),k,A.p(["M\u1ec7nh","T\xednh c\xe1ch c\xf3 s\u1ef1 m\xe2u thu\u1eabn gi\u1eefa m\xe1u li\u1ec1u m\u1ea1o hi\u1ec3m v\xe0 s\u1ef1 ch\xednh danh, quy c\u1ee7. \u0110\u01b0\u01a1ng s\u1ed1 c\xf3 th\u1ec3 kh\u1edfi nghi\u1ec7p t\u1eeb nh\u1eefng d\u1ef1 \xe1n t\xe1o b\u1ea1o, \u0111\u1ea7u t\u01b0 m\u1ea1o hi\u1ec3m nh\u01b0ng nh\u1edd c\xf3 qu\xfd tinh d\u1eabn \u0111\u01b0\u1eddng n\xean bi\u1ebft c\xe1ch h\u1ee3p th\u1ee9c h\xf3a, bi\u1ebfn n\xf3 th\xe0nh m\u1ed9t c\xf4ng vi\u1ec7c ch\xednh th\u1ed1ng, \u0111\u01b0\u1ee3c x\xe3 h\u1ed9i c\xf4ng nh\u1eadn. \xc2n Quang mang Ph\u1eadt t\xednh, gi\xfap b\u1ea1n gi\u1ea3m b\u1edbt t\xednh n\xf3ng n\u1ea3y, bi\u1ebft h\u1ed3i h\u01b0\u1edbng, l\xe0m vi\u1ec7c thi\u1ec7n \u0111\u1ec3 c\xe2n b\u1eb1ng nghi\u1ec7p l\u1ef1c t\u1eeb nh\u1eefng vi\u1ec7c m\u1ea1o hi\u1ec3m. B\u1ea1n nh\u01b0 m\u1ed9t doanh nh\xe2n c\xf3 t\xe2m, bi\u1ebft l\u1ea5y l\u1ee3i nhu\u1eadn t\u1eeb nh\u1eefng khe h\u1edf th\u1ecb tr\u01b0\u1eddng \u0111\u1ec3 l\xe0m t\u1eeb thi\u1ec7n, gi\xfap \u0111\u1ee1 ng\u01b0\u1eddi ngh\xe8o. S\u1ef1 th\xe0nh c\xf4ng th\u01b0\u1eddng \u0111i k\xe8m v\u1edbi nh\u1eefng c\xe2u chuy\u1ec7n ly k\u1ef3 v\xe0 \u0111\u01b0\u1ee3c qu\xfd nh\xe2n ph\xf9 tr\u1ee3 \u0111\xfang l\xfac."],d4,d4),j,A.p(["M\u1ec7nh","T\xednh c\xe1ch c\xf3 s\u1ef1 m\xe2u thu\u1eabn gi\u1eefa m\xe1u li\u1ec1u m\u1ea1o hi\u1ec3m v\xe0 s\u1ef1 ch\xednh danh, quy c\u1ee7. \u0110\u01b0\u01a1ng s\u1ed1 c\xf3 th\u1ec3 kh\u1edfi nghi\u1ec7p t\u1eeb nh\u1eefng d\u1ef1 \xe1n t\xe1o b\u1ea1o, \u0111\u1ea7u t\u01b0 m\u1ea1o hi\u1ec3m nh\u01b0ng nh\u1edd c\xf3 qu\xfd tinh d\u1eabn \u0111\u01b0\u1eddng n\xean bi\u1ebft c\xe1ch h\u1ee3p th\u1ee9c h\xf3a, bi\u1ebfn n\xf3 th\xe0nh m\u1ed9t c\xf4ng vi\u1ec7c ch\xednh th\u1ed1ng, \u0111\u01b0\u1ee3c x\xe3 h\u1ed9i c\xf4ng nh\u1eadn."],d4,d4),i,A.p(["M\u1ec7nh",'Mang trong m\xecnh tinh th\u1ea7n "anh h\xf9ng" ho\u1eb7c "h\u1ea3o h\xe1n", th\xedch l\xe0m nh\u1eefng vi\u1ec7c l\u1edbn, d\xe1m ch\u1ea5p nh\u1eadn r\u1ee7i ro \u0111\u1ec3 \u0111\u1ea1t \u0111\u01b0\u1ee3c m\u1ee5c ti\xeau. Tuy nhi\xean, nh\u1edd c\xf3 Thi\xean Kh\xf4i v\xe0 Thi\xean Qu\xfd, b\u1ea1n bi\u1ebft c\xe1ch h\xe0nh x\u1eed \u0111\xfang m\u1ef1c, tu\xe2n th\u1ee7 khu\xf4n kh\u1ed5 v\xe0 lu\xf4n \u0111\u01b0\u1ee3c qu\xfd nh\xe2n ph\xf9 tr\u1ee3. Thi\xean Qu\xfd mang \u0111\u1ebfn ph\u1ea9m ch\u1ea5t cao qu\xfd, thanh li\xeam, khi\u1ebfn cho nh\u1eefng h\xe0nh \u0111\u1ed9ng m\u1ea1o hi\u1ec3m c\u1ee7a b\u1ea1n kh\xf4ng v\xec t\u01b0 l\u1ee3i nh\u1ecf nhoi m\xe0 th\u01b0\u1eddng v\xec m\u1ed9t l\xfd t\u01b0\u1edfng l\u1edbn h\u01a1n. B\u1ea1n c\xf3 th\u1ec3 l\xe0 ng\u01b0\u1eddi \u0111\u1ee9ng ra b\u1ea3o v\u1ec7 l\u1ebd ph\u1ea3i, \u0111\u1ea7u t\u01b0 v\xe0o nh\u1eefng d\u1ef1 \xe1n c\u1ed9ng \u0111\u1ed3ng m\u1eb7c d\xf9 r\u1ee7i ro cao. T\xednh n\xf3ng n\u1ea3y \u0111\u01b0\u1ee3c ki\u1ec1m ch\u1ebf b\u1edfi s\u1ef1 t\u1ef1 tr\u1ecdng v\xe0 \xfd th\u1ee9c v\u1ec1 danh d\u1ef1.'],d4,d4),h,A.p(["M\u1ec7nh","C\xf3 ch\xed kh\xed phi\xeau l\u01b0u, kh\xf4ng ng\u1ea1i d\u1ea5n th\xe2n v\xe0o nh\u1eefng h\xe0nh tr\xecnh xa l\u1ea1, th\u1eadm ch\xed nguy hi\u1ec3m \u0111\u1ec3 t\xecm ki\u1ebfm c\u01a1 h\u1ed9i \u0111\u1ed5i \u0111\u1eddi. Tuy nhi\xean, b\u1ea1n kh\xf4ng ph\u1ea3i l\xe0 k\u1ebb li\u1ec1u m\u1ea1ng v\xf4 \xfd th\u1ee9c. \xc2n Quang mang \u0111\u1ebfn t\u1ea5m l\xf2ng t\u1eeb bi v\xe0 ni\u1ec1m tin t\xe2m linh, khi\u1ebfn nh\u1eefng cu\u1ed9c phi\xeau l\u01b0u c\u1ee7a b\u1ea1n th\u01b0\u1eddng c\xf3 m\u1ee5c \u0111\xedch s\xe2u xa h\u01a1n l\xe0 l\u1ee3i nhu\u1eadn v\u1eadt ch\u1ea5t, c\xf3 th\u1ec3 l\xe0 \u0111\u1ec3 gi\xfap \u0111\u1ee1 ng\u01b0\u1eddi kh\xe1c ho\u1eb7c t\xecm ki\u1ebfm ch\xe2n l\xfd. Thi\xean Vi\u1ec7t gi\xfap b\u1ea1n v\u01b0\u1ee3t qua c\xe1c tr\u1edf ng\u1ea1i v\u1ec1 \u0111\u1ecba l\xfd v\xe0 v\u0103n h\xf3a, d\u1ec5 th\xedch nghi v\xe0 th\xe0nh c\xf4ng \u1edf n\u01a1i \u0111\u1ea5t kh\xe1ch. B\u1ea1n gi\u1ed1ng nh\u01b0 nh\u1eefng nh\xe0 th\xe1m hi\u1ec3m c\xf3 t\xe2m, ho\u1eb7c nh\u1eefng doanh nh\xe2n xuy\xean qu\u1ed1c gia v\u1edbi t\u1ea5m l\xf2ng t\u1eeb thi\u1ec7n."],d4,d4),g,A.p(["M\u1ec7nh","Kh\xe1t v\u1ecdng chinh ph\u1ee5c nh\u1eefng \u0111\u1ec9nh cao m\u1edbi \u1edf nh\u1eefng v\xf9ng \u0111\u1ea5t m\u1edbi. S\u1ef1 m\u1ea1o hi\u1ec3m \u0111\u01b0\u1ee3c d\u1eabn d\u1eaft b\u1edfi t\u1ea7m nh\xecn xa v\xe0 kh\xe1t v\u1ecdng v\u01b0\u1ee3t kh\u1ecfi gi\u1edbi h\u1ea1n \u0111\u1ecba ph\u01b0\u01a1ng, \u0111\u1ed3ng th\u1eddi \u0111\u01b0\u1ee3c trang b\u1ecb ph\u1ea9m gi\xe1 v\xe0 s\u1ef1 thanh cao. B\u1ea1n kh\xf4ng ng\u1ea1i r\u1eddi b\u1ecf qu\xea h\u01b0\u01a1ng \u0111\u1ec3 l\u1eadp nghi\u1ec7p, v\xe0 th\u01b0\u1eddng \u0111\u1ea1t \u0111\u01b0\u1ee3c th\xe0nh c\xf4ng vang d\u1ed9i, \u0111\u01b0\u1ee3c c\xf4ng nh\u1eadn \u1edf ph\u1ea1m vi r\u1ed9ng l\u1edbn h\u01a1n. B\u1ea1n mang v\u1ebb ngo\xe0i \u0111\xe0ng ho\xe0ng, c\xf3 kh\xed ch\u1ea5t khi\u1ebfn ng\u01b0\u1eddi ta n\u1ec3 ph\u1ee5c d\xf9 \u1edf b\u1ea5t c\u1ee9 \u0111\xe2u. Th\xe0nh c\xf4ng c\u1ee7a b\u1ea1n th\u01b0\u1eddng g\u1eafn li\u1ec1n v\u1edbi vi\u1ec7c ph\xe1 v\u1ee1 c\xe1c r\xe0o c\u1ea3n v\xe0 thi\u1ebft l\u1eadp c\xe1c ti\xeau chu\u1ea9n m\u1edbi."],d4,d4),f,A.p(["M\u1ec7nh","Th\xf4ng minh, c\xf3 t\u01b0 duy ph\xe1 c\xe1ch v\xe0 kh\xf4ng th\xedch \u0111i theo l\u1ed1i m\xf2n, nh\u01b0ng nh\u1edd c\xf3 Thi\xean Kh\xf4i v\xe0 \xc2n Quang n\xean bi\u1ebft c\xe1ch chuy\u1ec3n h\xf3a s\u1ef1 ph\xe1 c\xe1ch \u0111\xf3 th\xe0nh nh\u1eefng \u0111\xf3ng g\xf3p c\xf3 \xedch, \u0111\u01b0\u1ee3c c\xf4ng nh\u1eadn. Thi\xean Kh\xf4i mang l\u1ea1i t\xednh quy c\u1ee7, danh ch\xednh ng\xf4n thu\u1eadn, trong khi \xc2n Quang mang \u0111\u1ebfn t\u1ea5m l\xf2ng t\u1eeb bi. B\u1ea1n c\xf3 th\u1ec3 l\xe0 ng\u01b0\u1eddi c\u1ea3i c\xe1ch trong c\xe1c l\u0129nh v\u1ef1c ch\xednh th\u1ed1ng v\u1edbi t\xe2m huy\u1ebft gi\xfap \u0111\u1eddi. T\xednh n\xf3ng n\u1ea3y c\u1ee7a \u0110\u1ecba Kh\xf4ng \u0111\u01b0\u1ee3c h\xf3a gi\u1ea3i b\u1edfi s\u1ef1 nh\u1eabn n\u1ea1i t\u1eeb \xc2n Quang v\xe0 \xfd th\u1ee9c gi\u1eef g\xecn th\u1ec3 di\u1ec7n t\u1eeb Thi\xean Kh\xf4i."],d4,d4),e,A.p(["M\u1ec7nh","\u01afa m\u1ea1o hi\u1ec3m v\xe0 di chuy\u1ec3n xa. D\u1ec5 l\u1eadp c\xf4ng danh, c\xf3 ti\u1ebfng t\u0103m trong l\u0129nh v\u1ef1c chuy\xean m\xf4n (\u0111\u1eb7c bi\u1ec7t binh nghi\u1ec7p, kinh doanh l\u01b0u \u0111\u1ed9ng ho\u1eb7c c\xf4ng vi\u1ec7c \u0111\xf2i h\u1ecfi di chuy\u1ec3n). Tuy nhi\xean, cu\u1ed9c \u0111\u1eddi hay b\xf4n ba, ly h\u01b0\u01a1ng, thay \u0111\u1ed5i nhi\u1ec1u, c\u1ea7n c\u1ea9n tr\u1ecdng tr\xe1nh r\u1ee7i ro do li\u1ec1u l\u0129nh."],d4,d4),d,A.p(["M\u1ec7nh",'Kh\u1ea9u t\xe0i xu\u1ea5t ch\xfang, \u0103n n\xf3i l\u01b0u lo\xe1t, duy\xean d\xe1ng v\xe0 c\xf3 ph\u1ea7n sang ch\u1ea3nh. Tuy nhi\xean, H\xf3a K\u1ef5 khi\u1ebfn b\u1ea1n c\xf3 c\xe1 t\xednh m\u1ea1nh, phong c\xe1ch kh\xe1c bi\u1ec7t, d\u1ec5 b\u1ecb ng\u01b0\u1eddi kh\xe1c \u0111\u1ec3 \xfd v\xe0 \u0111\xe0m ti\u1ebfu. May m\u1eafn thay, ch\xednh kh\u1ea3 n\u0103ng \u0103n n\xf3i kh\xe9o l\xe9o v\xe0 s\u1ef1 thanh cao v\u1ed1n c\xf3 l\u1ea1i l\xe0 v\u0169 kh\xed h\xf3a gi\u1ea3i m\u1ecdi th\u1ecb phi. B\u1ea1n bi\u1ebft c\xe1ch d\xf9ng l\u1eddi n\xf3i \u0111\u1ec3 bi\u1ec7n minh, gi\u1ea3i th\xedch cho nh\u1eefng h\xe0nh \u0111\u1ed9ng kh\xe1c ng\u01b0\u1eddi c\u1ee7a m\xecnh, v\xe0 th\u01b0\u1eddng th\xe0nh c\xf4ng trong vi\u1ec7c thuy\u1ebft ph\u1ee5c ng\u01b0\u1eddi kh\xe1c. B\u1ea1n gi\u1ed1ng nh\u01b0 m\u1ed9t ngh\u1ec7 s\u0129 t\xe0i ba tr\xean s\xe2n kh\u1ea5u cu\u1ed9c \u0111\u1eddi, lu\xf4n bi\u1ebft c\xe1ch chi\u1ebfm l\u1ea5y \xe1nh \u0111\xe8n s\xe2n kh\u1ea5u v\xe0 bi\u1ebfn nh\u1eefng \u0111i\u1ec3m y\u1ebfu th\xe0nh th\u1ebf m\u1ea1nh. Tuy nhi\xean, c\u1ea7n \u0111\u1ec1 ph\xf2ng "kh\u1ea9u nghi\u1ec7p", \u0111\xf4i khi n\xf3i qu\xe1 hay, qu\xe1 kh\xe9o l\u1ea1i khi\u1ebfn ng\u01b0\u1eddi kh\xe1c ghen gh\xe9t, cho l\xe0 gi\u1ea3 t\u1ea1o.'],d4,d4),c,A.p(["M\u1ec7nh","T\xednh c\xe1ch m\u1ea1nh m\u1ebd, nguy\xean t\u1eafc v\xe0 v\xf4 c\xf9ng k\u1ef7 lu\u1eadt, nh\u01b0ng l\u1ea1i mang trong m\xecnh m\u1ed9t phong c\xe1ch, l\u1ed1i s\u1ed1ng ho\u1eb7c quan \u0111i\u1ec3m kh\xe1c bi\u1ec7t, d\u1ec5 g\xe2y hi\u1ec3u l\u1ea7m. B\u1ea1n nghi\xeam kh\u1eafc v\u1edbi b\u1ea3n th\xe2n v\xe0 v\u1edbi ng\u01b0\u1eddi kh\xe1c, lu\xf4n \u0111\xf2i h\u1ecfi s\u1ef1 ho\xe0n h\u1ea3o v\xe0 \u0111\xfang quy tr\xecnh. \u0110i\u1ec1u n\xe0y khi\u1ebfn b\u1ea1n tr\u1edf n\xean kh\xf3 g\u1ea7n v\xe0 d\u1ec5 b\u1ecb ng\u01b0\u1eddi xung quanh xa l\xe1nh, cho l\xe0 kh\xf3 t\xednh, hay x\xe9t n\xe9t. B\u1ea1n th\xedch h\u1ee3p v\u1edbi nh\u1eefng c\xf4ng vi\u1ec7c \u0111\xf2i h\u1ecfi \u0111\u1ed9 ch\xednh x\xe1c cao, t\u1ec9 m\u1ec9, ch\u1eadm m\xe0 ch\u1eafc, nh\u01b0 k\u1ebf to\xe1n, ki\u1ec3m to\xe1n, lu\u1eadt s\u01b0, k\u1ef9 s\u01b0 ph\u1ea7n m\u1ec1m. N\u1ebfu kh\xf4ng t\xf4n tr\u1ecdng ph\xe1p lu\u1eadt, b\u1ea1n r\u1ea5t d\u1ec5 v\u01b0\u1edbng v\xe0o c\xe1c r\u1eafc r\u1ed1i ph\xe1p l\xfd. Ng\u01b0\u1ee3c l\u1ea1i, n\u1ebfu bi\u1ebft tu\xe2n th\u1ee7, b\u1ea1n c\xf3 th\u1ec3 tr\u1edf th\xe0nh chuy\xean gia xu\u1ea5t s\u1eafc trong l\u0129nh v\u1ef1c c\u1ee7a m\xecnh."],d4,d4),b,A.p(["M\u1ec7nh","Quy\u1ebft \u0111o\xe1n, d\xe1m ngh\u0129 d\xe1m l\xe0m, nh\u01b0ng l\u1ea1i c\xf3 c\xe1ch th\u1ee9c, quan \u0111i\u1ec3m ho\u1eb7c phong c\xe1ch r\u1ea5t kh\xe1c ng\u01b0\u1eddi, th\u1eadm ch\xed l\xe0 d\u1ecb bi\u1ec7t. B\u1ea1n ti\u1ebfn v\u1ec1 ph\xeda tr\u01b0\u1edbc m\u1ed9t c\xe1ch h\u0103ng h\xe1i, \u0111\xf4i khi b\u1ea5t ch\u1ea5p, nh\u01b0ng l\u1ea1i th\u01b0\u1eddng \u0111i theo m\u1ed9t l\u1ed1i ri\xeang m\xe0 \xedt ng\u01b0\u1eddi hi\u1ec3u \u0111\u01b0\u1ee3c. \u0110i\u1ec1u n\xe0y khi\u1ebfn b\u1ea1n d\u1ec5 tr\u1edf th\xe0nh m\u1ee5c ti\xeau c\u1ee7a nh\u1eefng l\u1eddi \u0111\xe0m ti\u1ebfu, th\u1ecb phi, v\xe0 th\xe0nh c\xf4ng c\u1ee7a b\u1ea1n th\u01b0\u1eddng \xedt \u0111\u01b0\u1ee3c ng\u01b0\u1eddi kh\xe1c c\xf4ng nh\u1eadn m\u1ed9t c\xe1ch r\u1ed9ng r\xe3i. B\u1ea1n gi\u1ed1ng nh\u01b0 m\u1ed9t chi\u1ebfn binh \u0111\u01a1n \u0111\u1ed9c, chi\u1ebfn \u0111\u1ea5u cho nh\u1eefng l\xfd t\u01b0\u1edfng ri\xeang. C\u1ea7n h\u1ecdc c\xe1ch ki\u1ec1m ch\u1ebf s\u1ef1 n\xf3ng n\u1ea3y v\xe0 h\xe0nh \u0111\u1ed9ng b\u1ed3ng b\u1ed9t, v\xec r\u1ea5t d\u1ec5 g\xe2y t\u1ed5n th\u01b0\u01a1ng cho ng\u01b0\u1eddi kh\xe1c v\xe0 t\u1ef1 chu\u1ed1c l\u1ea5y th\u1ecb phi v\xe0o th\xe2n. Hay m\u1ea5t l\xf2ng v\u1edbi c\u1ea5p tr\xean, l\xe0m nhi\u1ec1u nh\u01b0ng kh\xf4ng \u0111\u01b0\u1ee3c ng\u01b0\u1eddi kh\xe1c c\xf4ng nh\u1eadn."],d4,d4),a,A.p(["M\u1ec7nh","K\xecnh D\u01b0\u01a1ng mang t\xednh ch\u1ea5t m\u1ea1nh m\u1ebd, h\xe0nh \u0111\u1ed9ng nhanh, quy\u1ebft \u0111o\xe1n nh\u01b0ng c\u1ea9n tr\u1ecdng l\xe0 hay m\u1ea5t l\xf2ng v\u1edbi c\u1ea5p tr\xean n\xean \u0111\xf4i khi l\xe0m nhi\u1ec1u nh\u01b0ng kh\xf4ng \u0111\u01b0\u1ee3c ng\u01b0\u1eddi kh\xe1c c\xf4ng nh\u1eadn. C\xf2n Thi\xean H\xecnh mang t\xednh k\u1ef7 lu\u1eadt, nguy\xean t\u1eafc v\xe0 h\xecnh ph\u1ea1t. Ng\u01b0\u1eddi c\xf3 b\u1ed9 sao n\xe0y c\xf3 t\xednh c\xe1ch c\u01b0\u01a1ng tr\u1ef1c, th\u1eb3ng th\u1eafn \u0111\u1ebfn m\u1ee9c c\u1ee9ng nh\u1eafc, lu\xf4n tu\xe2n th\u1ee7 nguy\xean t\u1eafc v\xe0 s\u1eb5n s\xe0ng d\xf9ng h\xe0nh \u0111\u1ed9ng m\u1ea1nh \u0111\u1ec3 b\u1ea3o v\u1ec7 l\u1ebd ph\u1ea3i theo c\xe1ch b\u1ea1n hi\u1ec3u. B\u1ea1n r\u1ea5t th\xedch h\u1ee3p v\u1edbi c\xe1c ng\xe0nh ngh\u1ec1 nh\u01b0 c\u1ea3nh s\xe1t, qu\xe2n \u0111\u1ed9i, v\xf5 s\u01b0, lu\u1eadt s\u01b0 h\xecnh s\u1ef1, ho\u1eb7c c\xe1c c\xf4ng vi\u1ec7c \u0111\xf2i h\u1ecfi k\u1ef7 lu\u1eadt th\xe9p. Tuy nhi\xean, b\u1ea1n d\u1ec5 tr\u1edf n\xean \u0111\u1ed9c \u0111o\xe1n, b\u1ea3o th\u1ee7 v\xe0 hay \xe1p \u0111\u1eb7t ng\u01b0\u1eddi kh\xe1c. Nguy c\u01a1 v\u01b0\u1edbng v\xe0o ki\u1ec7n t\u1ee5ng, h\xecnh s\u1ef1 l\xe0 kh\xe1 cao n\u1ebfu kh\xf4ng bi\u1ebft ki\u1ec1m ch\u1ebf t\xednh n\xf3ng n\u1ea3y v\xe0 h\xe0nh \u0111\u1ed9ng theo c\u1ea3m t\xednh."],d4,d4),"\u0110\xe0 La+H\xf3a K\u1ef5",A.p(["M\u1ec7nh","L\xe0 ng\u01b0\u1eddi c\xf3 t\xednh c\xe1ch ch\u1eadm r\xe3i, c\u1ea9n th\u1eadn, th\xedch suy ngh\u0129 th\u1ea5u \u0111\xe1o tr\u01b0\u1edbc khi h\xe0nh \u0111\u1ed9ng, nh\u01b0ng l\u1ea1i c\xf3 nh\u1eefng suy ngh\u0129, quan \u0111i\u1ec3m r\u1ea5t s\xe2u s\u1eafc, ph\u1ee9c t\u1ea1p v\xe0 kh\xe1c bi\u1ec7t so v\u1edbi s\u1ed1 \u0111\xf4ng. B\u1ea1n s\u1ed1ng n\u1ed9i t\xe2m, \xedt b\u1ed9c l\u1ed9 ra ngo\xe0i, nh\u01b0ng b\xean trong l\u1ea1i l\xe0 m\u1ed9t th\u1ebf gi\u1edbi quan \u0111\u1ea7y nh\u1eefng nghi ng\u1edd, ho\xe0i nghi v\xe0 nh\u1eefng \xfd t\u01b0\u1edfng \u0111\u1ed9c \u0111\xe1o. \u0110i\u1ec1u n\xe0y khi\u1ebfn b\u1ea1n d\u1ec5 b\u1ecb hi\u1ec3u l\u1ea7m l\xe0 l\u1eadp d\u1ecb, kh\xf3 g\u1ea7n, hay \u1ee7 d\u1ed9t. B\u1ea1n th\xedch h\u1ee3p v\u1edbi nh\u1eefng c\xf4ng vi\u1ec7c \u0111\xf2i h\u1ecfi s\u1ef1 t\u1ec9 m\u1ec9, ki\xean nh\u1eabn, nghi\xean c\u1ee9u chuy\xean s\xe2u, ho\u1eb7c c\xe1c ng\xe0nh ngh\u1ec1 th\u1ee7 c\xf4ng m\u1ef9 ngh\u1ec7 tinh x\u1ea3o. Tuy nhi\xean, b\u1ea1n d\u1ec5 b\u1ecb cu\u1ed1n v\xe0o nh\u1eefng suy ngh\u0129 ti\xeau c\u1ef1c, d\u1ec5 b\u1ecb t\u1ed5n th\u01b0\u01a1ng b\u1edfi l\u1eddi n\xf3i c\u1ee7a ng\u01b0\u1eddi kh\xe1c v\xe0 c\xf3 nguy c\u01a1 b\u1ecb c\xf4 l\u1eadp trong x\xe3 h\u1ed9i."],d4,d4),a0,A.p(["M\u1ec7nh","L\xe0 ng\u01b0\u1eddi th\xf4ng minh, c\xf3 nhi\u1ec1u \xfd t\u01b0\u1edfng \u0111\u1ed9c \u0111\xe1o v\xe0 ph\xe1 c\xe1ch, nh\u01b0ng l\u1ea1i d\u1ec5 b\u1ecb hao t\xe1n t\xe0i s\u1ea3n, s\u1ee9c l\u1ef1c m\u1ed9t c\xe1ch nh\u1ecf gi\u1ecdt, li\xean t\u1ee5c. B\u1ea1n c\xf3 th\u1ec3 c\xf3 nhi\u1ec1u d\u1ef1 \xe1n, \xfd t\u01b0\u1edfng kinh doanh s\xe1ng t\u1ea1o, nh\u01b0ng m\u1ed7i d\u1ef1 \xe1n \u0111\u1ec1u ti\xeau t\u1ed1n m\u1ed9t kho\u1ea3n ti\u1ec1n kh\xf4ng nh\u1ecf m\xe0 kh\xf3 mang l\u1ea1i l\u1ee3i nhu\u1eadn nh\u01b0 k\u1ef3 v\u1ecdng. Gi\u1ed1ng nh\u01b0 m\u1ed9t c\xe1i l\u1ed7 th\u1ee7ng nh\u1ecf tr\xean thuy\u1ec1n, tuy kh\xf4ng l\xe0m \u0111\u1eafm ngay nh\u01b0ng n\u01b0\u1edbc c\u1ee9 r\u1ec9 v\xe0o t\u1eeb t\u1eeb. T\xednh n\xf3ng n\u1ea3y v\xe0 thi\u1ebfu ki\xean nh\u1eabn c\u1ee7a \u0110\u1ecba Kh\xf4ng khi\u1ebfn b\u1ea1n d\u1ec5 b\u1ecf cu\u1ed9c gi\u1eefa ch\u1eebng, chuy\u1ec3n sang \xfd t\u01b0\u1edfng m\u1edbi, v\xe0 l\u1ea1i ti\u1ebfp t\u1ee5c m\u1ed9t v\xf2ng hao t\xe1n m\u1edbi. C\u1ea7n h\u1ecdc c\xe1ch t\u1eadp trung, ho\xe0n thi\u1ec7n m\u1ed9t vi\u1ec7c \u0111\u1ebfn n\u01a1i \u0111\u1ebfn ch\u1ed1n v\xe0 c\xf3 k\u1ebf ho\u1ea1ch t\xe0i ch\xednh chi ti\u1ebft, c\u1eaft gi\u1ea3m nh\u1eefng kho\u1ea3n chi kh\xf4ng c\u1ea7n thi\u1ebft.","T\xe0i B\u1ea1ch",'T\xe0i ch\xednh "v\xe0o kh\xf4ng \u0111\u1ee7 b\xf9 ra". Thu nh\u1eadp c\xf3 th\u1ec3 \u1ed5n nh\u01b0ng lu\xf4n c\xf3 nh\u1eefng kho\u1ea3n chi ti\xeau b\u1ea5t ng\u1edd, nh\u1ecf nh\u1eb7t l\xe0m hao h\u1ee5t t\xe0i kho\u1ea3n. Kh\xf3 t\xedch l\u0169y \u0111\u01b0\u1ee3c s\u1ed1 ti\u1ec1n l\u1edbn. D\u1ec5 b\u1ecb l\u1ed7 trong c\xe1c kho\u1ea3n \u0111\u1ea7u t\u01b0 nh\u1ecf l\u1ebb, mua b\xe1n online. C\u1ea7n l\u1eadp ng\xe2n s\xe1ch chi ti\xeau h\xe0ng th\xe1ng, ph\xe2n bi\u1ec7t r\xf5 gi\u1eefa "c\u1ea7n" v\xe0 "mu\u1ed1n". Tr\xe1nh mua s\u1eafm theo c\u1ea3m x\xfac ho\u1eb7c v\xec nh\u1eefng l\u1eddi qu\u1ea3ng c\xe1o hay ho.'],d4,d4),a1,A.p(["M\u1ec7nh","L\xe0 ng\u01b0\u1eddi c\xf3 t\u01b0 duy ph\xf3ng kho\xe1ng, d\xe1m ngh\u0129 l\u1edbn, d\xe1m l\xe0m nh\u1eefng vi\u1ec7c v\u01b0\u1ee3t kh\u1ecfi khu\xf4n kh\u1ed5 th\xf4ng th\u01b0\u1eddng, nh\u01b0ng \u0111i k\xe8m v\u1edbi \u0111\xf3 l\xe0 nguy c\u01a1 th\u1ea5t tho\xe1t t\xe0i s\u1ea3n m\u1ed9t c\xe1ch \u0111\xe1ng k\u1ec3, th\u1eadm ch\xed l\xe0 ph\xe1 s\u1ea3n. B\u1ea1n gi\u1ed1ng nh\u01b0 m\u1ed9t nh\xe0 \u0111\u1ea7u t\u01b0 m\u1ea1o hi\u1ec3m t\xe0i ba, c\xf3 th\u1ec3 ki\u1ebfm \u0111\u01b0\u1ee3c nh\u1eefng m\xf3n l\u1eddi kh\u1ed5ng l\u1ed3 t\u1eeb nh\u1eefng \xfd t\u01b0\u1edfng \u0111i\xean r\u1ed3, nh\u01b0ng c\u0169ng c\xf3 th\u1ec3 m\u1ea5t tr\u1eafng ch\u1ec9 sau m\u1ed9t \u0111\xeam. T\xednh n\xf3ng v\u1ed9i v\xe0 thi\u1ebfu th\u1ef1c t\u1ebf c\u1ee7a \u0110\u1ecba Kh\xf4ng k\u1ebft h\u1ee3p v\u1edbi s\u1ef1 hao t\xe1n l\u1edbn c\u1ee7a \u0110\u1ea1i Hao t\u1ea1o n\xean m\u1ed9t v\xf2ng xo\xe1y nguy hi\u1ec3m: ki\u1ebfm \u0111\u01b0\u1ee3c nhi\u1ec1u -> ti\xeau x\xe0i hoang ph\xed ho\u1eb7c \u0111\u1ea7u t\u01b0 li\u1ec1u l\u0129nh -> thua l\u1ed7 n\u1eb7ng -> l\u1ea1i lao v\xe0o ki\u1ebfm ti\u1ec1n b\u1eb1ng m\u1ecdi gi\xe1. C\u1ea7n c\xf3 m\u1ed9t ng\u01b0\u1eddi c\u1ed1 v\u1ea5n t\xe0i ch\xednh c\u1ef1c k\u1ef3 th\u1eadn tr\u1ecdng v\xe0 ph\u1ea3i h\u1ecdc c\xe1ch ki\u1ec1m ch\u1ebf b\u1ea3n th\xe2n, \u0111\u1eb7t ra c\xe1c gi\u1edbi h\u1ea1n r\u1ee7i ro r\xf5 r\xe0ng.","T\xe0i B\u1ea1ch",'\u0110\xe2y l\xe0 m\u1ed9t trong nh\u1eefng d\u1ea5u hi\u1ec7u m\u1ea1nh nh\u1ea5t c\u1ee7a s\u1ef1 ph\xe1 t\xe0i l\u1edbn. C\xf3 th\u1ec3 m\u1ed9t \u0111\u1eddi tr\u1ea3i qua v\xe0i l\u1ea7n "tay tr\u1eafng l\u1ea1i ho\xe0n tay tr\u1eafng", th\u1eadm ch\xed l\xe0 mang n\u1ee3 n\u1ea7n ch\u1ed3ng ch\u1ea5t. Ti\u1ec1n b\u1ea1c c\xf3 th\u1ec3 \u0111\u1ebfn t\u1eeb nh\u1eefng ngu\u1ed3n r\u1ea5t b\u1ea5t ng\u1edd (th\u1eeba k\u1ebf, tr\xfang s\u1ed1, \u0111\u1ea7u c\u01a1) nh\u01b0ng c\u0169ng d\u1ec5 m\u1ea5t \u0111i theo c\xe1ch kh\xf3 tin. C\u1ea7n h\u1ecdc c\xe1ch ph\xe2n b\u1ed5 t\xe0i s\u1ea3n, kh\xf4ng bao gi\u1edd "b\u1ecf t\u1ea5t c\u1ea3 tr\u1ee9ng v\xe0o m\u1ed9t gi\u1ecf". D\xe0nh m\u1ed9t ph\u1ea7n t\xe0i s\u1ea3n g\u1eedi ng\xe2n h\xe0ng ho\u1eb7c mua v\xe0ng, b\u1ea5t \u0111\u1ed9ng s\u1ea3n an to\xe0n v\xe0 kh\xf4ng bao gi\u1edd \u0111\u01b0\u1ee3c \u0111\u1ee5ng \u0111\u1ebfn.'],d4,d4),"Linh Tinh+V\u0103n X\u01b0\u01a1ng+\u0110\xe0 La+H\xf3a K\u1ef5",A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 mang trong m\xecnh m\u1ed9t t\xe2m tr\xed nh\u1ea1y b\xe9n nh\u01b0ng l\u1ea1i c\u1ef1c k\u1ef3 b\u1ea5t \u1ed5n v\u1ec1 m\u1eb7t c\u1ea3m x\xfac. Kh\u1ea3 n\u0103ng h\u1ecdc t\u1eadp v\xe0 ti\u1ebfp thu b\u1ecb k\xe9o xu\u1ed1ng \u0111\xe1ng k\u1ec3, kh\xf4ng ph\u1ea3i v\xec thi\u1ebfu th\xf4ng minh m\xe0 v\xec c\xe1i t\xe2m kh\xf4ng \u0111\u1ee7 t\u0129nh \u0111\u1ec3 ng\u1ed3i y\xean m\xe0 h\u1ecdc. B\u1ea1n d\u1ec5 b\xf9ng n\u1ed5, d\u1ec5 n\u1ed5i c\xe1u v\u1edbi nh\u1eefng chuy\u1ec7n nh\u1ecf nh\u1eb7t, v\xe0 khi c\u01a1n gi\u1eadn l\xean th\xec g\u1ea7n nh\u01b0 kh\xf4ng t\u1ef1 ki\u1ec1m ch\u1ebf \u0111\u01b0\u1ee3c. Nguy hi\u1ec3m h\u01a1n, khi \u0110\xe0 La v\xe0 H\xf3a K\u1ef5 c\xf9ng xu\u1ea5t hi\u1ec7n, b\u1ea1n r\u1ea5t d\u1ec5 r\u01a1i v\xe0o tr\u1ea1ng th\xe1i tr\u1ea7m c\u1ea3m dai d\u1eb3ng, stress ch\u1ed3ng ch\u1ea5t m\xe0 kh\xf4ng t\xecm \u0111\u01b0\u1ee3c l\u1ed1i tho\xe1t. \u0110\xe2y l\xe0 s\u1ef1 k\u1ebft h\u1ee3p n\u1eb7ng n\u1ec1 nh\u1ea5t trong nh\xf3m n\xe0y \u2014 c\u1ea7n \u0111\u1eb7c bi\u1ec7t ch\xfa \xfd \u0111\u1ebfn s\u1ee9c kh\u1ecfe t\xe2m th\u1ea7n, tr\xe1nh c\xf4 l\u1eadp b\u1ea3n th\xe2n v\xe0 n\xean c\xf3 ng\u01b0\u1eddi th\xe2n b\xean c\u1ea1nh trong nh\u1eefng giai \u0111o\u1ea1n kh\xf3 kh\u0103n."],d4,d4),"Linh Tinh+V\u0103n X\u01b0\u01a1ng+\u0110\xe0 La",A.p(["M\u1ec7nh","Kh\u1ea3 n\u0103ng h\u1ecdc t\u1eadp v\xe0 t\u01b0 duy b\u1ecb \u1ea3nh h\u01b0\u1edfng r\xf5 r\u1ec7t, \u0111\u01b0\u01a1ng s\u1ed1 th\u01b0\u1eddng h\u1ecdc m\xe0 kh\xf4ng v\xe0o, ho\u1eb7c ti\u1ebfp thu \u0111\u01b0\u1ee3c nh\u01b0ng l\u1ea1i kh\xf4ng v\u1eadn d\u1ee5ng \u0111\u01b0\u1ee3c tr\u01a1n tru. T\xednh c\xe1ch d\u1ec5 c\xe1u g\u1eaft, hay n\u1ed5i n\xf3ng v\xf4 c\u1edb, v\xe0 b\u1ea3n th\xe2n th\u01b0\u1eddng kh\xf4ng nh\u1eadn ra m\xecnh \u0111ang m\u1ea5t ki\u1ec3m so\xe1t cho \u0111\u1ebfn khi \u0111\xe3 n\xf3i ho\u1eb7c l\xe0m \u0111i\u1ec1u g\xec \u0111\xf3 \u0111\xe1ng ti\u1ebfc. Khi c\xf3 th\xeam \u0110\xe0 La, \xe1p l\u1ef1c t\xedch t\u1ee5 kh\xf4ng c\xf3 ch\u1ed7 tho\xe1t ra, d\u1eabn \u0111\u1ebfn tr\u1ea1ng th\xe1i c\u0103ng th\u1eb3ng \xe2m \u1ec9 k\xe9o d\xe0i, d\u1ec5 chuy\u1ec3n th\xe0nh tr\u1ea7m c\u1ea3m n\u1ebfu kh\xf4ng \u0111\u01b0\u1ee3c x\u1eed l\xfd \u0111\xfang c\xe1ch. B\u1ea1n c\u1ea7n h\u1ecdc c\xe1ch d\u1eebng l\u1ea1i tr\u01b0\u1edbc khi ph\u1ea3n \u1ee9ng, v\xe0 c\u1ea7n c\xf3 m\u1ed9t l\u1ed1i tho\xe1t l\xe0nh m\u1ea1nh nh\u01b0 th\u1ec3 d\u1ee5c, thi\u1ec1n \u0111\u1ecbnh, ho\u1eb7c t\xe2m s\u1ef1 v\u1edbi ng\u01b0\u1eddi tin t\u01b0\u1edfng."],d4,d4),a2,A.p(["M\u1ec7nh","\u0110\xe2y l\xe0 s\u1ef1 k\u1ebft h\u1ee3p khi\u1ebfn vi\u1ec7c h\u1ecdc h\xe0nh v\xe0 ph\xe1t tri\u1ec3n tr\xed tu\u1ec7 g\u1eb7p nhi\u1ec1u c\u1ea3n tr\u1edf \u2014 b\u1ea1n c\xf3 th\u1ec3 n\u1ed7 l\u1ef1c nh\u01b0ng k\u1ebft qu\u1ea3 th\u01b0\u1eddng kh\xf4ng x\u1ee9ng v\u1edbi c\xf4ng s\u1ee9c b\u1ecf ra, v\xe0 \u0111i\u1ec1u \u0111\xf3 t\u1ea1o ra m\u1ed9t s\u1ef1 \u1ee9c ch\u1ebf \xe2m \u1ec9 b\xean trong. T\xednh kh\xed d\u1ec5 b\u1ef1c b\u1ed9i, d\u1ec5 c\xe1u k\u1ec9nh, \u0111\u1eb7c bi\u1ec7t khi m\u1ecdi vi\u1ec7c kh\xf4ng \u0111i theo k\u1ef3 v\u1ecdng. H\xf3a K\u1ef5 \u1edf \u0111\xe2y l\xe0m cho m\u1ecdi chuy\u1ec7n nh\u01b0 b\u1ecb ch\u1eb7n l\u1ea1i, t\u1ea1o c\u1ea3m gi\xe1c b\u1ebf t\u1eafc, t\u1eeb \u0111\xf3 r\u1ea5t d\u1ec5 d\u1eabn \u0111\u1ebfn stress m\xe3n t\xednh v\xe0 tr\u1ea7m c\u1ea3m. B\u1ea1n c\u1ea7n t\u1eadp ch\u1ea5p nh\u1eadn r\u1eb1ng kh\xf4ng ph\u1ea3i m\u1ecdi n\u1ed7 l\u1ef1c \u0111\u1ec1u cho ra k\u1ebft qu\u1ea3 ngay l\u1eadp t\u1ee9c, v\xe0 h\u1ecdc c\xe1ch bu\xf4ng b\u1ecf nh\u1eefng g\xec kh\xf4ng n\u1eb1m trong t\u1ea7m ki\u1ec3m so\xe1t c\u1ee7a m\xecnh."],d4,d4),a3,A.p(["M\u1ec7nh","D\xf9 b\u1ea3n t\xednh v\u1eabn c\xf2n \u0111\xf3 s\u1ef1 b\u1ed9c tr\u1ef1c v\xe0 \u0111\xf4i khi c\u1ee9ng \u0111\u1ea7u, nh\u01b0ng \u0111\u01b0\u01a1ng s\u1ed1 \u0111\u01b0\u1ee3c h\u01b0\u1edfng s\u1ef1 che ch\u1edf r\xf5 r\xe0ng t\u1eeb nh\u1eefng qu\xfd nh\xe2n c\xf3 danh ph\u1eadn, c\xf3 v\u1ecb th\u1ebf trong x\xe3 h\u1ed9i. Nh\u1eefng ng\u01b0\u1eddi n\xe0y kh\xf4ng ch\u1ec9 gi\xfap b\u1ea1n trong l\xfac kh\xf3 kh\u0103n m\xe0 c\xf2n mang l\u1ea1i cho b\u1ea1n s\u1ef1 ch\xednh danh, \u0111\u01b0\u1ee3c c\xf4ng nh\u1eadn trong nh\u1eefng vi\u1ec7c b\u1ea1n l\xe0m. \xc2n Quang b\u1ed5 tr\u1ee3 th\xeam m\u1ed9t l\u1edbp ph\u01b0\u1edbc l\xe0nh \u2014 b\u1ea1n th\u01b0\u1eddng g\u1eb7p \u0111\u01b0\u1ee3c nh\u1eefng ng\u01b0\u1eddi c\xf3 l\xf2ng t\u1ed1t th\u1eadt s\u1ef1, kh\xf4ng v\u1ee5 l\u1ee3i, s\u1eb5n s\xe0ng ra tay gi\xfap \u0111\u1ee1 \u0111\xfang l\xfac. T\xednh hung h\u0103ng \u0111\u01b0\u1ee3c h\xf3a gi\u1ea3i \u0111\xe1ng k\u1ec3, cu\u1ed9c s\u1ed1ng tuy kh\xf4ng b\u1eb1ng ph\u1eb3ng ho\xe0n to\xe0n nh\u01b0ng lu\xf4n c\xf3 ng\u01b0\u1eddi n\xe2ng \u0111\u1ee1 qua c\u01a1n kh\xf3."],d4,d4),a4,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 ph\u1ea7n hung h\u0103ng v\xe0 b\u1ed1c \u0111\u1ed3ng \u0111\u01b0\u1ee3c k\xe9o gi\u1ea3m b\u1edbt nh\u1edd s\u1ef1 xu\u1ea5t hi\u1ec7n c\u1ee7a qu\xfd nh\xe2n c\xf3 danh ph\u1eadn. Thi\xean Kh\xf4i mang \u0111\u1ebfn s\u1ef1 ch\xednh danh, gi\xfap b\u1ea1n \u0111\u01b0\u1ee3c nh\xe0 n\u01b0\u1edbc ho\u1eb7c t\u1ed5 ch\u1ee9c c\xf3 th\u1ea9m quy\u1ec1n c\xf4ng nh\u1eadn, c\xf2n Thi\xean Qu\xfd ti\u1ebfp th\xeam m\u1ed9t t\u1ea7ng ph\u01b0\u1edbc l\xe0nh n\u1eefa \u2014 b\u1ea1n th\u01b0\u1eddng g\u1eb7p ng\u01b0\u1eddi c\xf3 c\u0103n tu, c\xf3 t\xe2m thi\u1ec7n, s\u1eb5n s\xe0ng l\xe0 ch\u1ed7 d\u1ef1a tinh th\u1ea7n cho b\u1ea1n. S\u1ef1 k\u1ebft h\u1ee3p n\xe0y gi\xfap b\u1ea1n tr\xe1nh \u0111\u01b0\u1ee3c nhi\u1ec1u tai \u01b0\u01a1ng do b\u1ea3n t\xednh li\u1ec1u l\u0129nh g\xe2y ra, v\xe0 thay v\xe0o \u0111\xf3 bi\u1ebft t\u1eadn d\u1ee5ng c\u01a1 h\u1ed9i m\u1ed9t c\xe1ch kh\xf4n ngoan h\u01a1n. D\xf9 kh\xf4ng ho\xe0n to\xe0n an to\xe0n, nh\u01b0ng cu\u1ed9c \u0111\u1eddi b\u1ea1n lu\xf4n c\xf3 ng\u01b0\u1eddi che ch\u1edf \u0111\xfang l\xfac."],d4,d4),a5,A.p(["M\u1ec7nh","Thi\xean Vi\u1ec7t mang \u0111\u1ebfn cho \u0111\u01b0\u01a1ng s\u1ed1 nh\u1eefng qu\xfd nh\xe2n t\u1eeb ph\xeda n\u1eef gi\u1edbi ho\u1eb7c nh\u1eefng ng\u01b0\u1eddi c\xf3 t\xecnh c\u1ea3m ch\xe2n th\xe0nh, trong khi \xc2n Quang g\u1ee3i l\xean m\u1ed9t lo\u1ea1i ph\u01b0\u1edbc l\xe0nh mang t\xednh t\xe2m linh, c\u1ee9u c\xe1nh trong nh\u1eefng l\xfac c\xf9ng \u0111\u01b0\u1eddng. T\xednh li\u1ec1u l\u0129nh v\xe0 b\u1ed9c tr\u1ef1c t\u1eeb \u0110\u1ecba Kh\xf4ng \u0111\xe3 \u0111\u01b0\u1ee3c \u0111i\u1ec1u ti\u1ebft nh\u1edd (\u0110), n\xean b\u1ea1n v\u1eabn d\xe1m ngh\u0129 d\xe1m l\xe0m nh\u01b0ng \xedt khi \u0111i \u0111\u1ebfn m\u1ee9c ph\xe1 v\u1ee1 m\u1ecdi th\u1ee9. S\u1ef1 gi\xfap \u0111\u1ee1 \u0111\u1ebfn v\u1edbi b\u1ea1n th\u01b0\u1eddng r\u1ea5t t\u1ef1 nhi\xean, kh\xf4ng c\u1ea7n c\u1ea7u xin \u2014 ng\u01b0\u1eddi ta th\u1ea5y b\u1ea1n c\u1ea7n l\xe0 h\u1ecd t\u1ef1 gi\u01a1 tay. \u0110\xe2y l\xe0 l\xe1 s\u1ed1 c\xf3 ph\u01b0\u1edbc nh\xe2n duy\xean t\u1ed1t, bi\u1ebft tr\xe2n tr\u1ecdng th\xec s\u1ebd \u0111\u01b0\u1ee3c d\xf9ng su\u1ed1t \u0111\u1eddi."],d4,d4),a6,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 \u0111\u01b0\u1ee3c bao b\u1ecdc b\u1edfi nh\u1eefng qu\xfd nh\xe2n c\xf3 t\xecnh ngh\u0129a v\xe0 c\xf3 c\u0103n tu, gi\xfap h\xf3a gi\u1ea3i ph\u1ea7n l\u1edbn s\u1ef1 hung h\u0103ng v\xe0 li\u1ec1u l\u0129nh v\u1ed1n c\xf3. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn s\u1ef1 h\u1ed7 tr\u1ee3 t\u1eeb nh\u1eefng ng\u01b0\u1eddi ch\xe2n th\xe0nh, c\xf2n Thi\xean Qu\xfd l\xe0m cho b\u1ea1n c\xf3 m\u1ed9t s\u1ee9c h\xfat nh\u1ea5t \u0111\u1ecbnh v\u1edbi nh\u1eefng ng\u01b0\u1eddi t\u1ed1t b\u1ee5ng, c\xf3 \u0111\u1ea1o \u0111\u1ee9c. Nh\u1edd (\u0110), b\u1ea1n bi\u1ebft ki\u1ec3m so\xe1t b\u1ea3n th\xe2n h\u01a1n so v\u1edbi ng\u01b0\u1eddi kh\xf4ng c\xf3, v\xe0 khi k\u1ebft h\u1ee3p v\u1edbi hai ng\xf4i sao qu\xfd nh\xe2n n\xe0y, b\u1ea1n th\u01b0\u1eddng tho\xe1t kh\u1ecfi nh\u1eefng t\xecnh hu\u1ed1ng nguy hi\u1ec3m m\u1ed9t c\xe1ch kh\xe1 \xeam th\u1ea5m. Cu\u1ed9c s\u1ed1ng v\u1eabn c\xf3 s\xf3ng gi\xf3 nh\u01b0ng kh\xf4ng \u0111\u1ebfn m\u1ee9c b\u1ecb ch\xecm."],d4,d4),a7,A.p(["M\u1ec7nh","\u0110\u1ecba Ki\u1ebfp v\u1ed1n mang t\xednh \u0111\u1ed9t ng\u1ed9t, hay t\u1ea1o ra nh\u1eefng c\xfa s\u1ed1c b\u1ea5t ng\u1edd trong cu\u1ed9c \u0111\u1eddi, nh\u01b0ng khi c\xf3 (\u0110), s\u1ef1 b\u1ed9c ph\xe1t \u1ea5y \u0111\u01b0\u1ee3c ki\u1ec1m ch\u1ebf l\u1ea1i ph\u1ea7n n\xe0o, b\u1ea1n chi ti\xeau v\xe0 h\xe0nh \u0111\u1ed9ng c\xf3 c\xe2n nh\u1eafc h\u01a1n. Thi\xean Kh\xf4i mang \u0111\u1ebfn qu\xfd nh\xe2n ch\xednh danh, nh\u1eefng ng\u01b0\u1eddi c\xf3 th\u1ec3 \u0111\u1ee9ng ra b\u1ea3o ch\u1ee9ng cho b\u1ea1n, gi\xfap b\u1ea1n \u0111\u01b0\u1ee3c c\xf4ng nh\u1eadn trong x\xe3 h\u1ed9i. \xc2n Quang b\u1ed5 sung th\xeam l\u1edbp b\u1ea3o h\u1ed9 mang t\xednh t\xe2m linh v\xe0 ph\u01b0\u1edbc l\xe0nh \u2014 trong nh\u1eefng l\xfac b\u1ea1n t\u01b0\u1edfng nh\u01b0 kh\xf4ng c\xf2n \u0111\u01b0\u1eddng ra, th\u01b0\u1eddng s\u1ebd c\xf3 ng\u01b0\u1eddi ho\u1eb7c c\u01a1 h\u1ed9i xu\u1ea5t hi\u1ec7n \u0111\xfang l\xfac. \u0110\xe2y l\xe0 l\xe1 s\u1ed1 c\xf3 v\u1ea5t v\u1ea3 nh\u01b0ng lu\xf4n c\xf3 ng\u01b0\u1eddi \u0111\u1ee1."],d4,d4),a8,A.p(["M\u1ec7nh","S\u1ef1 \u0111\u1ed9t ng\u1ed9t v\xe0 t\xednh to\xe1n ph\u1ee9c t\u1ea1p c\u1ee7a \u0110\u1ecba Ki\u1ebfp \u0111\u01b0\u1ee3c \u0111i\u1ec1u ti\u1ebft b\u1edbt nh\u1edd (\u0110), gi\xfap \u0111\u01b0\u01a1ng s\u1ed1 h\xe0nh \u0111\u1ed9ng c\xf3 b\xe0i b\u1ea3n h\u01a1n thay v\xec ch\u1ec9 ph\u1ea3n \u1ee9ng theo b\u1ea3n n\u0103ng. Thi\xean Kh\xf4i \u0111\u1ee9ng ra \u0111\u1ea3m b\u1ea3o cho b\u1ea1n s\u1ef1 ch\xednh danh, c\xf2n Thi\xean Qu\xfd mang \u0111\u1ebfn nh\u1eefng ng\u01b0\u1eddi c\xf3 t\xe2m thi\u1ec7n, kh\xf4ng v\u1ee5 l\u1ee3i, th\u01b0\u1eddng xu\u1ea5t hi\u1ec7n \u0111\xfang l\xfac b\u1ea1n c\u1ea7n m\u1ed9t l\u1eddi khuy\xean hay m\u1ed9t b\xe0n tay. Hai ng\xf4i sao qu\xfd nh\xe2n n\xe0y h\xf3a gi\u1ea3i \u0111\xe1ng k\u1ec3 t\xednh hung c\u1ee7a \u0110\u1ecba Ki\u1ebfp, khi\u1ebfn cho nh\u1eefng bi\u1ebfn c\u1ed1 d\xf9 c\xf3 x\u1ea3y ra c\u0169ng th\u01b0\u1eddng \u0111\u01b0\u1ee3c gi\u1ea3i quy\u1ebft \xeam \xe1i h\u01a1n. B\u1ea1n v\u1eabn ph\u1ea3i tr\u1ea3i qua th\u1eed th\xe1ch, nh\u01b0ng kh\xf4ng ph\u1ea3i \u0111i m\u1ed9t m\xecnh."],d4,d4),a9,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 xu h\u01b0\u1edbng t\u01b0 duy ph\u1ee9c t\u1ea1p v\xe0 \u0111\xf4i khi \u0111i \u0111\u01b0\u1eddng v\xf2ng trong m\u1ecdi vi\u1ec7c, nh\u01b0ng nh\u1edd (\u0110), b\u1ea1n \u0111\xe3 c\xf3 ph\u1ea7n k\u1ef7 lu\u1eadt h\u01a1n trong c\xe1ch ti\xeau ti\u1ec1n v\xe0 ra quy\u1ebft \u0111\u1ecbnh. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n t\xecnh ngh\u0129a, th\u01b0\u1eddng l\xe0 ph\u1ee5 n\u1eef ho\u1eb7c ng\u01b0\u1eddi c\xf3 l\xf2ng nh\xe2n h\u1eadu, s\u1eb5n s\xe0ng gi\xfap \u0111\u1ee1 b\u1ea1n kh\xf4ng t\xednh to\xe1n. \xc2n Quang th\xeam v\xe0o \u0111\xf3 m\u1ed9t t\u1ea7ng ph\u01b0\u1edbc l\xe0nh s\xe2u h\u01a1n \u2014 b\u1ea1n c\xf3 c\u0103n tu, c\xf3 l\xf2ng nh\xe2n, v\xe0 ch\xednh \u0111i\u1ec1u \u0111\xf3 thu h\xfat nh\u1eefng ng\u01b0\u1eddi t\u1ed1t l\u1ea1i g\u1ea7n. Cu\u1ed9c \u0111\u1eddi c\xf3 nh\u1eefng kh\xfac quanh b\u1ea5t ng\u1edd nh\u01b0ng hi\u1ebfm khi b\u1ecb b\u1ecf l\u1ea1i m\u1ed9t m\xecnh."],d4,d4),b0,A.p(["M\u1ec7nh","\u0110\u1ecba Ki\u1ebfp mang theo s\u1ef1 bi\u1ebfn \u0111\u1ed9ng v\xe0 t\xednh to\xe1n nhi\u1ec1u chi\u1ec1u, nh\u01b0ng khi c\xf3 (\u0110), b\u1ea1n kh\xf4ng \u0111\u1ebfn m\u1ee9c h\xe0nh x\u1eed li\u1ec1u l\u0129nh m\xe0 thay v\xe0o \u0111\xf3 c\xf3 th\u1ec3 d\xf9ng s\u1ef1 nh\u1ea1y b\xe9n \u1ea5y v\xe0o nh\u1eefng vi\u1ec7c c\xf3 gi\xe1 tr\u1ecb. Thi\xean Vi\u1ec7t v\xe0 Thi\xean Qu\xfd c\xf9ng l\xfac c\xf3 m\u1eb7t l\xe0 m\u1ed9t ph\u01b0\u1edbc l\u1edbn \u2014 qu\xfd nh\xe2n \u0111\u1ebfn t\u1eeb nhi\u1ec1u h\u01b0\u1edbng, c\xf3 ng\u01b0\u1eddi gi\xfap b\u1ea1n v\u1ec1 danh ph\u1eadn, c\xf3 ng\u01b0\u1eddi gi\xfap b\u1ea1n v\u1ec1 tinh th\u1ea7n v\xe0 t\xe2m linh. Hai ng\xf4i sao n\xe0y l\xe0m d\u1ecbu \u0111i ph\u1ea7n hung h\u0103ng c\u1ee7a \u0110\u1ecba Ki\u1ebfp m\u1ed9t c\xe1ch hi\u1ec7u qu\u1ea3, gi\xfap b\u1ea1n s\u1ed1ng c\xf3 chi\u1ec1u s\xe2u h\u01a1n, bi\u1ebft ngh\u0129 cho ng\u01b0\u1eddi kh\xe1c h\u01a1n. \u0110\xe2y l\xe0 l\xe1 s\u1ed1 tuy c\xf3 s\xf3ng nh\u01b0ng l\u1ea1i c\xf3 nhi\u1ec1u ng\u01b0\u1eddi mu\u1ed1n \u0111\u1ee9ng sau l\u01b0ng b\u1ea1n."],d4,d4),b1,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 mang t\xednh n\xf3ng n\u1ea3y, hay so \u0111o t\xednh to\xe1n v\xe0 th\xedch \u0111i \u0111\u01b0\u1eddng v\xf2ng h\u01a1n \u0111\u01b0\u1eddng th\u1eb3ng \u2014 nh\u01b0ng khi Thi\xean Kh\xf4i v\xe0 Thi\xean Qu\xfd c\xf9ng c\xf3 m\u1eb7t, nh\u1eefng t\xednh c\xe1ch \u1ea5y \u0111\u01b0\u1ee3c ki\u1ec1m ch\u1ebf v\xe0 d\u1eabn h\u01b0\u1edbng l\u1ea1i. Qu\xfd nh\xe2n \u0111\u1ebfn v\u1edbi b\u1ea1n t\u1eeb c\u1ea3 hai ph\xeda: ng\u01b0\u1eddi c\xf3 danh ph\u1eadn ch\xednh th\u1ed1ng l\u1eabn ng\u01b0\u1eddi c\xf3 c\u0103n l\xe0nh, t\xe2m thi\u1ec7n. Hai b\u1ed9 sao n\xe0y \u0111\u1ee7 m\u1ea1nh \u0111\u1ec3 h\xf3a gi\u1ea3i ph\u1ea7n l\u1edbn t\xednh hung c\u1ee7a \u0110\u1ecba Kh\xf4ng, gi\xfap b\u1ea1n bi\u1ebft d\u1eebng l\u1ea1i \u0111\xfang l\xfac thay v\xec c\u1ee9 lao \u0111\u1ea7u v\xe0o. Tuy kh\xf4ng c\xf3 (\u0110) n\xean b\u1ea1n v\u1eabn c\xf2n d\u1ec5 ti\xeau x\xe0i v\xe0 b\u1ed1c \u0111\u1ed3ng, nh\u01b0ng nh\u1edd qu\xfd nh\xe2n che ch\u1edf, b\u1ea1n \xedt khi ph\u1ea3i g\xe1nh h\u1eadu qu\u1ea3 m\u1ed9t m\xecnh."],d4,d4),b2,A.p(["M\u1ec7nh","B\u1ea1n c\xf3 t\u01b0 duy ph\xf3ng kho\xe1ng, th\xedch l\xe0m nh\u1eefng g\xec ng\u01b0\u1eddi kh\xe1c kh\xf4ng d\xe1m, nh\u01b0ng c\u0169ng hay l\xe3ng ph\xed v\xe0 kh\xf3 gi\u1eef ti\u1ec1n. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n ch\xe2n t\xecnh, th\u01b0\u1eddng l\xe0 nh\u1eefng ng\u01b0\u1eddi \xe2m th\u1ea7m gi\xfap \u0111\u1ee1 kh\xf4ng c\u1ea7n \u0111\u01b0\u1ee3c bi\u1ebft \u01a1n, c\xf2n \xc2n Quang g\u1ee3i l\xean m\u1ed9t lo\u1ea1i ph\u01b0\u1edbc l\xe0nh mang h\u01a1i h\u01b0\u1edbng t\xe2m linh \u2014 b\u1ea1n c\xf3 l\xf2ng nh\xe2n v\xe0 \u0111i\u1ec1u \u0111\xf3 thu h\xfat s\u1ef1 gi\xfap \u0111\u1ee1 ch\xe2n th\xe0nh v\u1ec1 ph\xeda m\xecnh. Tuy nhi\xean v\xec kh\xf4ng c\xf3 (\u0110), t\xednh b\u1ed1c \u0111\u1ed3ng v\xe0 d\u1ec5 x\xe0i hoang v\u1eabn c\xf2n \u0111\xf3, c\u1ea7n t\u1ef1 \xfd th\u1ee9c ki\u1ec3m so\xe1t nhi\u1ec1u h\u01a1n. Nh\xecn chung, \u0111\xe2y l\xe0 l\xe1 s\u1ed1 tuy c\xf3 hao t\u1ed5n nh\u01b0ng kh\xf4ng \u0111\u1ebfn m\u1ee9c c\xf4 \u0111\u01a1n trong c\u01a1n ho\u1ea1n n\u1ea1n."],d4,d4),b3,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 \u0111\u1ea7u \xf3c nhanh nh\u1ea1y trong th\u1eddi gian ng\u1eafn nh\u01b0ng l\u1ea1i thi\u1ebfu s\u1ef1 ki\xean nh\u1eabn \u0111\u1ec3 \u0111i \u0111\u01b0\u1eddng d\xe0i, k\u1ebft h\u1ee3p v\u1edbi t\xednh hay t\xednh to\xe1n l\xf2ng v\xf2ng khi\u1ebfn nhi\u1ec1u c\u01a1 h\u1ed9i b\u1ecb b\u1ecf l\u1ee1. Thi\xean Vi\u1ec7t v\xe0 Thi\xean Qu\xfd c\xf9ng l\xfac mang \u0111\u1ebfn hai l\u1edbp qu\xfd nh\xe2n: ng\u01b0\u1eddi gi\xfap v\u1ec1 t\xecnh c\u1ea3m v\xe0 ng\u01b0\u1eddi gi\xfap v\u1ec1 t\xe2m linh, c\u1ea3 hai \u0111\u1ec1u h\xf3a gi\u1ea3i ph\u1ea7n hung c\u1ee7a \u0110\u1ecba Kh\xf4ng m\u1ed9t c\xe1ch hi\u1ec7u qu\u1ea3. B\u1ea1n th\u01b0\u1eddng \u0111\u01b0\u1ee3c ng\u01b0\u1eddi kh\xe1c y\xeau m\u1ebfn d\xf9 b\u1ea3n t\xednh \u0111\xf4i khi kh\xf3 ch\u1ecbu, v\xe0 hay g\u1eb7p \u0111\u01b0\u1ee3c ng\u01b0\u1eddi \u0111\u1ee9ng ra che ch\u1eafn cho m\xecnh \u0111\xfang l\xfac. N\u1ebfu bi\u1ebft tr\xe2n tr\u1ecdng nh\u1eefng m\u1ed1i quan h\u1ec7 n\xe0y, b\u1ea1n s\u1ebd ti\u1ebft ki\u1ec7m \u0111\u01b0\u1ee3c r\u1ea5t nhi\u1ec1u c\xf4ng s\u1ee9c trong cu\u1ed9c \u0111\u1eddi."],d4,d4),b4,A.p(["M\u1ec7nh","\u0110\u1ecba Ki\u1ebfp kh\xf4ng c\xf3 (\u0110) mang theo t\xednh n\xf3ng, hay l\xe8m b\xe8m v\xe0 suy ngh\u0129 ph\u1ee9c t\u1ea1p \u2014 b\u1ea1n th\u01b0\u1eddng kh\xf4ng \u0111i th\u1eb3ng v\xe0o v\u1ea5n \u0111\u1ec1 m\xe0 lu\xf4n c\xf3 nhi\u1ec1u b\u01b0\u1edbc v\xf2ng, nhi\u1ec1u t\xednh to\xe1n. Tuy nhi\xean, Thi\xean Kh\xf4i \u0111\u1ee9ng ra b\u1ea3o ch\u1ee9ng cho b\u1ea1n s\u1ef1 ch\xednh danh v\xe0 s\u1ef1 c\xf4ng nh\u1eadn t\u1eeb nh\u1eefng ng\u01b0\u1eddi c\xf3 v\u1ecb th\u1ebf, c\xf2n \xc2n Quang mang \u0111\u1ebfn m\u1ed9t t\u1ea7ng ph\u01b0\u1edbc l\xe0nh \u0111\u1eb7c bi\u1ec7t \u2014 khi b\u1ea1n c\xf9ng \u0111\u01b0\u1eddng th\xec th\u01b0\u1eddng c\xf3 ng\u01b0\u1eddi ho\u1eb7c c\u01a1 h\u1ed9i xu\u1ea5t hi\u1ec7n nh\u01b0 m\u1ed9t c\u1ee9u c\xe1nh. Hai ng\xf4i sao n\xe0y \u0111\u1ee7 \u0111\u1ec3 h\xf3a gi\u1ea3i t\xednh hung c\u1ee7a \u0110\u1ecba Ki\u1ebfp, gi\xfap b\u1ea1n kh\xf4ng b\u1ecb bi\u1ebfn c\u1ed1 nh\u1ea5n ch\xecm ho\xe0n to\xe0n. Nh\u01b0ng v\xec thi\u1ebfu (\u0110), b\u1ea1n v\u1eabn c\u1ea7n t\u1ef1 \xfd th\u1ee9c ki\u1ec3m so\xe1t t\xe0i ch\xednh v\xe0 c\u1ea3m x\xfac."],d4,d4),b5,A.p(["M\u1ec7nh","B\u1ea1n c\xf3 t\xednh n\xf3ng, hay l\u1eafm chuy\u1ec7n v\xe0 th\xedch \u0111i \u0111\u01b0\u1eddng t\u1eaft h\u01a1n \u0111\u01b0\u1eddng th\u1eb3ng \u2014 \u0111\xe2y l\xe0 t\xednh c\u1ee7a \u0110\u1ecba Ki\u1ebfp khi kh\xf4ng c\xf3 s\u1ef1 \u0111i\u1ec1u ti\u1ebft. Nh\u01b0ng khi Thi\xean Kh\xf4i v\xe0 Thi\xean Qu\xfd c\xf9ng xu\u1ea5t hi\u1ec7n, ch\xfang t\u1ea1o th\xe0nh m\u1ed9t l\u1edbp b\u1ea3o h\u1ed9 m\u1ea1nh m\u1ebd: m\u1ed9t b\xean mang \u0111\u1ebfn qu\xfd nh\xe2n ch\xednh danh, m\u1ed9t b\xean mang \u0111\u1ebfn ng\u01b0\u1eddi c\xf3 t\xe2m thi\u1ec7n v\xe0 c\u0103n tu. Hai l\u1edbp qu\xfd nh\xe2n n\xe0y \u0111\u1ee7 s\u1ee9c h\xf3a gi\u1ea3i ph\u1ea7n l\u1edbn t\xednh hung h\u0103ng c\u1ee7a \u0110\u1ecba Ki\u1ebfp, gi\xfap nh\u1eefng quy\u1ebft \u0111\u1ecbnh li\u1ec1u l\u0129nh c\u1ee7a b\u1ea1n \xedt khi d\u1eabn \u0111\u1ebfn h\u1eadu qu\u1ea3 kh\xf4ng th\u1ec3 c\u1ee9u v\xe3n. B\u1ea1n v\u1eabn c\u1ea7n h\u1ecdc c\xe1ch \u0111i th\u1eb3ng v\xe0 s\u1ed1ng \u0111\u01a1n gi\u1ea3n h\u01a1n, nh\u01b0ng cu\u1ed9c \u0111\u1eddi th\u01b0\u1eddng c\xf3 ng\u01b0\u1eddi che ch\u1edf."],d4,d4),b6,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 t\u01b0 duy v\xf2ng vo, hay t\xednh to\xe1n nhi\u1ec1u chi\u1ec1u v\xe0 d\u1ec5 ngh\u0129 \u1ea9u l\xe0m li\u1ec1u khi b\u1ecb k\xedch \u0111\u1ed9ng \u2014 \u0111\xe2y l\xe0 m\u1eb7t t\u1ed1i c\u1ee7a \u0110\u1ecba Ki\u1ebfp khi thi\u1ebfu s\u1ef1 \u0111i\u1ec1u ti\u1ebft. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n t\xecnh ngh\u0129a, th\u01b0\u1eddng che ch\u1edf b\u1ea1n m\u1ed9t c\xe1ch \xe2m th\u1ea7m, c\xf2n \xc2n Quang th\xeam v\xe0o \u0111\xf3 m\u1ed9t l\u1edbp ph\u01b0\u1edbc l\xe0nh t\xe2m linh gi\xfap b\u1ea1n g\u1eb7p \u0111\u01b0\u1ee3c ng\u01b0\u1eddi c\xf3 l\xf2ng t\u1ed1t th\u1eadt s\u1ef1 trong nh\u1eefng l\xfac c\u1ea7n nh\u1ea5t. Hai ng\xf4i sao n\xe0y l\xe0m d\u1ecbu t\xednh hung c\u1ee7a \u0110\u1ecba Ki\u1ebfp, nh\u01b0ng kh\xf4ng tri\u1ec7t ti\xeau ho\xe0n to\xe0n \u2014 b\u1ea1n v\u1eabn c\u1ea7n t\u1ef1 r\xe8n luy\u1ec7n t\xednh ki\xean nh\u1eabn v\xe0 bi\u1ebft \u0111i th\u1eb3ng h\u01a1n. Ph\u01b0\u1edbc l\xe0nh v\u1eabn c\xf2n \u0111\xf3, ch\u1ec9 c\u1ea7n b\u1ea1n bi\u1ebft nh\u1eadn ra."],d4,d4),b7,A.p(["M\u1ec7nh","B\u1ea1n c\xf3 \u0111\u1ea7u \xf3c nh\u1ea1y b\xe9n nh\u01b0ng l\u1ea1i th\xedch l\xe0m nh\u1eefng vi\u1ec7c khu\u1ea5t kh\xfac, hay so \u0111o t\xednh to\xe1n v\xe0 ti\xeau ti\u1ec1n kh\xf4ng c\xf3 k\u1ebf ho\u1ea1ch \u2014 t\xednh c\u1ee7a \u0110\u1ecba Ki\u1ebfp khi kh\xf4ng c\xf3 s\u1ef1 ki\u1ec3m so\xe1t. Thi\xean Vi\u1ec7t v\xe0 Thi\xean Qu\xfd c\xf9ng l\xfac c\xf3 m\u1eb7t t\u1ea1o th\xe0nh m\u1ed9t v\xf2ng b\u1ea3o h\u1ed9 \u0111\xf4i: ng\u01b0\u1eddi th\xe2n t\xecnh gi\xfap \u0111\u1ee1 t\u1eeb ph\xeda n\xe0y, ng\u01b0\u1eddi c\xf3 c\u0103n tu v\xe0 t\xe2m thi\u1ec7n n\xe2ng \u0111\u1ee1 t\u1eeb ph\xeda kia. C\u1ea3 hai \u0111\u1ec1u \u0111\u1ee7 m\u1ea1nh \u0111\u1ec3 h\xf3a gi\u1ea3i ph\u1ea7n hung h\u0103ng v\u1ed1n c\xf3, gi\xfap b\u1ea1n \xedt khi ph\u1ea3i ch\u1ecbu \u0111\u1ef1ng h\u1eadu qu\u1ea3 n\u1eb7ng n\u1ec1 m\u1ed9t m\xecnh. Tuy nhi\xean, \u0111\u1ec3 th\u1eadt s\u1ef1 h\u01b0\u1edfng \u0111\u01b0\u1ee3c ph\u01b0\u1edbc n\xe0y l\xe2u d\xe0i, b\u1ea1n c\u1ea7n h\u1ecdc c\xe1ch bi\u1ebft \u01a1n v\xe0 s\u1ed1ng ngay th\u1eb3ng h\u01a1n trong t\u1eebng ng\xe0y."],d4,d4),b8,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 v\u1eabn c\xf2n t\xednh li\u1ec1u l\u0129nh v\xe0 th\xedch l\xe0m nh\u1eefng vi\u1ec7c v\u01b0\u1ee3t khu\xf4n kh\u1ed5, nh\u01b0ng nh\u1edd (\u0110), b\u1ea1n \u0111\xe3 bi\u1ebft c\xe2n nh\u1eafc h\u01a1n tr\u01b0\u1edbc khi h\xe0nh \u0111\u1ed9ng, kh\xf4ng c\xf2n b\u1ed1c \u0111\u1ed3ng ho\xe0n to\xe0n nh\u01b0 tr\u01b0\u1edbc. Thi\xean Kh\xf4i mang \u0111\u1ebfn s\u1ef1 ch\xednh danh v\xe0 qu\xfd nh\xe2n c\xf3 v\u1ecb th\u1ebf \u2014 b\u1ea1n th\u01b0\u1eddng \u0111\u01b0\u1ee3c ng\u01b0\u1eddi c\xf3 quy\u1ec1n l\u1ef1c ho\u1eb7c t\u1ed5 ch\u1ee9c l\u1edbn c\xf4ng nh\u1eadn v\xe0 h\u1ed7 tr\u1ee3, gi\xfap h\xf3a gi\u1ea3i t\xednh hung c\u1ee7a \u0110\u1ecba Kh\xf4ng. T\xe0i ch\xednh v\u1eabn c\xf3 xu h\u01b0\u1edbng ra v\xe0o b\u1ea5t th\u01b0\u1eddng nh\u01b0ng kh\xf4ng \u0111\u1ebfn m\u1ee9c ph\xe1 s\u1ea3n, v\xec lu\xf4n c\xf3 ng\u01b0\u1eddi ho\u1eb7c c\u01a1 h\u1ed9i \u0111\u1ee1 l\u1ea1i \u0111\xfang l\xfac. \u0110\xe2y l\xe0 l\xe1 s\u1ed1 d\xe1m ngh\u0129 d\xe1m l\xe0m v\xe0 c\xf3 ng\u01b0\u1eddi \u0111\u1ee9ng sau l\u01b0ng."],d4,d4),b9,A.p(["M\u1ec7nh","T\xednh li\u1ec1u l\u0129nh v\xe0 ph\xf3ng kho\xe1ng \u0111\u01b0\u1ee3c \u0111i\u1ec1u ti\u1ebft b\u1edfi (\u0110), gi\xfap b\u1ea1n kh\xf4ng \u0111\u1ebfn m\u1ee9c l\xe0m li\u1ec1u ho\xe0n to\xe0n m\xe0 v\u1eabn c\xf2n bi\u1ebft \u0111o l\u01b0\u1eddng. \xc2n Quang mang \u0111\u1ebfn ph\u01b0\u1edbc l\xe0nh t\xe2m linh \u2014 b\u1ea1n c\xf3 l\xf2ng nh\xe2n, c\xf3 c\u0103n tu \u1ea9n v\xe0 \u0111i\u1ec1u \u0111\xf3 thu h\xfat nh\u1eefng ng\u01b0\u1eddi t\u1ed1t b\u1ee5ng \u0111\u1ebfn v\u1edbi m\xecnh m\u1ed9t c\xe1ch t\u1ef1 nhi\xean. Trong nh\u1eefng l\xfac kh\xf3 kh\u0103n nh\u1ea5t, th\u01b0\u1eddng c\xf3 m\u1ed9t s\u1ef1 ki\u1ec7n ho\u1eb7c con ng\u01b0\u1eddi xu\u1ea5t hi\u1ec7n nh\u01b0 m\u1ed9t c\u1ee9u c\xe1nh m\xe0 b\u1ea1n kh\xf4ng ng\u1edd \u0111\u1ebfn. Tuy nhi\xean, qu\xfd nh\xe2n \u1edf \u0111\xe2y kh\xf4ng h\u1eb3n l\xe0 ng\u01b0\u1eddi c\xf3 ch\u1ee9c quy\u1ec1n m\xe0 thi\xean v\u1ec1 ng\u01b0\u1eddi c\xf3 l\xf2ng t\u1ed1t ch\xe2n th\xe0nh \u2014 b\u1ea1n c\u1ea7n bi\u1ebft nh\u1eadn ra v\xe0 tr\xe2n tr\u1ecdng h\u1ecd."],d4,d4),c0,A.p(["M\u1ec7nh","Nh\u1edd (\u0110), b\u1ea1n \u0111\xe3 b\u1edbt b\u1ed9c ph\xe1t v\xe0 chi ti\xeau c\xf3 k\u1ebf ho\u1ea1ch h\u01a1n, d\xf9 b\u1ea3n t\xednh v\u1eabn c\xf2n th\xedch l\xe0m nh\u1eefng vi\u1ec7c kh\xe1c ng\u01b0\u1eddi. Thi\xean Qu\xfd mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n c\xf3 c\u0103n tu, c\xf3 t\xednh Ph\u1eadt, th\u01b0\u1eddng xu\u1ea5t hi\u1ec7n \u0111\u1ec3 gi\xfap b\u1ea1n t\xecm l\u1ea1i s\u1ef1 c\xe2n b\u1eb1ng khi b\u1ea1n \u0111ang \u0111i l\u1ec7ch h\u01b0\u1edbng. S\u1ef1 k\u1ebft h\u1ee3p n\xe0y h\xf3a gi\u1ea3i t\xednh hung c\u1ee7a \u0110\u1ecba Kh\xf4ng theo c\xe1ch nh\u1eb9 nh\xe0ng nh\u01b0ng s\xe2u s\u1eafc \u2014 kh\xf4ng ph\u1ea3i b\u1eb1ng quy\u1ec1n l\u1ef1c hay \u0111\u1ecba v\u1ecb m\xe0 b\u1eb1ng s\u1ef1 kh\xf4n ngoan v\xe0 l\xf2ng nh\xe2n \xe1i. B\u1ea1n th\u01b0\u1eddng \u0111\u01b0\u1ee3c g\u1eb7p nh\u1eefng ng\u01b0\u1eddi khi\u1ebfn m\xecnh d\u1eebng l\u1ea1i v\xe0 ngh\u0129, v\xe0 ch\xednh nh\u1eefng cu\u1ed9c g\u1eb7p g\u1ee1 \u1ea5y thay \u0111\u1ed5i cu\u1ed9c \u0111\u1eddi b\u1ea1n."],d4,d4),c1,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 t\xednh ph\xf3ng kho\xe1ng v\xe0 hay l\xe0m nh\u1eefng vi\u1ec7c v\u01b0\u1ee3t ngo\xe0i k\u1ef3 v\u1ecdng th\xf4ng th\u01b0\u1eddng, nh\u01b0ng nh\u1edd (\u0110), b\u1ea1n kh\xf4ng \u0111\u1ebfn m\u1ee9c hoang ph\xed ho\xe0n to\xe0n m\xe0 \u0111\xe3 bi\u1ebft ki\u1ec3m so\xe1t ph\u1ea7n n\xe0o. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn qu\xfd nh\xe2n t\u1eeb ph\xeda n\u1eef gi\u1edbi ho\u1eb7c nh\u1eefng ng\u01b0\u1eddi c\xf3 t\xecnh ngh\u0129a ch\xe2n th\xe0nh, th\u01b0\u1eddng ch\u1ee7 \u0111\u1ed9ng gi\xfap b\u1ea1n m\xe0 kh\xf4ng c\u1ea7n b\u1ea1n ph\u1ea3i c\u1ea7u xin. S\u1ef1 hi\u1ec7n di\u1ec7n c\u1ee7a Thi\xean Vi\u1ec7t \u0111\u1ee7 \u0111\u1ec3 h\xf3a gi\u1ea3i t\xednh hung c\u1ee7a \u0110\u1ecba Kh\xf4ng, t\u1ea1o ra m\u1ed9t l\u1edbp b\u1ea3o h\u1ed9 m\u1ec1m m\u1ea1i nh\u01b0ng v\u1eefng ch\u1eafc. B\u1ea1n c\xf3 xu h\u01b0\u1edbng \u0111\u01b0\u1ee3c y\xeau qu\xfd trong c\xe1c m\u1ed1i quan h\u1ec7 g\u1ea7n g\u0169i, v\xe0 ch\xednh nh\u1eefng ng\u01b0\u1eddi \u0111\xf3 l\xe0 \u0111i\u1ec3m t\u1ef1a quan tr\u1ecdng trong cu\u1ed9c \u0111\u1eddi."],d4,d4),c2,A.p(["M\u1ec7nh","T\xednh \u0111\u1ed9t ng\u1ed9t v\xe0 t\u01b0 duy ph\u1ee9c t\u1ea1p c\u1ee7a \u0110\u1ecba Ki\u1ebfp \u0111\u01b0\u1ee3c \u0111i\u1ec1u h\xf2a b\u1edbt nh\u1edd (\u0110), gi\xfap b\u1ea1n h\xe0nh \u0111\u1ed9ng c\xf3 k\u1ebf ho\u1ea1ch h\u01a1n thay v\xec ch\u1ec9 ph\u1ea3n \u1ee9ng theo b\u1ea3n n\u0103ng. Thi\xean Kh\xf4i mang \u0111\u1ebfn s\u1ef1 ch\xednh danh v\xe0 qu\xfd nh\xe2n c\xf3 v\u1ecb th\u1ebf \u2014 b\u1ea1n th\u01b0\u1eddng \u0111\u01b0\u1ee3c nh\u1eefng ng\u01b0\u1eddi c\xf3 quy\u1ec1n l\u1ef1c c\xf4ng nh\u1eadn ho\u1eb7c h\u1ed7 tr\u1ee3, v\xe0 \u0111i\u1ec1u \u0111\xf3 h\xf3a gi\u1ea3i \u0111\u01b0\u1ee3c ph\u1ea7n hung h\u0103ng v\u1ed1n c\xf3. T\xe0i ch\xednh tuy v\u1eabn c\xf3 l\xfac th\u1ea5t tho\xe1t b\u1ea5t ng\u1edd nh\u01b0ng lu\xf4n c\xf3 qu\xfd nh\xe2n k\u1ecbp th\u1eddi \u0111\u1ee9ng ra. \u0110\xe2y l\xe0 l\xe1 s\u1ed1 c\u1ee7a ng\u01b0\u1eddi v\u1eeba c\xf3 t\xe0i v\u1eeba \u0111\u01b0\u1ee3c \u0111\u1ee1 \u0111\u1ea7u \u2014 n\u1ebfu bi\u1ebft t\u1eadn d\u1ee5ng th\xec con \u0111\u01b0\u1eddng s\u1ef1 nghi\u1ec7p s\u1ebd kh\xe1 hanh th\xf4ng."],d4,d4),c3,A.p(["M\u1ec7nh","\u0110\u1ecba Ki\u1ebfp (\u0110) gi\xfap b\u1ea1n ki\u1ec3m so\xe1t ph\u1ea7n n\xe0o s\u1ef1 b\u1ed1c \u0111\u1ed3ng v\xe0 t\xednh to\xe1n nhi\u1ec1u chi\u1ec1u, nh\u01b0ng b\u1ea3n t\xednh v\u1eabn th\xedch \u0111i con \u0111\u01b0\u1eddng \xedt ai ngh\u0129 \u0111\u1ebfn. \xc2n Quang mang \u0111\u1ebfn m\u1ed9t lo\u1ea1i ph\u01b0\u1edbc l\xe0nh \u0111\u1eb7c bi\u1ec7t \u2014 b\u1ea1n c\xf3 l\xf2ng nh\xe2n trong ng\u01b0\u1eddi, c\xf3 c\u0103n tu \u1ea9n, v\xe0 \u0111i\u1ec1u \u0111\xf3 t\u1ea1o ra m\u1ed9t s\u1ee9c h\xfat v\xf4 h\xecnh v\u1edbi nh\u1eefng ng\u01b0\u1eddi t\u1ed1t b\u1ee5ng. Trong nh\u1eefng l\xfac t\u01b0\u1edfng nh\u01b0 b\u1ebf t\u1eafc, th\u01b0\u1eddng c\xf3 ng\u01b0\u1eddi ho\u1eb7c s\u1ef1 vi\u1ec7c xu\u1ea5t hi\u1ec7n gi\xfap b\u1ea1n tho\xe1t ra m\u1ed9t c\xe1ch b\u1ea5t ng\u1edd. Tuy nhi\xean b\u1ea1n c\u1ea7n b\u1edbt \u0111i \u0111\u01b0\u1eddng v\xf2ng v\xe0 h\u1ecdc c\xe1ch n\xf3i th\u1eb3ng \u2014 qu\xfd nh\xe2n s\u1ebd d\u1ec5 nh\u1eadn ra b\u1ea1n h\u01a1n khi b\u1ea1n s\u1ed1ng th\u1eadt h\u01a1n."],d4,d4),c4,A.p(["M\u1ec7nh","Nh\u1edd (\u0110), b\u1ea1n \u0111\xe3 bi\u1ebft c\xe2n nh\u1eafc h\u01a1n trong t\xe0i ch\xednh v\xe0 h\xe0nh \u0111\u1ed9ng, kh\xf4ng c\xf2n qu\xe1 li\u1ec1u l\u0129nh nh\u01b0 khi thi\u1ebfu s\u1ef1 \u0111i\u1ec1u ti\u1ebft. Thi\xean Qu\xfd mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n c\xf3 c\u0103n tu, c\xf3 t\xe2m thi\u1ec7n v\xe0 tr\xed tu\u1ec7 s\xe2u s\u1eafc \u2014 h\u1ecd th\u01b0\u1eddng xu\u1ea5t hi\u1ec7n trong cu\u1ed9c \u0111\u1eddi b\u1ea1n nh\u01b0 nh\u1eefng ng\u01b0\u1eddi th\u1ea7y ho\u1eb7c ng\u01b0\u1eddi b\u1ea1n t\xe2m giao, gi\xfap b\u1ea1n nh\xecn ra h\u01b0\u1edbng \u0111i \u0111\xfang \u0111\u1eafn. S\u1ef1 k\u1ebft h\u1ee3p n\xe0y h\xf3a gi\u1ea3i t\xednh hung c\u1ee7a \u0110\u1ecba Ki\u1ebfp theo c\xe1ch tinh t\u1ebf \u2014 kh\xf4ng b\u1eb1ng quy\u1ec1n l\u1ef1c m\xe0 b\u1eb1ng s\u1ef1 hi\u1ec3u bi\u1ebft v\xe0 l\xf2ng nh\xe2n. B\u1ea1n s\u1ebd tr\u01b0\u1edfng th\xe0nh v\xe0 ch\xedn ch\u1eafn h\u01a1n nh\u1edd nh\u1eefng cu\u1ed9c g\u1eb7p g\u1ee1 n\xe0y."],d4,d4),c5,A.p(["M\u1ec7nh","T\xednh \u0111\u1ed9t ng\u1ed9t v\xe0 hay t\xednh to\xe1n l\u1eb1ng nh\u1eb1ng \u0111\u01b0\u1ee3c k\xe9o b\u1edbt nh\u1edd (\u0110), gi\xfap \u0111\u01b0\u01a1ng s\u1ed1 s\u1ed1ng c\xf3 chi\u1ec1u s\xe2u h\u01a1n v\xe0 \xedt b\u1ecb cu\u1ed1n v\xe0o nh\u1eefng quy\u1ebft \u0111\u1ecbnh b\u1ed1c \u0111\u1ed3ng. Thi\xean Vi\u1ec7t mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n ch\xe2n t\xecnh, th\u01b0\u1eddng \xe2m th\u1ea7m h\u1ed7 tr\u1ee3 v\xe0 che ch\u1edf m\xe0 kh\xf4ng c\u1ea7n \u0111\u01b0\u1ee3c \u0111\u1ec1n \u0111\xe1p \u2014 \u0111\xe2y l\xe0 lo\u1ea1i qu\xfd nh\xe2n b\u1ec1n v\u1eefng nh\u1ea5t trong cu\u1ed9c \u0111\u1eddi. S\u1ef1 h\xf3a gi\u1ea3i c\u1ee7a Thi\xean Vi\u1ec7t l\xean \u0110\u1ecba Ki\u1ebfp c\xf3 ph\u1ea7n \xeam \xe1i v\xe0 \u1ed5n \u0111\u1ecbnh, gi\xfap b\u1ea1n \xedt g\u1eb7p bi\u1ebfn c\u1ed1 l\u1edbn d\xf9 cu\u1ed9c s\u1ed1ng kh\xf4ng ho\xe0n to\xe0n b\u1eb1ng ph\u1eb3ng. N\u1ebfu bi\u1ebft tr\xe2n tr\u1ecdng nh\u1eefng m\u1ed1i quan h\u1ec7 n\xe0y, b\u1ea1n s\u1ebd c\xf3 m\u1ed9t h\u1eadu thu\u1eabn r\u1ea5t v\u1eefng ch\u1eafc."],d4,d4),c6,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 mang t\xednh n\xf3ng n\u1ea3y, hay l\xe8m b\xe8m v\xe0 th\xedch \u0111i \u0111\u01b0\u1eddng v\xf2ng h\u01a1n \u0111\u01b0\u1eddng th\u1eb3ng \u2014 \u0111\xe2y l\xe0 t\xednh c\u1ee7a \u0110\u1ecba Kh\xf4ng khi kh\xf4ng c\xf3 s\u1ef1 ki\u1ec3m so\xe1t t\u1eeb (\u0110). Tuy nhi\xean, Thi\xean Kh\xf4i \u0111\u1ee9ng ra mang l\u1ea1i s\u1ef1 ch\xednh danh v\xe0 che ch\u1edf t\u1eeb nh\u1eefng ng\u01b0\u1eddi c\xf3 v\u1ecb th\u1ebf, gi\xfap h\xf3a gi\u1ea3i ph\u1ea7n hung h\u0103ng \u0111\xe1ng k\u1ec3. B\u1ea1n v\u1eabn d\u1ec5 ti\xeau ti\u1ec1n v\xe0 hay ngh\u0129 \u1ea9u, nh\u01b0ng nh\u1edd qu\xfd nh\xe2n b\xean c\u1ea1nh, nh\u1eefng sai l\u1ea7m \u1ea5y th\u01b0\u1eddng kh\xf4ng d\u1eabn \u0111\u1ebfn h\u1eadu qu\u1ea3 kh\xf4ng th\u1ec3 c\u1ee9u v\xe3n. \u0110i\u1ec1u b\u1ea1n c\u1ea7n l\xe0m l\xe0 b\u1edbt \u0111i \u0111\u01b0\u1eddng v\xf2ng v\xe0 h\u1ecdc c\xe1ch n\xf3i th\u1eb3ng \u2014 qu\xfd nh\xe2n s\u1ebd \u0111\u1ee1 b\u1ea1n hi\u1ec7u qu\u1ea3 h\u01a1n khi b\u1ea1n r\xf5 r\xe0ng h\u01a1n trong \xfd \u0111\u1ecbnh."],d4,d4),c7,A.p(["M\u1ec7nh","B\u1ea1n c\xf3 t\u01b0 duy ph\xf3ng kho\xe1ng, d\xe1m ngh\u0129 d\xe1m l\xe0m v\xe0 th\xedch th\u1eed nh\u1eefng th\u1ee9 m\xe0 ng\u01b0\u1eddi kh\xe1c kh\xf4ng d\xe1m \u2014 nh\u01b0ng \u0111i k\xe8m v\u1edbi \u0111\xf3 l\xe0 t\xednh d\u1ec5 x\xe0i hoang v\xe0 kh\xf3 gi\u1eef ti\u1ec1n l\xe2u d\xe0i. \xc2n Quang mang \u0111\u1ebfn ph\u01b0\u1edbc l\xe0nh t\xe2m linh, b\u1ea1n c\xf3 l\xf2ng nh\xe2n v\xe0 c\xf3 c\u0103n tu \u1ea9n trong ng\u01b0\u1eddi, \u0111i\u1ec1u \u0111\xf3 thu h\xfat nh\u1eefng ng\u01b0\u1eddi t\u1ed1t b\u1ee5ng \u0111\u1ebfn h\u1ed7 tr\u1ee3 m\xe0 kh\xf4ng c\u1ea7n t\xednh to\xe1n. Tuy nhi\xean v\xec kh\xf4ng c\xf3 (\u0110), t\xednh b\u1ed1c \u0111\u1ed3ng v\xe0 d\u1ec5 hao t\u1ed5n v\u1eabn c\xf2n r\xf5 \u2014 b\u1ea1n c\u1ea7n h\u1ecdc c\xe1ch l\u1eafng nghe nh\u1eefng qu\xfd nh\xe2n \u1ea5y thay v\xec ch\u1ec9 ch\u1edd h\u1ecd c\u1ee9u m\xecnh khi \u0111\xe3 l\u1ee1 vi\u1ec7c. Ph\u01b0\u1edbc c\xf3 nh\u01b0ng c\u1ea7n bi\u1ebft d\xf9ng \u0111\xfang l\xfac."],d4,d4),c8,A.p(["M\u1ec7nh","T\xednh n\xf3ng v\u1ed9i, hay c\xe1u g\u1eaft v\xe0 th\xedch l\xe0m nh\u1eefng vi\u1ec7c v\u01b0\u1ee3t khu\xf4n kh\u1ed5 c\u1ee7a \u0110\u1ecba Kh\xf4ng v\u1eabn c\xf2n nguy\xean v\xec kh\xf4ng c\xf3 (\u0110) ki\u1ec3m so\xe1t. Tuy nhi\xean, Thi\xean Qu\xfd mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n c\xf3 c\u0103n tu v\xe0 t\xe2m thi\u1ec7n, th\u01b0\u1eddng xu\u1ea5t hi\u1ec7n nh\u01b0 m\u1ed9t \u0111i\u1ec3m d\u1eebng gi\xfap b\u1ea1n nh\xecn l\u1ea1i b\u1ea3n th\xe2n tr\u01b0\u1edbc khi \u0111i qu\xe1 xa. S\u1ef1 h\xf3a gi\u1ea3i c\u1ee7a Thi\xean Qu\xfd kh\xf4ng d\u1eef d\u1ed9i m\xe0 r\u1ea5t nh\u1eb9 nh\xe0ng \u2014 \u0111\xf4i khi ch\u1ec9 l\xe0 m\u1ed9t l\u1eddi n\xf3i, m\u1ed9t cu\u1ed9c g\u1eb7p g\u1ee1 \u0111\xfang l\xfac \u0111\u1ee7 \u0111\u1ec3 thay \u0111\u1ed5i h\u01b0\u1edbng \u0111i c\u1ee7a b\u1ea1n. B\u1ea1n v\u1eabn c\u1ea7n t\u1ef1 r\xe8n luy\u1ec7n ki\u1ec3m so\xe1t c\u1ea3m x\xfac v\xe0 t\xe0i ch\xednh, nh\u01b0ng kh\xf4ng bao gi\u1edd thi\u1ebfu ng\u01b0\u1eddi \u0111\u1ec3 t\xe2m s\u1ef1."],d4,d4),c9,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 t\xednh li\u1ec1u l\u0129nh, hay so \u0111o v\xe0 d\u1ec5 x\xe0i ti\u1ec1n kh\xf4ng c\xf3 k\u1ebf ho\u1ea1ch \u2014 nh\u1eefng \u0111i\u1ec1u n\xe0y kh\xf4ng \u0111\u01b0\u1ee3c \u0111i\u1ec1u ti\u1ebft v\xec thi\u1ebfu (\u0110). Thi\xean Vi\u1ec7t mang \u0111\u1ebfn qu\xfd nh\xe2n ch\xe2n t\xecnh v\xe0 c\xf3 t\xecnh ngh\u0129a, th\u01b0\u1eddng l\xe0 nh\u1eefng ng\u01b0\u1eddi s\u1eb5n s\xe0ng \u0111\u1ee9ng ra gi\xfap b\u1ea1n m\xe0 kh\xf4ng c\u1ea7n b\u1ea1n ph\u1ea3i n\u0103n n\u1ec9. S\u1ef1 che ch\u1edf c\u1ee7a Thi\xean Vi\u1ec7t \u0111\u1ee7 \u0111\u1ec3 l\xe0m d\u1ecbu t\xednh hung c\u1ee7a \u0110\u1ecba Kh\xf4ng, nh\u01b0ng kh\xf4ng tri\u1ec7t ti\xeau ho\xe0n to\xe0n \u2014 b\u1ea1n v\u1eabn s\u1ebd g\u1eb7p hao t\u1ed5n n\u1ebfu kh\xf4ng t\u1ef1 \xfd th\u1ee9c. \u0110i\u1ec1u quan tr\u1ecdng l\xe0 b\u1ea1n h\u1ecdc c\xe1ch tr\xe2n tr\u1ecdng nh\u1eefng ng\u01b0\u1eddi th\u1eadt s\u1ef1 b\xean m\xecnh v\xe0 \u0111\u1eebng \u0111\u1ec3 t\xednh b\u1ed1c \u0111\u1ed3ng l\xe0m m\u1ea5t \u0111i nh\u1eefng m\u1ed1i quan h\u1ec7 qu\xfd gi\xe1 \u0111\xf3."],d4,d4),d0,A.p(["M\u1ec7nh","B\u1ea1n c\xf3 t\xednh n\xf3ng, hay l\u1eafm chuy\u1ec7n v\xe0 th\xedch \u0111i con \u0111\u01b0\u1eddng ph\u1ee9c t\u1ea1p h\u01a1n con \u0111\u01b0\u1eddng th\u1eb3ng \u2014 \u0111\xe2y l\xe0 m\u1eb7t th\u1eadt c\u1ee7a \u0110\u1ecba Ki\u1ebfp khi thi\u1ebfu s\u1ef1 \u0111i\u1ec1u ch\u1ec9nh t\u1eeb (\u0110). Thi\xean Kh\xf4i mang \u0111\u1ebfn s\u1ef1 ch\xednh danh v\xe0 qu\xfd nh\xe2n c\xf3 v\u1ecb th\u1ebf, gi\xfap h\xf3a gi\u1ea3i ph\u1ea7n hung h\u0103ng v\xe0 t\u1ea1o ra m\u1ed9t t\u1ea5m ch\u1eafn b\u1ea3o v\u1ec7 t\u1eeb b\xean ngo\xe0i. B\u1ea1n th\u01b0\u1eddng \u0111\u01b0\u1ee3c nh\u1eefng ng\u01b0\u1eddi c\xf3 quy\u1ec1n l\u1ef1c c\xf4ng nh\u1eadn ho\u1eb7c \u0111\u1ee9ng ra b\u1ea3o v\u1ec7, v\xe0 \u0111i\u1ec1u \u0111\xf3 gi\xfap b\u1ea1n tr\xe1nh \u0111\u01b0\u1ee3c nhi\u1ec1u tai \u01b0\u01a1ng do b\u1ea3n t\xednh li\u1ec1u l\u0129nh g\xe2y ra. Tuy nhi\xean, kh\xf4ng n\xean \u1ef7 l\u1ea1i v\xe0o qu\xfd nh\xe2n m\xe0 c\u1ea7n t\u1ef1 c\u1ea3i thi\u1ec7n t\xednh c\xe1ch \u2014 b\u1edbt l\u1eafm chuy\u1ec7n, b\u1edbt t\xednh to\xe1n v\xe0 h\u1ecdc c\xe1ch n\xf3i th\u1eb3ng h\u01a1n."],d4,d4),d1,A.p(["M\u1ec7nh","\u0110\u1ecba Ki\u1ebfp kh\xf4ng c\xf3 (\u0110) mang \u0111\u1ebfn t\xednh n\xf3ng, l\u1eafm l\u1eddi v\xe0 hay suy ngh\u0129 v\xf2ng vo \u2014 b\u1ea1n th\u01b0\u1eddng kh\xf4ng \u0111i th\u1eb3ng v\xe0o v\u1ea5n \u0111\u1ec1 m\xe0 lu\xf4n c\xf3 nhi\u1ec1u b\u01b0\u1edbc trung gian, nhi\u1ec1u t\xednh to\xe1n \u1ea9n. \xc2n Quang mang \u0111\u1ebfn m\u1ed9t t\u1ea7ng ph\u01b0\u1edbc l\xe0nh t\xe2m linh, b\u1ea1n c\xf3 l\xf2ng nh\xe2n th\u1eadt s\u1ef1 trong ng\u01b0\u1eddi v\xe0 \u0111i\u1ec1u \u0111\xf3 thu h\xfat nh\u1eefng ng\u01b0\u1eddi t\u1ed1t b\u1ee5ng \u0111\u1ebfn gi\xfap \u0111\u1ee1 m\u1ed9t c\xe1ch t\u1ef1 nhi\xean. Trong nh\u1eefng l\xfac kh\xf3 kh\u0103n nh\u1ea5t, th\u01b0\u1eddng c\xf3 m\u1ed9t s\u1ef1 ki\u1ec7n ho\u1eb7c con ng\u01b0\u1eddi xu\u1ea5t hi\u1ec7n nh\u01b0 m\u1ed9t ph\xe9p m\xe0u. B\u1ea1n c\u1ea7n h\u1ecdc c\xe1ch b\u1edbt t\xednh to\xe1n v\xe0 s\u1ed1ng th\u1eb3ng th\u1eafn h\u01a1n \u2014 v\xec ch\xednh s\u1ef1 th\u1eadt th\xe0 \u1ea5y m\u1edbi khai th\xf4ng \u0111\u01b0\u1ee3c d\xf2ng ph\u01b0\u1edbc t\u1eeb \xc2n Quang."],d4,d4),d2,A.p(["M\u1ec7nh","T\xednh ph\u1ee9c t\u1ea1p, hay l\xe8m b\xe8m v\xe0 th\xedch \u0111i \u0111\u01b0\u1eddng v\xf2ng c\u1ee7a \u0110\u1ecba Ki\u1ebfp v\u1eabn c\xf2n r\xf5 khi thi\u1ebfu (\u0110), khi\u1ebfn b\u1ea1n \u0111\xf4i khi t\u1ef1 t\u1ea1o ra r\u1eafc r\u1ed1i kh\xf4ng c\u1ea7n thi\u1ebft. Thi\xean Qu\xfd mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n c\xf3 t\xe2m thi\u1ec7n v\xe0 c\u0103n tu s\xe2u, th\u01b0\u1eddng gi\xfap b\u1ea1n nh\xecn ra \u0111i\u1ec1u m\xecnh \u0111ang l\xe0m sai m\xe0 kh\xf4ng ph\xe1n x\xe9t. S\u1ef1 h\xf3a gi\u1ea3i t\u1eeb Thi\xean Qu\xfd kh\xf4ng mang t\xednh quy\u1ec1n l\u1ef1c m\xe0 mang t\xednh khai s\xe1ng \u2014 b\u1ea1n h\u1ecdc \u0111\u01b0\u1ee3c nhi\u1ec1u t\u1eeb nh\u1eefng ng\u01b0\u1eddi n\xe0y h\u01a1n l\xe0 \u0111\u01b0\u1ee3c gi\xfap v\u1ec1 v\u1eadt ch\u1ea5t. Tuy nhi\xean b\u1ea1n c\u1ea7n b\u1edbt t\xednh to\xe1n v\xe0 m\u1edf l\xf2ng h\u01a1n, v\xec Thi\xean Qu\xfd ch\u1ec9 c\xf3 th\u1ec3 gi\xfap \u0111\u01b0\u1ee3c ng\u01b0\u1eddi s\u1eb5n s\xe0ng \u0111\xf3n nh\u1eadn."],d4,d4),d3,A.p(["M\u1ec7nh","\u0110\u01b0\u01a1ng s\u1ed1 c\xf3 t\xednh n\xf3ng, hay so \u0111o v\xe0 th\xedch l\xe0m nh\u1eefng chuy\u1ec7n ph\u1ee9c t\u1ea1p h\u01a1n c\u1ea7n thi\u1ebft \u2014 \u0111\xe2y l\xe0 b\u1ea3n ch\u1ea5t c\u1ee7a \u0110\u1ecba Ki\u1ebfp khi kh\xf4ng c\xf3 s\u1ef1 \u0111i\u1ec1u ti\u1ebft. Tuy nhi\xean, Thi\xean Vi\u1ec7t mang \u0111\u1ebfn nh\u1eefng qu\xfd nh\xe2n c\xf3 t\xecnh ngh\u0129a, th\u01b0\u1eddng l\xe0 nh\u1eefng ng\u01b0\u1eddi ch\xe2n th\xe0nh v\xe0 s\u1eb5n s\xe0ng \u0111\u1ee9ng ra b\xeanh v\u1ef1c b\u1ea1n d\xf9 b\u1ea1n c\xf3 nh\u1eefng l\xfac kh\xf4ng d\u1ec5 ch\u1ecbu. S\u1ef1 h\xf3a gi\u1ea3i c\u1ee7a Thi\xean Vi\u1ec7t l\xean \u0110\u1ecba Ki\u1ebfp t\u1ea1o ra m\u1ed9t s\u1ef1 c\xe2n b\u1eb1ng nh\u1ea5t \u0111\u1ecbnh \u2014 b\u1ea1n v\u1eabn c\xf3 t\xednh kh\xf3, nh\u01b0ng l\u1ea1i c\xf3 ng\u01b0\u1eddi y\xeau th\u01b0\u01a1ng th\u1eadt s\u1ef1. \u0110i\u1ec1u b\u1ea1n c\u1ea7n l\xe0m l\xe0 b\u1edbt ph\u1ee9c t\u1ea1p h\xf3a m\u1ecdi vi\u1ec7c v\xe0 h\u1ecdc c\xe1ch tr\xe2n tr\u1ecdng nh\u1eefng ng\u01b0\u1eddi b\xean c\u1ea1nh tr\u01b0\u1edbc khi h\u1ecd m\u1ec7t m\u1ecfi m\xe0 \u0111i."],d4,d4)],d4,t.GU)
