if(s&&r.b===1&&r.c===1&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba Thi\xean Th\xe1i",c5,r.b,r.c,r.d,r.e,r.f,"H\u1ec8 B\xc1O TAM NGUY\xcaN",a7,a9,b0,n,m,l,b1,"",2,0,3,k,d,r.r[56],"\n\u521d \u4e5d : \u62d4 \u8305 \u8339 \uff0e \u4ee5 \u5176 \u5f59 \uff0e \u5f81 \u5409 \uff0e\nS\u01a1 c\u01b0\u0309u: ba\u0323t mao nh\u01b0\u0323, di\u0303 ky\u0300 vi\u0323, chinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : Nh\xf4\u0309 r\xea\u0309 co\u0309 mao ma\u0300 \u0111\u01b0\u01a1\u0323c ca\u0309 \u0111a\u0301m, ti\xea\u0301n l\xean thi\u0300 t\xf4\u0301t.\n","\n\u4e5d \u4e8c : \u5305 \u8352 , \u7528 \u99ae \u6cb3 , \u4e0d \u9050 \u907a \uff0e\u670b \u4ea1 , \u5f97 \u5c1a \u4e8e \u4e2d \u884c \uff0e\nC\u1eedu nhi\u0323: Bao hoang, du\u0323ng b\u0103\u0300ng ha\u0300, b\xe2\u0301t ha\u0300 di,\nB\u0103\u0300ng vong, \u0111\u0103\u0301c th\u01b0\u01a1\u0323ng vu trung ha\u0300nh.\nD\u1ecbch: Bao dung s\u01b0\u0323 hoang ph\xea\u0301 (nh\u01b0\u0303ng t\xea\u0323 ha\u0323i cu\u0303), du\u0300ng ca\u0301ch c\u01b0\u01a1ng quy\xea\u0301t ma\u0323o hi\xea\u0309m nh\u01b0 l\xf4\u0323i qua s\xf4ng, kh\xf4ng bo\u0309 so\u0301t nh\u01b0\u0303ng vi\xea\u0323c (ho\u0103\u0323c ng\u01b0\u01a1\u0300i ) \u01a1\u0309 xa, kh\xf4ng nghi\u0303 \u0111\xea\u0301n be\u0300 \u0111a\u0309ng, ma\u0300 pha\u0309i h\u01a1\u0323p v\u01a1\u0301i \u0111a\u0323o trung.\n","\n\u4e5d \u4e09 : \u65e0 \u5e73 \u4e0d \u9642 , \u65e0 \u5f80 \u4e0d \u5fa9 \uff0e \u8271 \u8c9e \u65e0 \u548e , \u52ff \u6064, \u5176 \u5b5a , \u4e8e \u98df \u6709 \u798f \uff0e\nC\u1eedu tam: V\xf4 hi\u0300nh b\xe2\u0301t bi\u0301, v\xf4 va\u0303ng b\xe2\u0301t phu\u0323c.\nGian trinh v\xf4 c\u01b0\u0309u, v\xe2\u0323t tu\xe2\u0301t, ky\u0300 phu, vu th\u01b0\u0323c h\u01b0\u0303u phu\u0301c.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: kh\xf4ng co\u0301 ca\u0301i gi\u0300 b\u0103\u0300ng ma\u0303i ma\u0300 kh\xf4ng nghi\xeang, \u0111i ma\u0303i ma\u0300 kh\xf4ng tr\u01a1\u0309 la\u0323i, trong ca\u0309nh gian nan ma\u0300 gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c chi\u0301nh \u0111a\u0301ng thi\u0300 kh\xf4ng l\xf4\u0303i. \u0110\u01b0\u0300ng lo phi\xea\u0300n, c\u01b0\u0301 tin \u01a1\u0309 \u0111i\xea\u0300u chi\u0301nh thi\u0300 \u0111\u01b0\u01a1\u0323c h\u01b0\u01a1\u0309ng phu\u0301c.\n","\n\u516d \u56db : \u7fe9 \u7fe9 , \u4e0d \u5bcc, \u4ee5 \u5176 \u9130 , \u4e0d \u6212 \u4ee5 \u5b5a \uff0e\nL\u1ee5c t\u01b0\u0301: Phi\xean phi\xean, b\xe2\u0301t phu\u0301, di\u0303 ky\u0300 l\xe2n, b\xe2\u0301t gi\u01a1\u0301i di\u0303 phu.\nD\u1ecbch: Ha\u0300o 4, \xe2m : D\xe2\u0323p di\u0300u (ho\u0103\u0323c h\u01a1\u0301n h\u01a1\u0309) v\u01a1\u0301i nhau, kh\xf4ng gia\u0300u ma\u0300 tha\u0300nh m\xf4\u0323t xo\u0301m, ch\u0103\u0309ng \u01b0\u01a1\u0301c he\u0323n ma\u0300 cu\u0303ng tin nhau.\n","\n\u516d \u4e94 : \u5e1d \u4e59 \u6b78 \u59b9 \uff0e \u4ee5 \u7949, \u5143 \u5409 \uff0e\nL\u1ee5c ngu\u0303: \u0110\xea\u0301 \xc2\u0301t qui mu\xf4\u0323i, di\u0303 chi\u0309, nguy\xean ca\u0301t.\nD\u1ecbch: Nh\u01b0 vua \u0111\xea\u0301 \xc2\u0301t (\u0111\u01a1\u0300i Th\u01b0\u01a1ng) cho em ga\u0301i v\xea\u0300 nha\u0300 ch\xf4\u0300ng, co\u0301 phu\u0301c, r\xe2\u0301t t\xf4\u0301t.\n","\n\u4e0a \u516d : \u57ce \u5fa9 \u4e8e \u968d , \u52ff \u7528 \u5e2b , \u81ea \u9091 \u544a \u547d, \u8c9e \u541d \uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Tha\u0300nh phu\u0323c vu\u0323 hoa\u0300ng, v\xe2\u0323t du\u0323ng s\u01b0,\nT\u01b0\u0323 \xe2\u0301p ca\u0301o m\xea\u0323nh, trinh l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: tha\u0300nh \u0111\xf4\u0309 su\u0323p xu\xf4\u0301ng, la\u0323i chi\u0309 la\u0300 \u0111\xf4\u0301ng \u0111\xe2\u0301t. \u0110\u01b0\u0300ng du\u0300ng qu\xe2n n\u01b0\u0303a, b\xe2\u0301t qua\u0301 m\xea\u0323nh l\xea\u0323nh chi\u0309 ban ra \u0111\u01b0\u0323\u01a1c trong \xe2\u0301p mi\u0300nh th\xf4i. Du\u0300 ha\u0300nh \u0111\xf4\u0323ng cu\u0309a mi\u0300nh chi\u0301nh \u0111a\u0301ng nh\u01b0ng v\xe2\u0303n th\xe2\u0301t ba\u0323i ma\u0300 x\xe2\u0301u h\xf4\u0309.\n")
if(s&&r.b===1&&r.c===1&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("B\xe1t Thu\u1ea7n C\xe0n",c5,r.b,r.c,r.d,r.e,r.f,"KH\u1ed0N LONG \u0110\u1eaeC TH\u1ee6Y",a7,a9,b0,i,h,g,"","",0,0,6,e,j,r.r[7],"\n\u521d \u4e5d: \u6f5b \u9f8d \u52ff \u7528\nS\u01a1 c\u01b0\u0309u: Ti\xea\u0300m long v\xe2\u0323t du\u0323ng.\nD\u1ecbch: ha\u0300o 1 d\u01b0\u01a1ng: R\xf4\u0300ng co\u0300n \xe2\u0309n na\u0301u, ch\u01b0a (\u0111em ta\u0300i ra) du\u0300ng \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d \u4e8c : \u898b \u9f8d \u5728 \u7530 \uff0e \u5229 \u898b \u5927 \u4eba\n \uff0eC\u1eedu nhi\u0323: Hi\xea\u0323n long ta\u0323i \u0111i\xea\u0300n, l\u01a1\u0323i ki\xea\u0301n \u0111a\u0323i nh\xe2n.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: r\xf4\u0300ng \u0111a\u0303 hi\xea\u0323n \u01a1\u0309 ca\u0301nh \u0111\xf4\u0300ng, ra m\u0103\u0301t \u0111a\u0323i nh\xe2n thi\u0300 l\u01a1\u0323i.\n","\n\u4e5d \u4e09: \u541b \u5b50 \u7d42 \u65e5 \u4e7e \u4e7e, \u5915 \u60d5 \u82e5. \u53b2, \u65e0 \u548e.\nC\u1eedu tam: Qu\xe2n t\u01b0\u0309 chung nh\xe2\u0323t ca\u0300n ca\u0300n, ti\u0323ch di\u0323ch nh\u01b0\u01a1\u0323c. L\xea\u0323, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: ha\u0300o 3, d\u01b0\u01a1ng: Ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 m\xf4\u0303i nga\u0300y h\u0103ng ha\u0301i t\u01b0\u0323 c\u01b0\u01a1\u0300ng, \u0111\xea\u0301n t\xf4\u0301i v\xe2\u0303n co\u0300n th\xe2\u0323n tro\u0323ng nh\u01b0 lo s\u01a1\u0323. Nguy hi\xea\u0309m, nh\u01b0ng kh\xf4ng t\xf4i l\xf4\u0303i.\n","\n\u4e5d \u56db: \u6216 \u8e8d, \u5728 \u6df5, \u65e0 \u548e.\nC\u1eedu t\u01b0\u0301: Ho\u0103\u0323c d\u01b0\u01a1\u0323c, ta\u0323i uy\xean, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: nh\u01b0 con r\xf4\u0300ng co\u0301 khi bay nha\u0309y, co\u0301 khi n\u0103\u0300m trong v\u01b0\u0323c (bi\xea\u0301t tu\u0300y th\u01a1\u0300i nh\u01b0 th\xea\u0301 thi\u0300) kh\xf4ng l\xe2\u0300m l\xf4\u0303i.\n","\n\u4e5d \u4e94 : \u98db \u9f8d \u5728 \u5929 , \u5229 \u898b \u5927 \u4eba.\nC\u1eedu ngu\u0303: Phi long ta\u0323i thi\xean, l\u01a1\u0323i ki\xea\u0301n \u0111a\u0323i nh\xe2n.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: R\xf4\u0300ng bay tr\xean tr\u01a1\u0300i, ra m\u0103\u0301t ke\u0309 \u0111a\u0323i nh\xe2n thi\u0300 l\u01a1\u0323i.\n","\n\u4e0a \u4e5d \uff0e \u4ea2 \u9f8d \u6709 \u6094.\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Kha\u0301ng long h\u01b0\u0303u h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: R\xf4\u0300ng l\xean cao qua\u0301, co\u0301 h\xf4\u0301i h\xe2\u0323n.\n")
if(s&&r.b===1&&r.c===1&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch Thi\xean Qu\u1ea3i",c5,r.b,r.c,r.d,r.e,r.f,"DU PHONG THO\xc1T V\xd5NG",a7,a9,b0,m,l,q,b1,"",2,0,5,k,"",r.r[14],"\n\u521d\u4e5d: \u58ef\u4e8e\u524d\u8dbe, \u5f80, \u4e0d\u52dd\u70ba\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: Tra\u0301ng vu ti\xean chi\u0309, va\u0303ng, b\xe2\u0301t th\u0103\u0301ng vi c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: ma\u0323nh (th\u0103ng \u01a1\u0309 ngo\u0301n ch\xe2n b\u01b0\u01a1\u0301c l\xean tr\u01b0\u01a1\u0301c (t\u01b0\u0301c h\u0103ng ti\xea\u0301n l\xean tr\u01b0\u01a1\u0301c), ti\xea\u0301n l\xean ma\u0300 kh\xf4ng ch\u0103\u0301c th\u0103\u0301ng \u0111\u01b0\u01a1\u0323c la\u0300 co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u60d5, \u865f, \u83ab\u591c\u6709\u620e, \u52ff\u6064\uff0e\nC\u1eedu nhi: Di\u0323ch, hao, ma\u0323c da\u0323 h\u01b0\u0303u nhung, v\xe2\u0323t tu\xe2\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: lo l\u0103\u0301ng ma\u0300 h\xf4 ha\u0300o ca\u0301c ba\u0323n (\u0111\xea\u0300 pho\u0300ng) nh\u01b0 v\xe2\u0323y du\u0300 \u0111\xeam khuya gi\u0103\u0323c co\u0301 t\u01a1\u0301i cu\u0303ng ch\u0103\u0309ng s\u01a1\u0323.\n","\n\u4e5d\u4e09: \u58ef\u4e8e\u9804\uff0e\u6709\u51f6\uff0e\u541b\u5b50\u592c\u592c\uff0e\u7368\u884c\u9047\u96e8, \u82e5\u6fe1\u6709\u614d, \u65e0\u548e\uff0e\nC\u1eedu tam: Tra\u0301ng vu qui\u0300 (c\u01b0\u0300u), h\u01b0\u0303u hung, qu\xe2n t\u01b0\u0309 qua\u0309i qua\u0309i,\n\u0110\xf4\u0323c ha\u0300nh ng\xf4\u0323 vu\u0303, nh\u01b0\u01a1\u0323c nhu h\u01b0\u0303u u\xe2\u0309n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: C\u01b0\u01a1\u0300ng ba\u0323o \u01a1\u0309 go\u0300 ma\u0301 (hi\xea\u0323n tr\xean m\u0103\u0323t), co\u0301 \u0111i\xea\u0300u x\xe2\u0301u. Ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 c\u01b0\u01a1ng quy\xea\u0301t (bo\u0309 ti\xea\u0309u nh\xe2n): tr\u01b0\u01a1\u0301c kia \u0111a\u0303 l\u01a1\u0303 \u0111i ri\xeang m\xf4\u0323t \u0111\u01b0\u01a1\u0300ng g\u0103\u0323p m\u01b0a \u01b0\u01a1\u0301t va\u0300 l\xe2\u0301m, bi\u0323 ba\u0323n be\u0300 gi\xe2\u0323n, b\xe2y gi\u01a1\u0300 ca\u0309i qua\u0301, se\u0303 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u56db: \u81c0\u65e0\u819a, \u5176\u884c\u6b21\u4e14, \u727d\u7f8a\u6094\u4ea1, \u805e\u8a00\u4e0d\u4fe1\uff0e\nC\u1eedu t\u01b0\u0301: \u0110\xf4\u0300n v\xf4 phu, ki\u0300 ha\u0300nh t\u01b0 th\u01b0, khi\xean d\u01b0\u01a1ng h\xf4\u0301i vong, v\u0103n ng\xf4n b\xe2\u0301t ti\u0301n.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: Nh\u01b0 ba\u0300n toa\u0323 ma\u0300 kh\xf4ng co\u0301 da (co\u0301 ng\u01b0\u01a1\u0300i cho la\u0300 kh\xf4ng h\u01a1\u0323p co\u0301 l\u01a1\u0301p thi\u0323t sau da), \u0111i ch\xe2\u0323p ch\u01b0\u0303ng (kho\u0301 kh\u0103n); chi\u0309 n\xean \u0111i sau ng\u01b0\u01a1\u0300i ta nh\u01b0 ng\u01b0\u01a1\u0300i lu\u0300a b\xe2\u0300y c\u01b0\u0300u, thi\u0300 h\xea\u0301t \xe2n h\xe2\u0323n; (nh\u01b0ng e r\u0103\u0300ng) nghe (ta) no\u0301i ma\u0300 ch\u0103\u0309ng tin \u0111\xe2u.\n","\n\u4e5d\u4e94: \u83a7\u9678, \u592c\u592c, \u4e2d\u884c, \u65e0\u548e\uff0e\nC\u1eedu ngu\u0303: Nghi\xea\u0303n lu\u0323c, qua\u0309i qua\u0309i, trung ha\u0300nh, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng (Ha\u0300o tr\xean cu\u0300ng) nh\u01b0 rau sam (\u0111\u01b0\u01a1\u0323c nhi\xea\u0300u \xe2m khi\u0301), n\xea\u0301u ha\u0300o 5 c\u01b0\u01a1ng quy\xea\u0301t, \u0111a\u0300o t\xe2\u0323n g\xf4\u0301c no\u0301, c\u01b0\u0301 theo \u0111a\u0323o trung ma\u0300 \u0111i thi\u0300 kh\xf4ng l\xf4\u0303i.\n","\n\u4e0a\u516d: \u65e0\u865f, \u7d42 \u6709\u51f6.\nTh\u01b0\u1ee3ng lu\u0323c: v\xf4 ha\u0300o, chung h\u01b0\u0303u hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: \u0110\u01b0\u0300ng k\xeau ga\u0300o, kh\xf4ng ai giu\u0301p \u0111\xe2u, cu\xf4\u0301i cu\u0300ng se\u0303 bi\u0323 hoa\u0323.\n")
if(s&&r.b===1&&r.c===1&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa Thi\xean \u0110\u1ea1i H\u1eefu",c5,r.b,r.c,r.d,r.e,r.f,"TR\u1ea2M TH\u1ee4 M\xd4 T\u01af\u1edaC",a7,a9,b0,l,q,p,"","",0,0,3,e,a8,r.r[21],"\n\u521d\u4e5d: \u65e0\u4ea4\u5bb3, \u532a\u548e; \u8271\u5247\u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: V\xf4 giao ha\u0323i, phi\u0309 c\u01b0\u0303u; nan t\u0103\u0301c v\xf4 c\u01b0\u0309u.\nD\u1ecbch : Ha\u0300o 1. d\u01b0\u01a1ng : ch\u01b0a la\u0300m vi\xea\u0323c gi\u0300 tai ha\u0323i, ch\u01b0a co\u0301 l\xf4\u0303i; nh\u01b0ng pha\u0309i (c\xe2\u0309n th\xe2\u0323n) c\u01b0 x\u01b0\u0309 nh\u01b0 g\u0103\u0323p lu\u0301c gian nan thi\u0300 m\u01a1\u0301i kho\u0309i l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u5927\u8eca\u4ee5\u8f09, \u6709\u6538\u5f80, \u65e0\u548e\uff0e\nC\u1eedu nhi\u0323: \u0111a\u0323i xa di\u0303 ta\u0301i, h\u01b0\u0303u du va\u0303ng, v\xf4 c\u01b0\u0309u.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : xe l\u01a1\u0301n ch\u01a1\u0309 n\u0103\u0323ng, \u0111i ch\xf4\u0301n na\u0300o (y\u0301 no\u0301i la\u0300m gi\u0300) cu\u0303ng \u0111\u01b0\u01a1\u0323c, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e09: \u516c\u7528\u4ea8\u4e8e\u5929\u5b50, \u5c0f\u4eba\u5f17\u514b\uff0e\nC\u1eedu tam: C\xf4ng du\u0323ng h\u01b0\u01a1\u0309ng vu thi\xean t\u01b0\u0309, ti\xea\u0309u nh\xe2n ph\xe2\u0301t kh\u0103\u0301c.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : nh\u01b0 b\xe2\u0323c c\xf4ng (h\xe2\u0300u) m\u01a1\u0309 ti\xea\u0323c m\u01a1\u0300i thi\xean t\u01b0\u0309 ha\u0323ng ti\xea\u0309u nh\xe2n kh\xf4ng \u0111\u01b0\u01a1ng n\xf4\u0309i vi\xea\u0323c \u0111o\u0301.\n","\n\u4e5d\u56db: \u532a\u5176\u5f6d, \u65e0\u548e\uff0e\nC\u1eedu t\u01b0\u0301: phi\u0309 ky\u0300 ba\u0300nh, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0303o, d\u01b0\u01a1ng: \u0111\u01b0\u0300ng la\u0300m ra ve\u0309 thi\u0323nh v\u01b0\u01a1\u0323ng (khoe cu\u0309a, s\xf4\u0301ng sang qua\u0301) thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94: \u53a5\u5b5a\u4ea4\u5982, \u5a01\u5982, \u5409\uff0e\nL\u1ee5c ngu\u0303: quy\xea\u0301t phu giao nh\u01b0, uy nh\u01b0, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: L\xe2\u0301y \u0111\u01b0\u0301c tin, chi\u0301 ha\u0300nh ma\u0300 giao thi\xea\u0323p, va\u0300 pha\u0309i co\u0301 uy thi\u0300 t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u81ea\u5929\u7950\u4e4b, \u5409, \u65e0\u4e0d\u5229\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: t\u01b0\u0323 thi\xean h\u01b0\u0323u chi, ca\u0301t, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng : t\u01b0\u0323 tr\u01a1\u0300i giu\u0301p cho, t\xf4\u0301t, kh\xf4ng co\u0301 gi\u0300 ma\u0300 ch\u0103\u0309ng l\u01a1\u0323i.\n")
if(s&&r.b===1&&r.c===1&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i Thi\xean \u0110\u1ea1i Tr\xe1ng",c5,r.b,r.c,r.d,r.e,r.f,"C\xd4NG S\u01af \u0110\u1eaeC M\u1ed8C",a7,a9,b0,i,h,g,"","",0,0,4,k,j,r.r[28],"\n\u521d\u4e5d: \u58ef\u4e8e\u8dbe, \u5f81\u51f6, \u6709\u5b5a\uff0e\nS\u01a1 c\u01b0\u0309u: Tra\u0301ng vu chi\u0309, chinh hung, h\u01b0\u0303u phu.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: ma\u0323nh \u01a1\u0309 ngo\u0301n ch\xe2n, \u0111i l\xean thi\u0300 x\xe2\u0301u, co\u0301 th\xea\u0309 tin ch\u0103\u0301c nh\u01b0 v\xe2\u0323y (h\u01b0\u0303u phu \u01a1\u0309 \u0111\xe2y kh\xf4ng co\u0301 nghi\u0303a la\u0300 co\u0301 \u0111\u01b0\u0301c tin nh\u01b0 nh\u01b0\u0303ng n\u01a1i kha\u0301c).\n","\n\u4e5d\u4e8c: \u8c9e\u5409\uff0e\nC\u1eedu nhi\u0323: Trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : co\u0301 \u0111\u01b0\u0301c chi\u0301nh ,t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u5c0f\u4eba\u7528\u58ef, \u541b\u5b50\u7528\u7f54\uff0e\u8c9e\u53b2, \u7f9d\u7f8a\u89f8\u85e9, \u7fb8\u5176\u89d2\uff0e\nC\u1eedu tam: Ti\xea\u0309u nh\xe2n du\u0323ng tra\u0301ng, qu\xe2n t\u01b0\u0309 du\u0323ng vo\u0303ng.\nTrinh l\xea\u0323, \u0111\xea\u0300 d\u01b0\u01a1ng xu\u0301c phi\xean, luy ki\u0300 gia\u0301c.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: ti\xea\u0309u nh\xe2n du\u0300ng s\u01b0\u0301c ma\u0323nh, qu\xe2n t\u01b0\u0309 kh\xf4ng; du\u0300 gi\u01b0\u0303 \u0111i\xea\u0300u chi\u0301nh cu\u0303ng nguy, nh\u01b0 con c\u01b0\u0300u \u0111\u01b0\u0323c hu\u0301c va\u0300o ca\u0301i d\xe2\u0323u, bi\u0323 th\u01b0\u01a1ng ca\u0301i s\u01b0\u0300ng.\n","\n\u4e5d\u56db: \u8c9e\u5409, \u6094\u4ea1, \u85e9\u6c7a\u4e0d\u7fb8\uff0e\u58ef\u4e8e\u5927\u8f3f\u4e4b\u8f39\uff0e\nC\u1eedu t\u01b0\u0301: Trinh ca\u0301t, h\xf4\u0301i vong, phi\xean quy\xea\u0301t b\xe2\u0301t luy, tra\u0301ng vu \u0111a\u0323i d\u01b0 chi phu\u0301c.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : theo \u0111i\xea\u0300u chi\u0301nh thi\u0300 t\xf4\u0301t, h\xf4\u0301i h\xe2\u0323n m\xe2\u0301t h\xea\u0301t; d\xe2\u0323u \u0111a\u0303 m\u01a1\u0309 kh\xf4ng kh\xf4\u0301n n\u01b0\u0303a, ma\u0323nh me\u0303 ti\xea\u0301n l\xean, nh\u01b0 ng\xf4\u0300i c\xf4\u0303 xe l\u01a1\u0301n ma\u0300 tru\u0323c xe v\u01b0\u0303ng va\u0300ng.\n","\n\u516d\u4e94: \u55aa\u7f8a\u4e8e\u6613, \u65e0\u6094\uff0e\nL\u1ee5c ngu\u0303: ta\u0301ng d\u01b0\u01a1ng vu di\u0323, v\xf4 h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o 5, \xe2m: la\u0300m m\xe2\u0301t s\u01b0\u0323 hung h\u0103ng cu\u0309a b\xe2\u0300y c\u01b0\u0300u b\u0103\u0300ng ca\u0301ch vui ve\u0309 d\xea\u0303 da\u0323i, thi\u0300 se\u0303 kh\xf4ng \xe2n h\xe2\u0323n.\n","\n\u4e0a\u516d: \u7f9d\u7f8a\u89f8 \u85e9, \u4e0d\u80fd\u9000, \u4e0d\u80fd\u9042, \u65e0\u6538\u5229, \u8271\u5247\u5409\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: \u0111\xea\u0300 d\u01b0\u01a1ng xu\u0301c phi\xean, b\xe2\u0301t n\u0103ng thoa\u0301i, b\xe2\u0301t n\u0103ng toa\u0323i, v\xf4 du l\u01a1\u0323i, gian t\u0103\u0301c ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: C\u01b0\u0300u \u0111\u01b0\u0323c hu\u0301c va\u0300o d\xe2\u0323u, m\u0103\u0301c ke\u0323t, lui kh\xf4ng \u0111\u01b0\u01a1\u0323c, ti\xea\u0301n cho toa\u0323i y\u0301 cu\u0303ng kh\xf4ng \u0111\u01b0\u01a1\u0323c, kh\xf4ng co\u0301 l\u01a1\u0323i gi\u0300 ca\u0309; chi\u0323u kho\u0301 nho\u0323c thi\u0300 t\xf4\u0301t.\n")
if(s&&r.b===1&&r.c===1&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong Thi\xean Ti\u1ec3u S\xfac",c5,r.b,r.c,r.d,r.e,r.f,"M\u1eacT V\xc2N B\u1ea4T V\u0168",a7,a9,b0,q,p,o,b2,"",3,0,1,b3,"",r.r[35],"\n\u521d \u4e5d : \u5fa9 \u81ea \u9053 , \u4f55 \u5176 \u548e ? \u5409 \uff0e\nS\u01a1 c\u01b0\u0309u: Phu\u0323c t\u01b0\u0323 \u0111a\u0323o, ha\u0300 ky\u0300 c\u01b0\u0303u? Ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : tr\u01a1\u0309 v\xea\u0300 \u0111a\u0323o ly\u0301 cu\u0309a mi\u0300nh, co\u0301 l\xf4\u0303i gi\u0300 \u0111\xe2u? T\xf4\u0301t.\n","\n\u4e5d \u4e8c : \u727d \u5fa9 , \u5409 \uff0e\nC\u1eedu nhi\u0323: khi\xean phu\u0323c, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng. D\u0103\u0301t nhau tr\u01a1\u0309 la\u0323i \u0111a\u0323o ly\u0301 thi\u0300 t\xf4\u0301t.\n","\n\u4e5d \u4e09 : \u8f3f \u8aaa \u8f3b , \u592b \u59bb \u53cd \u76ee \uff0e\nC\u1eedu tam: D\u01b0 thoa\u0301t b\u01b0\u0301c, phu th\xea pha\u0309n mu\u0323c.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : Xe r\u01a1\u0301t m\xe2\u0301t tru\u0323c; v\u01a1\u0323 ch\xf4\u0300ng hu\u0323c h\u0103\u0323c v\u01a1\u0301i nhau.\n","\n\u516d \u56db : \u6709 \u5b5a , \u8840 \u53bb, \u60d5 \u51fa \uff0e \u65e0 \u548e \uff0e\nL\u1ee5c t\u01b0\u0301: h\u01b0\u0303u phu, huy\xea\u0301t kh\u01b0\u0301, di\u0323ch xu\xe2\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: nh\u01a1\u0300 co\u0301 lo\u0300ng chi\u0301 tha\u0300nh, n\xean th\u01b0\u01a1ng ti\u0301ch \u0111\u01b0\u01a1\u0323c la\u0300nh, h\xea\u0301t lo s\u01a1\u0323, ma\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d \u4e94 : \u6709 \u5b5a, \u6523 \u5982 \uff0e \u5bcc \u4ee5 \u5176 \u9130 \uff0e\nC\u1eedu ngu\u0303: H\u01b0\u0303u phu, luy\xean nh\u01b0, phu\u0301 di\u0303 ky\u0300 l\xe2n.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng. Co\u0301 lo\u0300ng tha\u0300nh ti\u0301n, ra\u0300ng bu\xf4\u0323c d\u0103\u0301t di\u0300u (ca\u0309 b\xe2\u0300y ha\u0300o d\u01b0\u01a1ng ), nhi\xea\u0300u ta\u0300i \u0111\u01b0\u0301c , ca\u0309m ho\u0301a \u0111\u01b0\u01a1\u0323c la\u0301ng gi\xea\u0300ng.\n","\n\u4e0a \u4e5d : \u65e2 \u96e8, \u65e2 \u8655 , \u5c1a \u5fb7 \u8f09 \uff0e \u5a66 \u8c9e \u53b2 \uff0e \u6708 \u5e7e \u671b , \u541b \u5b50 \u5f81 \u51f6 \uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Ky\u0301 vu\u0303, ky\u0301 x\u01b0\u0309, th\u01b0\u01a1\u0323ng \u0111\u01b0\u0301c ta\u0301i.\nPhu\u0323 trinh l\xea\u0323. Nguy\xea\u0323t c\u01a1 vo\u0323ng, qu\xe2n t\u01b0\u0309 chinh hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: \u0110a\u0303 m\u01b0a r\xf4\u0300i, y\xean r\xf4\u0300i, \u0111\u01b0\u0301c nhu t\xf4\u0301n cu\u0309a 4 \u0111a\u0303 \u0111\xe2\u0300y (ng\u0103n \u0111\u01b0\u01a1\u0323c \u0111a\u0300n \xf4ng r\xf4\u0300i), v\u01a1\u0323 ma\u0300 c\u01b0\u0301 m\xf4\u0323t m\u01b0\u0323c (trinh) ng\u0103n hoa\u0300i ch\xf4\u0300ng thi\u0300 nguy (l\xea\u0323) \u0111\xe2\u0301y. Tr\u0103ng s\u0103\u0301p \u0111\xea\u0301n \u0111\xeam r\u0103\u0300m (c\u01b0\u0323c thi\u0323nh), ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 (kh\xf4ng th\xe2\u0323n tro\u0323ng, pho\u0300ng bi\u0323) v\xf4\u0323i ti\xea\u0301n ha\u0300nh thi\u0300 x\xe2\u0301u.\n")
if(s&&r.b===1&&r.c===1&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("Th\u1ee7y Thi\xean Nhu",c5,r.b,r.c,r.d,r.e,r.f,"MINH CH\xc2U XU\u1ea4T TH\u1ed4",a7,a9,b0,h,g,a7,b1,"",2,0,4,k,a4,r.r[42],"\n\u521d \u4e5d: \u9700 \u4e8e \u90ca, \u5229 \u7528 \u6046 , \u65e0 \u548e .\nS\u01a1 c\u01b0\u0309u: Nhu vu giao, l\u01a1\u0323i du\u0323ng h\u0103\u0300ng, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1 la\u0300 d\u01b0\u01a1ng, c\u01b0\u01a1ng ki\xea\u0323n, sa\u0301ng su\xf4\u0301t ma\u0300 \u01a1\u0309 xa ngoa\u0323i qua\u0301i la\u0300 Kha\u0309m, t\u01b0\u0301c xa n\u01b0\u01a1\u0301c, xa ch\xf4\u0303 hi\xea\u0309m (cu\u0303ng nh\u01b0 co\u0300n \u01a1\u0309 ngo\u0300ai tha\u0300nh, kh\xf4ng g\xe2\u0300n s\xf4ng n\u01b0\u01a1\u0301c), \u0111\u01b0\u0300ng no\u0301ng na\u0309y x\xf4ng va\u0300o ch\xf4\u0303 hi\xea\u0309m na\u0323n, c\u01b0\u0301 chi\u0323u ch\u01a1\u0300 \u0111\u01a1\u0323i thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i. Chu C\xf4ng khuy\xean nh\u01b0 v\xe2\u0323y vi\u0300 ha\u0300o d\u01b0\u01a1ng na\u0300y kh\xf4ng \u0111\u0103\u0301c trung ma\u0300 co\u0301 y\u0301 mu\xf4\u0301n ti\xea\u0301n.\n","\n\u4e5d \u4e8c: \u9700 \u4e8e \u6c99 , \u5c0f \u6709 \u8a00 , \u7d42 \u5409 \uff0e\nC\u1eedu nhi\u0323: Nhu vu sa, ti\xea\u0309u h\u01b0\u0303u ng\xf4n, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: \u0110\u01a1\u0323i \u01a1\u0309 ba\u0303i ca\u0301t, tuy co\u0301 kh\xe2\u0309u thi\xea\u0323t m\xf4\u0323t chu\u0301t, nh\u01b0ng sau se\u0303 t\xf4\u0301t.\n","\n \u4e5d \u4e09 : \u9700 \u4e8e \u6ce5 \uff0e \u81f4 \u5bc7 \u81f3\uff0e\nC\u1eedu tam: Nhu vu n\xea, tri\u0301 kh\xe2\u0301u chi\u0301.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : \u0111\u01a1\u0323i \u01a1\u0309 ch\xf4\u0303 bu\u0300n l\xe2\u0300y, nh\u01b0 t\u01b0\u0323 mi\u0300nh v\u01a1\u0300i gi\u0103\u0323c \u0111\xea\u0301n.\n","\n\u516d \u56db : \u9700 \u4e8e \u8840, \u51fa \u81ea \u7a74 \uff0e\nL\u1ee5c t\u01b0\u0301: Nhu vu huy\xea\u0301t, xu\xe2\u0301t t\u01b0\u0323 huy\xea\u0323t.\nD\u1ecbch: Ha\u0300o 4, \xe2m: nh\u01b0 \u0111a\u0303 ch\u01a1\u0300 \u0111\u01a1\u0323i \u01a1\u0309 ch\xf4\u0303 l\u01b0u huy\xea\u0301t ma\u0300 r\xf4\u0300i ra kho\u0309i \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d \u4e94 : \u9700 \u4e8e \u9152 \u98df, \u8c9e \u5409 \uff0e\nC\u1eedu ngu\u0303: Nhu vu t\u01b0\u0309u th\u01b0\u0323c, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Ch\u01a1\u0300 \u0111\u01a1\u0323i \u01a1\u0309 ch\xf4\u0303 \u0103n u\xf4\u0301ng no say (ch\xf4\u0303 y\xean vui), b\xea\u0300n gi\u01b0\u0303 \u0111\u01b0\u0301c trung chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u4e0a \u516d:\uff0e \u5165 \u4e8e \u7a74 , \u6709 \u4e0d \u901f \u4e4b \u5ba2 \u4e09 \u4eba \u4f86 , \u656c \u4e4b , \u7d42 \u5409 \uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Nh\xe2\u0323p vu huy\xea\u0323t, h\u01b0\u0303u b\xe2\u0301t t\xf4\u0301c chi kha\u0301ch tam nh\xe2n lai, ki\u0301nh chi, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: Va\u0300o ch\xf4\u0303 c\u01b0\u0323c hi\xea\u0309m r\xf4\u0300i, nh\u01b0ng co\u0301 ba ng\u01b0\u01a1\u0300i kha\u0301ch thu\u0309ng th\u0103\u0309ng t\u01a1\u0301i, bi\xea\u0301t ki\u0301nh tro\u0323ng ho\u0323 thi\u0300 sau \u0111\u01b0\u0323\u01a1c t\xf4\u0301t la\u0300nh.\n")
if(s&&r.b===1&&r.c===1&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n Thi\xean \u0110\u1ea1i S\xfac",c5,r.b,r.c,r.d,r.e,r.f,"TR\u1eacN TH\u1ebe \u0110\u1eaeC KHAI",a7,a9,b0,g,a7,a9,"Ph\u1ee5 Ng\u1ecd",b4,2,3,2,b5,"",r.r[49],"\n\u521d\u4e5d\uff0e\u6709\u53b2\uff0e\u5229\u5df2\uff0e\nS\u01a1 c\u01b0\u0309u: H\u01b0\u0303u l\xea\u0323, l\u01a1\u0323i di\u0303.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : co\u0301 nguy, ng\u01b0ng la\u0323i thi\u0300 l\u01a1\u0323i.\n","\n\u4e5d\u4e8c: \u8f3f\u8aaa\u8f39\uff0e\nC\u1eedu nhi\u0323: D\u01b0 thoa\u0301t phu\u0301c.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng, nh\u01b0 chi\xea\u0301c xe \u0111a\u0303 tha\u0301o ca\u0301i tru\u0323c,nh\u01b0 v\xe2\u0323y kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e09: \u826f\u99ac\u9010; \u5229\u8271\u8c9e\uff0e\u65e5\u9591\u8f3f\u885b, \u5229\u6709\u6538\u5f80\uff0e\nC\u1eedu tam: L\u01b0\u01a1ng ma\u0303 tru\u0323c; l\u01a1\u0323i gian trinh,\nNh\xe2\u0323t nha\u0300n d\u01b0 v\xea\u0323, l\u01a1\u0323i h\u01b0\u0303u du va\u0303ng.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : nh\u01b0 hai con ng\u01b0\u0323a t\xf4\u0301t cha\u0323y \u0111ua nhau; pha\u0309i chi\u0323u kho\u0301 gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 co\u0301 l\u01a1\u0323i, la\u0323i pha\u0309i th\u01b0\u01a1\u0300ng nga\u0300y luy\xea\u0323n t\xe2\u0323p, d\u01b0\u0323 bi\u0323 ca\u0301c \u0111\xf4\u0300 h\xf4\u0323 th\xe2n thi\u0300 ti\xea\u0301n l\xean m\u01a1\u0301i co\u0301 l\u01a1\u0323i.\n","\n\u516d\u56db: \u7ae5\u725b\u4e4b\u727f, \u5143\u5409\uff0e\nL\u1ee5c t\u01b0\u0301: \u0111\xf4\u0300ng ng\u01b0u chi c\xf4\u0301c, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, \xe2m: nh\u01b0 con bo\u0300 m\xf4\u0323ng co\u0300n non, m\u01a1\u0301i nhu\u0301 s\u01b0\u0300ng, \u0111\u0103\u0323t ngay ma\u0309nh g\xf4\u0303 ch\u0103\u0323n s\u01b0\u0300ng no\u0301, thi\u0300 r\xe2\u0301t t\xf4\u0301t.\n","\n\u516d\u4e94: \u8c76\u8c55\u4e4b\u7259, \u5409\uff0e\nL\u1ee5c ngu\u0303: Ph\xe2\u0300n thi\u0309 chi nha, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Nh\u01b0 th\xea\u0309 ng\u0103n ca\u0301i nanh con heo \u0111a\u0303 thi\xea\u0301n thi\u0300 t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u4f55\u5929\u4e4b\u8862, \u4ea8\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: ha\u0300 thi\xean chi cu\u0300, hanh.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng. Sao ma\u0300 th\xf4ng su\xf4\u0301t nh\u01b0 d\u01b0\u01a1ng tr\xean tr\u01a1\u0300i v\xe2\u0323y.\n")
if(s&&r.b===1&&r.c===0&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba Tr\u1ea1ch L\xe2m",c5,r.b,r.c,r.d,r.e,r.f,"PH\xc1T CH\xcdNH THI NH\xc2N",p,o,n,n,m,l,"","",0,0,2,k,"",r.r[57],"\n\u521d\u4e5d: \u54b8\u81e8, \u8c9e\u5409.\nS\u01a1 c\u01b0\u0309u: Ha\u0300m l\xe2m, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : Cu\u0300ng t\u01a1\u0301i, gi\u01b0\u0303 chi\u0301nh \u0111a\u0323o thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e8c: \u54b8\u81e8, \u5409, \u65e0\u4e0d\u5229\uff0e\nC\u1eedu nhi\u0323: Ha\u0300m l\xe2m, ca\u0301t, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : cu\u0300ng t\u01a1\u0301i, t\xf4\u0301t, kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n","\n\u516d\u4e09: \u7518\u81e8, \u65e0\u6538\u5229; \u65e2\u6182\u4e4b, \u65e0\u548e\uff0e\nL\u1ee5c tam: Cam l\xe2m, v\xf4 du l\u01a1\u0323i; Ki\u0301 \u01b0u chi, c\xf4 c\u01b0\u0309u.\nD\u1ecbch: Ha\u0300o 3 \xe2m: Ngo\u0323t nga\u0300o (a dua) ma\u0300 t\u01a1\u0301i (\u0111\xea\u0309 du\u0323 d\xf4\u0303 ha\u0300o 2) thi\u0300 kh\xf4ng co\u0301 l\u01a1\u0323i \u0111\xe2u; nh\u01b0ng \u0111a\u0303 bi\xea\u0301t lo s\u01b0\u0309a ti\u0301nh thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i n\u01b0\u0303a.\n","\n\u56db: \u81f3\u81e8, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: Chi l\xe2m, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: H\xea\u0301t lo\u0300ng tha\u0300nh th\u01b0\u0323c t\u01a1\u0301i v\u01a1\u0301i ha\u0300o 1, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94: \u77e5\u81e8, \u5927\u541b\u4e4b\u5b9c, \u5409\uff0e\nL\u1ee5c ngu\u0303: Tri\u0301 l\xe2m, \u0111a\u0323i qu\xe2n chi nghi, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Du\u0300ng \u0111\u01b0\u0301c sa\u0301ng su\xf4\u0301t ma\u0300 t\u01a1\u0301i, \u0111u\u0301ng la\u0300 t\u01b0 ca\u0301ch m\xf4\u0323t vi\u0323 nguy\xean thu\u0309, t\xf4\u0301t.\n","\n\u4e0a\u516d: \u6566\u81e8, \u5409, \u65e0\u548e\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: \u0110\xf4n l\xe2m, ca\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: L\xe2\u0301y lo\u0300ng \u0111\xf4n h\xe2\u0323u ma\u0300 t\u01a1\u0301i (v\u01a1\u0301i \u0111\u01a1\u0300i), t\xf4\u0301t, kh\xf4ng co\u0301 l\xf4\u0303i.\n")
if(s&&r.b===1&&r.c===0&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean Tr\u1ea1ch L\xfd",c5,r.b,r.c,r.d,r.e,r.f,"PH\u1ee4NG MINH K\u1ef2 S\u01a0N",p,o,n,i,h,g,b6,"",5,0,5,b5,"",r.r[0],"\n\u521d \u4e5d : \u7d20 \u5c65, \u5f80 , \u65e0 \u548e \uff0e\nS\u01a1 c\u01b0\u0309u: t\xf4\u0301 ly\u0301, va\u0303ng, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: ha\u0300o 1, d\u01b0\u01a1ng : gi\u01b0\u0303 ba\u0309n ch\xe2\u0301t trong tr\u0103\u0301ng ma\u0300 ra v\u01a1\u0301i \u0111\u01a1\u0300i thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d \u4e8c : \u5c65 \u9053 \u5766 \u5766 , \u5e7d \u4eba \u8c9e \u5409 \uff0e\nC\u1eedu nhi\u0323: Ly\u0301 \u0111a\u0323o tha\u0309n tha\u0309n, u nh\xe2n trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: nh\u01b0 \u0111i tr\xean \u0111\u01b0\u01a1\u0300ng b\u0103\u0300ng ph\u0103\u0309ng, c\u01b0\u0301 m\xf4\u0323t mi\u0300nh gi\u01b0\u0303 v\u01b0\u0303ng \u0111\u01b0\u01a1\u0300ng chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u516d \u4e09 : \u7707, \u80fd \u8996 ; \u8ddb, \u80fd \u5c65 \uff0e \u5c65 \u864e \u5c3e , \u54a5 \u4eba, \u51f6 \uff0e \u6b66 \u4eba \u70ba \u4e8e \u5927 \u541b \uff0e\nL\u1ee5c tam: Mi\xea\u0303u, n\u0103ng thi\u0323; ba\u0309, n\u0103ng ly\u0301.\nLy\u0301 h\xf4\u0309 vi\u0303, di\xea\u0323t nh\xe2n, hung. Vo\u0303 nh\xe2n vi vu \u0111a\u0323i qu\xe2n.\nD\u1ecbch: Ha\u0300o 3, \xe2m: ch\xf4\u0323t (ma\u0300 t\u01b0\u0323 phu\u0323 la\u0300) th\xe2\u0301y to\u0309, tho\u0323t (ma\u0300 t\u01b0\u0323 phu\u0323 la\u0300) \u0111i nhanh, nh\u01b0 v\xe2\u0323y thi\u0300 nguy nh\u01b0 d\xe2\u0303m l\xean \u0111u\xf4i co\u0323p ma\u0300 bi\u0323 no\u0301 c\u0103\u0301n. \u0110o\u0301 la\u0300 ke\u0309 vu\u0303 phu ma\u0300 \u0111o\u0300i la\u0300m vi\xea\u0323c cu\u0309a m\xf4\u0323t \xf4ng vua l\u01a1\u0301n.\n","\n\u4e5d \u56db : \u5c65 \u864e \u5c3e \uff0e \u612c \u612c \u7d42 \u5409 \uff0e\nC\u1eedu t\u01b0\u0301: Li\u0301 h\xf4\u0309 vi\u0303, sa\u0301ch sa\u0301ch (ho\u0103\u0323c so\u0301c so\u0301c)chung ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: D\xe2\u0303m l\xean \u0111u\xf4i co\u0323p, nh\u01b0ng bi\xea\u0301t s\u01a1\u0323 ha\u0303i, n\xean que\u0309 se\u0303 t\xf4\u0301t.\n","\n\u4e5d \u4e94 : \u592c \u5c65 \u8c9e \u53b2 \uff0e\nC\u1eedu ngu\u0303: Quy\xea\u0301t ly\u0301, trinh l\xea\u0323.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng : Quy\xea\u0301t t\xe2m ha\u0300nh \u0111\xf4\u0323ng qua\u0301 thi\u0300 tuy chi\u0301nh \u0111a\u0301ng cu\u0303ng co\u0301 th\xea\u0309 nguy.\n","\n\u4e0a \u4e5d: \u8996 \u5c65, \u8003 \u7965 \uff0e \u5176 \u65cb, \u5143 \u5409 \uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Thi\u0323 ly\u0301, kha\u0309o t\u01b0\u01a1\u0300ng, ky\u0300 toa\u0300n, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng, xem ca\u0301ch \u0103n \u01a1\u0309 trong \u0111\u01a1\u0300i ng\u01b0\u01a1\u0300i, cho n\xean Ha\u0300o t\u01b0\u0300 di\xea\u0303n y\u0301 nghi\u0303a cu\u0309a toa\u0300n que\u0309 ch\u01b0\u0301 kh\xf4ng di\xea\u0303n y\u0301 nghi\u0303a cu\u0309a ri\xeang ha\u0300o cu\xf4\u0301i. Cu\u0303ng la\u0300 m\xf4\u0323t l\xea\u0323 ngoa\u0323i nh\u01b0 ha\u0300o cu\xf4\u0301i cu\u0300ng que\u0309 Ti\xea\u0309u su\u0301c.\n")
if(s&&r.b===1&&r.c===0&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("B\xe1t Thu\u1ea7n \u0110o\xe0i",c5,r.b,r.c,r.d,r.e,r.f,"CHU\u1ea8N TH\u1ee6Y H\xd2A N\xca",p,o,n,m,l,q,"","",0,0,6,a3,j,r.r[15],"\n\u521d\u4e5d: \u548c\u514c\u5409\uff0e\nS\u01a1 c\u01b0\u0309u: Hoa\u0300 \u0111oa\u0301i, ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: Hoa\u0300 thu\xe2\u0323n, vui ve\u0309, t\xf4\u0301t.\n","\n\u4e5d\u4e8c\uff0e\u5b5a\u514c\u5409\uff0e\u6094\u4ea1\uff0e\nC\u1eedu nhi\u0323: Phu \u0111oa\u0300i, ca\u0301t, h\xf4\u0301i vong.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: Trung tr\u01b0\u0323c ma\u0300 vui ve\u0309, t\xf4\u0301t, h\xf4\u0301i h\xe2\u0323n m\xe2\u0301t \u0111i.\n","\n\u516d\u4e09: \u4f86\u514c\u51f6\uff0e\nL\u1ee5c tam: Lai \u0111oa\u0300i, hung.\nD\u1ecbch: Ha\u0300o 3, \xe2m: Quay la\u0323i c\xe2\u0300u vui v\u01a1\u0301i ng\u01b0\u01a1\u0300i \u01a1\u0309 d\u01b0\u01a1\u0301i, x\xe2\u0301u.\n","\n\u4e5d\u56db: \u5546\u514c, \u672a\u5be7, \u4ecb\u75be,\u6709\u559c\uff0e\nC\u1eedu t\u01b0\u0301; Th\u01b0\u01a1ng \u0111oa\u0300i, vi\u0323 ninh, gi\u01a1\u0301i t\xe2\u0323t, h\u01b0\u0303u hi\u0309.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: c\xe2n nh\u0103\u0301c xem n\xean c\xe2\u0300u vui \u01a1\u0309 phi\u0301a na\u0300o ma\u0300 ch\u01b0a quy\xea\u0301t \u0111i\u0323nh \u0111\u01b0\u01a1\u0323c r\xf4\u0300i sau theo chi\u0301nh bo\u0309 ta\u0300, \u0111a\u0301ng m\u01b0\u0300ng.\n","\n\u4e5d\u4e94: \u5b5a\u4e8e\u525d, \u6709\u53b2\uff0e\nC\u1eedu ngu\u0303 : Phu vu ba\u0301c, h\u01b0\u0303u l\xea\u0323.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: N\xea\u0301u tin ke\u0309 ti\xea\u0309u nh\xe2n ma\u0300 ti\xeau mo\u0300n (ba\u0301c) h\xea\u0301t \u0111\u01b0\u0301c trung chi\u0301nh cu\u0309a mi\u0300nh thi\u0300 nguy.\n","\n\u4e0a\u516d: \u5f15\u514c\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: D\xe2\u0303n \u0111oa\u0300i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: \u0110em s\u01b0\u0323 vui thu\u0301 t\u01a1\u0301i.\n")
if(s&&r.b===1&&r.c===0&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa Tr\u1ea1ch Khu\xea",c5,r.b,r.c,r.d,r.e,r.f,"PH\u1ea2N M\u1ea0I TR\u01af D\u01af\u01a0NG",p,o,n,l,q,p,b6,"",5,0,4,b5,"",r.r[22],"\n\u521d\u4e5d: \u6094\u4ea1, \u55aa\u99ac, \u52ff\u9010, \u81ea\u5fa9. \u898b\u60e1\u4eba\uff0e\u65e0\u548e\uff0e \nS\u01a1 c\u01b0\u0309u: H\xf4\u0301i vong, ta\u0301ng ma\u0303, v\xe2\u0323t tru\u0323c, t\u01b0\u0323 phu\u0323c ki\xea\u0301n a\u0301c nh\xe2n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: h\xf4\u0301i h\xe2\u0323n ti\xeau h\xea\u0301t; m\xe2\u0301t ng\u01b0\u0323a \u0111\u01b0\u0300ng ti\u0300m \u0111u\xf4\u0309i, t\u01b0\u0323 no\u0301 se\u0303 v\xea\u0300: g\u0103\u0323p ke\u0309 a\u0301c r\xf4\u0300i m\u01a1\u0301i tra\u0301nh \u0111\u01b0\u01a1\u0323c l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u9047\u4e3b\u4e8e\u5df7, \u65e0\u548e\uff0e\nC\u1eedu nhi\u0323: Ng\xf4\u0323 chu\u0309 vu ha\u0323ng, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: g\u0103\u0323p chu\u0309 trong ngo\u0303 he\u0323p (do \u0111\u01b0\u01a1\u0300ng t\u0103\u0301t) kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e09: \u898b\u8f3f\u66f3, \u5176\u725b\u63a3; \u5176\u4eba\u5929\u4e14\u5293\uff0e\u65e0\u521d\u6709\u7d42\uff0e\nL\u1ee5c tam: Ki\xea\u0301n d\u01b0 du\xea\u0323, ki\u0300 ng\u01b0u x\xea\u0323 (hay xi\xea\u0323t);\nKi\u0300 nh\xe2n thi\xean tha\u0309 nghi\u0323, v\xf4 s\u01a1 h\u01b0\u0303u chung.\nD\u1ecbch: Ha\u0309o, \xe2m: Th\xe2\u0301y xe d\u0103\u0301t t\u01a1\u0301i, nh\u01b0ng con bo\u0300 bi\u0323 (ha\u0300o 4) ca\u0309n, kh\xf4ng ti\xea\u0301n \u0111\u01b0\u01a1\u0323c; nh\u01b0 ng\u01b0\u01a1\u0300i bi\u0323 x\xe2m va\u0300o m\u0103\u0323t, xe\u0309o mu\u0303i, m\u01a1\u0301i \u0111\xe2\u0300u ca\u0301ch tr\u01a1\u0309, sau ho\u0300a h\u01a1\u0323p v\u01a1\u0301i nhau.\n","\n\u4e5d\u56db: \u777d\u5b64, \u9047\u5143\u592b, \u4ea4\u5b5a, \u53b2\u65e0\u548e\uff0e\nC\u1eedu t\u01b0\u0301: Khu\xea c\xf4, ng\xf4\u0323 nguy\xean phu, giao phu, l\xea\u0323 v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: \u01a1\u0309 th\u01a1\u0300i chia li\u0300a ch\xf4\u0301ng \u0111\xf4\u0301i ma\u0300 c\xf4 l\xe2\u0323p; n\xea\u0301u g\u0103\u0323p \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i trai t\xf4\u0301t (nguy\xean phu), ma\u0300 chi\u0301 tha\u0300nh k\xea\u0301t h\u01a1\u0323p v\u01a1\u0301i nhau (giao phu) thi\u0300 du\u0300 co\u0301 g\u0103\u0323p nguy, k\xea\u0301t qua\u0309 cu\u0303ng kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94: \u6094\u4ea1, \u53a5\u5b97\u566c\u819a, \u5f80, \u4f55\u548e\uff0e\nL\u1ee5c ngu\u0303: h\xf4\u0301i vong, quy\xea\u0301t t\xf4n ph\xea\u0323 phu, va\u0303ng, ha\u0300 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5 \xe2m, h\xf4\u0301i h\xe2\u0323n ti\xeau h\xea\u0301t; n\xea\u0301u ng\u01b0\u01a1\u0300i cu\u0300ng phe v\u01a1\u0301i mi\u0300nh c\u0103\u0301n va\u0300o da mi\u0300nh (h\xea\u0301t s\u01b0\u0301c giu\u0301p \u0111\u01a1\u0303 mi\u0300nh) thi\u0300 ti\xea\u0301n \u0111i, kh\xf4ng co\u0301 l\xf4\u0303i gi\u0300 ca\u0309.\n","\n\u4e0a\u4e5d: \u777d\u5b64, \u898b\u8c55\u8ca0\u5857, \u8f09\u9b3c\u4e00\u8eca\uff0e\u5148\u5f35\u4e4b\u5f27, \u5f8c\u8aaa\u4e4b\u5f27, \u532a\u5bc7, \u5a5a\u5abe\uff0e\u5f80\u9047\u96e8\u5247\u5409\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Khu\xea c\xf4, ki\xea\u0301n thi\u0309 phu\u0323 \u0111\xf4\u0300, ta\u0309i qui\u0309 nh\xe2\u0301t xa. Ti\xean tr\u01b0\u01a1ng chi h\xf4\u0300, h\xe2\u0323u thoa\u0301t chi h\xf4\u0300, phi\u0309 kh\xe2\u0301u, h\xf4n c\xe2\u0301u. Va\u0303ng ng\xf4\u0323 vu\u0303 t\u0103\u0301c ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: \u01a1\u0309 th\u01a1\u0300i chia li\u0300a ma\u0300 c\xf4 \u0111\xf4\u0323c (sinh nghi ky\u0323), th\xe2\u0301y con heo \u0111\xf4\u0323i \u0111\xe2\u0300y bu\u0300n, th\xe2\u0301y ch\u01a1\u0309 qui\u0309 \u0111\xe2\u0300y m\xf4\u0323t xe. M\u01a1\u0301i \u0111\xe2\u0300u gi\u01b0\u01a1ng cung \u0111\xea\u0309 b\u0103\u0301n, sau bu\xf4ng cung xu\xf4\u0301ng, xin l\xf4\u0303i r\u0103\u0300ng mi\u0300nh kh\xf4ng mu\xf4\u0301n la\u0300m ha\u0323i ha\u0300o 3 ma\u0300 mu\xf4\u0301n c\xe2\u0300u h\xf4n. (Hai b\xean ho\u0300a h\u01a1\u0323p nhau, vui ve\u0309) nh\u01b0 sau khi n\u0103\u0301ng l\xean, g\u0103\u0323p c\u01a1n m\u01b0a, t\xf4\u0301t la\u0300nh gi\u0300 h\u01a1n?\n")
if(s&&r.b===1&&r.c===0&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i Tr\u1ea1ch Quy Mu\u1ed9i",c5,r.b,r.c,r.d,r.e,r.f,"DUY\xcaN M\u1ed8C C\u1ea6U NG\u01af",p,o,n,i,h,g,"T\u1eed H\u1ee3i","",4,0,3,a3,a8,r.r[29],"\n\u521d\u4e5d: \u6b78\u59b9\u4ee5\u5a23, \u8ddb\u80fd\u5c65, \u5f81\u5409\uff0e\nS\u01a1 c\u01b0\u0309u: Qui mu\xf4\u0323i di\u0303 qui \u0111\xea\u0323, ba\u0309 n\u0103ng ly\u0301, chinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: Em ga\u0301i v\xea\u0300 nha\u0300 ch\xf4\u0300ng la\u0300m v\u01a1\u0323 be\u0301, ch\xe2n tho\u0323t ma\u0300 \u0111i \u0111\u01b0\u01a1\u0323c, ti\xea\u0301n \u0111i thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e8c: \u7707\u80fd\u8996, \u5229\u5e7d\u4eba\u4e4b\u8c9e\uff0e\nC\u1eedu nhi\u0323: Di\xea\u0309u (mi\xea\u0309u) n\u0103ng thi\u0323, l\u01a1\u0323i u nh\xe2n chi trinh.\nD\u1ecbch : Ha\u0300o 2, d\u01b0\u01a1ng: ch\xf4\u0323t ma\u0300 th\xe2\u0301y \u0111\u01b0\u01a1\u0323c \xe2m th\xe2\u0300m gi\u01b0\u0303 \u0111\u01b0\u0301c trinh chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e09: \u6b78\u59b9\u4ee5\u9808, \u53cd\u6b78\u4ee5\u5a23\uff0e\nL\u1ee5c tam: qui mu\xf4\u0323i di\u0303 tu, pha\u0309n qui di\u0303 \u0111\xea\u0323.\nD\u1ecbch: Ha\u0300o 3, \xe2m: Em ga\u0301i v\xea\u0300 nha\u0300 ch\xf4\u0300ng, ch\u01a1\u0300 \u0111\u01a1\u0323i ma\u0303i, no\u0301ng lo\u0300ng tr\u01a1\u0309 v\xea\u0300 la\u0300m v\u01a1\u0323 be\u0301.\n","\n\u4e5d\u56db: \u6b78\u59b9, \u6106\u671f, \u9072\u6b78, \u6709\u6642\uff0e\nC\u1eedu t\u01b0\u0301: Qui mu\xf4\u0323i, khi\xean ki\u0300, tri\u0300 qui, h\u01b0\u0303u th\u01a1\u0300i.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: em ga\u0301i v\xea\u0300 nha\u0300 ch\xf4\u0300ng, l\u01a1\u0303 th\u01a1\u0300i; nh\u01b0ng du\u0300 ch\xe2\u0323m ga\u0309 i\u0301t l\xe2u, r\xf4\u0300i cu\u0303ng se\u0303 co\u0301 lu\u0301c g\u0103\u0323p \u0111\u01b0\u0323\u01a1c ch\xf4\u0300ng t\xf4\u0301t..\n","\n\u516d\u4e94: \u5e1d\u4e59\u6b78\u59b9, \u5176\u541b\u4e4b\u8882, \u4e0d\u5982\u5176\u5a23\u4e4b\u8882\u826f, \u6708\u5e7e\u671b, \u5409\uff0e\nL\u1ee5c ngu\u0303: \u0110\xea\u0301 \xc2\u0301t qui mu\xf4\u0323i, ki\u0300 qu\xe2n chi du\xea\u0323, b\xe2\u0301t nh\u01b0 ki\u0300 \u0111\xea\u0323 chi du\xea\u0323 l\u01b0\u01a1ng, nguy\xea\u0323t c\u01a1 vo\u0323ng, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Vua \u0110\xea\u0301 \xc2\u0301t (nha\u0300 Th\u01b0\u01a1ng) cho em ga\u0301i v\xea\u0300 nha\u0300 ch\xf4\u0300ng, tay a\u0301o cu\u0309a c\xf4ng chu\u0301a (c\xf4 d\xe2u) kh\xf4ng \u0111e\u0323p b\u0103\u0300ng tay a\u0301o cu\u0309a c\xf4 phu\u0300 d\xe2u (v\u01a1\u0323 be\u0301); nh\u01b0 tr\u0103ng \u0111\xeam mu\u01a1\u0300i b\xf4\u0301n (s\u0103\u0301p \u0111\xea\u0301n r\u0103\u0300m) t\xf4\u0301t.\n","\n\u4e0a\u516d: \u5973\u627f\u7b50, \u65e0\u5be6\uff0e\u58eb\u5232\u7f8a, \u65e0\u8840, \u65e0\u6538\u5229\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: N\u01b0\u0303 th\u01b0\u0300a khu\xf4ng ,v\xf4 th\u01b0\u0323c.\nSi\u0303 khu\xea d\u01b0\u01a1ng, v\xf4 huy\xea\u0301t, v\xf4 du l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: (\u0110\xea\u0309 cu\u0301ng t\xf4\u0309 ti\xean) ng\u01b0\u01a1\u0300i con ga\u0301i (v\u01a1\u0323) xa\u0301ch gio\u0309 ma\u0300 gio\u0309 kh\xf4ng co\u0301 \u0111\xf4\u0300 cu\u0301ng, ng\u01b0\u01a1\u0300i con trai (ch\xf4\u0300ng) c\u0103\u0301t c\xf4\u0309 con c\u01b0\u0300u \u0111\xea\u0309 l\xe2\u0301y huy\xea\u0301t ma\u0300 (c\u0103\u0301t gia\u0309 v\u01a1\u0300) kh\xf4ng co\u0301 huy\xea\u0301t, kh\xf4ng co\u0301 gi\u0300 l\u01a1\u0323i ca\u0309.\n")
if(s&&r.b===1&&r.c===0&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong Tr\u1ea1ch Trung Phu",c5,r.b,r.c,r.d,r.e,r.f,"H\xc0NH T\u1ea8U B\u1ea0C B\u0102NG",p,o,n,q,p,o,b4,b6,3,5,4,b5,a4,r.r[36],"\n\u521d\u4e5d: \u865e\u5409, \u6709\u5b83, \u4e0d\u71d5\uff0e\nS\u01a1 c\u01b0\u0309u: Ngu ca\u0301t, h\u01b0\u0303u tha, b\xe2\u0301t y\xea\u0301n.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: li\xea\u0323u ti\u0301nh cho ch\u0103\u0301c ch\u0103\u0301n r\xf4\u0300i m\u01a1\u0301i tin thi\u0300 t\xf4\u0301t; co\u0301 lo\u0300ng nghi\u0303 kha\u0301c thi\u0300 kh\xf4ng y\xean.\n","\n\u4e5d\u4e8c: \u9db4\u9cf4\u5728\u9670\uff0e\u5176\u5b50\u548c\u4e4b\uff0e\u6211\u6709\u597d\u7235\uff0e\u543e\u8207\u723e\u9761\u4e4b\uff0e\nC\u1eedu nhi\u0323: Minh ha\u0323c ta\u0323i \xe2m, ky\u0300 t\u01b0\u0309 hoa\u0323 chi;\nNga\u0303 h\u01b0\u0303u ha\u0309o t\u01b0\u01a1\u0301c, ng\xf4 d\u01b0\u0303 nhi\u0303 mi\u0303 chi.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: Nh\u01b0 con ha\u0323c me\u0323 ga\u0301y \u01a1\u0309 bo\u0301ng r\xe2m, con con no\u0301 hoa\u0323 la\u0323i; la\u0323i nh\u01b0 t\xf4i co\u0301 che\u0301n r\u01b0\u01a1\u0323u ngon, t\xf4i cu\u0300ng anh chia nhau.\n","\n\u516d\u4e09: \u5f97\u6575, \u6210\u9f13, \u6216\u7f77, \u6216\u6ce3, \u6216\u6b4c\uff0e\nL\u1ee5c tam: \u0110\u0103\u0301c di\u0323ch, ho\u0103\u0323c c\xf4\u0309, ho\u0103\u0323c ba\u0303i, ho\u0103\u0323c kh\xe2\u0301p, ho\u0103\u0323c ca.\nD\u1ecbch: Ha\u0300o 3, \xe2m: g\u0103\u0323p \u0111\u01b0\u01a1\u0323c ba\u0323n (\u0111i\u0323ch) lu\u0301c thi\u0300 \u0111a\u0301nh tr\xf4\u0301ng vui mu\u0301a, lu\u0301c thi\u0300 cha\u0301n na\u0309n ma\u0300 ng\u01b0\u0300ng, lu\u0301c thi\u0300 kho\u0301c, lu\u0301c thi\u0300 ha\u0301t.\n","\n\u516d\u56db: \u6708\u5e7e\u671b, \u99ac\u5339\u4ea1, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: Nguy\xea\u0323t c\u01a1 vo\u0323ng, ma\u0303 th\xe2\u0301t vong, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Tr\u0103ng m\u01b0\u01a1\u0300i b\xf4\u0301n (g\xe2\u0300n t\u01a1\u0301i r\u0103\u0300m), con ng\u01b0\u01a1\u0300i bo\u0309 ba\u0323n ma\u0300 ti\xea\u0301n l\xean, kh\xf4ng l\xf4\u0303i.\n","\n\u4e5d\u4e94: \u6709\u5b5a\u6523\u5982, \u65e0\u548e\uff0e\nC\u1eedu ngu\u0303: H\u01b0\u0303u phu luy\xea\u0301n nh\u01b0, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: co\u0301 lo\u0300ng chi\u0301 tha\u0300nh ra\u0300ng bu\xf4\u0323c, kh\xf4ng l\xf4\u0303i.\n","\n\u4e0a\u4e5d: \u7ff0\u97f3\u767b\u4e8e\u5929, \u8c9e\u51f6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Ha\u0300n \xe2m \u0111\u0103ng vu thi\xean, trinh hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: ti\xea\u0301ng ga\u0300 l\xean t\xe2\u0323n tr\u01a1\u0300i, du\u0300 co\u0301 chi\u0301nh \u0111a\u0301ng cu\u0303ng x\xe2\u0301u.\n")
if(s&&r.b===1&&r.c===0&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("Th\u1ee7y Tr\u1ea1ch Ti\u1ebft",c5,r.b,r.c,r.d,r.e,r.f,"TR\u1ea2M T\u01af\u1edaNG PHONG TH\u1ea6N",p,o,n,h,g,a7,"","",0,0,1,b7,d,r.r[43],"\n\u521d\u4e5d: \u4e0d\u51fa\u6236\u5ead, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: B\xe2\u0301t xu\xe2\u0301t h\xf4\u0323i \u0111i\u0300nh, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: kh\xf4ng ra kho\u0309i s\xe2n ngo\u0303, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u4e0d\u51fa\u9580\u5ead, \u51f6\uff0e\nC\u1eedu nhi\u0323: B\xe2\u0301t xu\xe2\u0301t m\xf4n \u0111i\u0300nh, hung.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: kh\xf4ng ra kho\u0309i ca\u0301i s\xe2n \u01a1\u0309 trong c\u01b0\u0309a, x\xe2\u0301u.\n","\n\u516d\u4e09: \u4e0d\u7bc0\u82e5, \u5247\u55df\u82e5,\u65e0\u548e\uff0e\nL\u1ee5c tam: B\xe2\u0301t ti\xea\u0301t nh\u01b0\u01a1\u0323c, t\xe2\u0301t ta nh\u01b0\u01a1\u0323c, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, \xe2m: kh\xf4ng de\u0300 d\u0103\u0323t (t\u01b0\u0323 ti\xea\u0301t ch\xea\u0301 mi\u0300nh) ma\u0300 pha\u0309i than va\u0303n, kh\xf4ng \u0111\xf4\u0309 l\xf4\u0303i cho ai \u0111\u01b0\u01a1\u0323c.\n","\n\u516d\u56db\uff0e\u5b89\u7bc0,\u4ea8\uff0e\nL\u1ee5c t\u01b0\u0301: An ti\xea\u0301t, hanh.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Vui ve\u0309 t\u01b0\u0323 ti\xea\u0301t ch\xea\u0301 (kh\xf4ng mi\xea\u0303n c\u01b0\u01a1\u0303ng) hanh th\xf4ng.\n","\n\u4e5d\u4e94: \u7518\u7bc0, \u5409\uff0e\u5f80\u6709\u5c1a\uff0e\nC\u1eedu ngu\u0303: Cam ti\xea\u0301t, ca\u0301t. Va\u0303ng h\u01b0\u0303u th\u01b0\u01a1\u0323ng.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Ti\xea\u0301t ch\xea\u0301 ma\u0300 vui ve\u0309 (cho la\u0300 ngon ngo\u0323t) thi\u0300 t\xf4\u0301t. C\u01b0\u0301 th\xea\u0301 ma\u0300 ti\xea\u0301n ha\u0300nh thi\u0300 \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i ta tro\u0323ng, khen.\n","\n\u4e0a\u516d: \u82e6\u7bc0, \u8c9e\u51f6, \u6094\u4ea1\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Kh\xf4\u0309 ti\xea\u0301t, trinh hung. H\xf4\u0301i vong.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: Ti\xea\u0301t ch\xea\u0301 ma\u0300 t\u01a1\u0301i m\u01b0\u0301c c\u01b0\u0323c kh\xf4\u0309, n\xea\u0301u c\u01b0\u0301 gi\u01b0\u0303 ma\u0303i (trinh) th\xf4i \u0111o\u0301 thi\u0300 x\xe2\u0301u. N\xea\u0301u bi\xea\u0301t h\xf4\u0301i h\xe2\u0323n, b\u01a1\u0301t tha\u0301i qua\u0301 \u0111i thi\u0300 h\xea\u0301t x\xe2\u0301u.\n")
if(s&&r.b===1&&r.c===0&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n Tr\u1ea1ch T\u1ed5n",c5,r.b,r.c,r.d,r.e,r.f,"TH\xd4I XA PH\xcd L\u1ef0C",p,o,n,g,a7,a9,b4,"",3,0,3,b5,"",r.r[50],"\n\u521d\u4e5d: \u5df2\u4e8b\u9044\u5f80, \u65e0\u548e, \u914c\u640d\u4e4b\uff0e\nS\u01a1 c\u01b0\u0309u: Di\u0303 s\u01b0\u0323 thuy\xean va\u0303ng, v\xf4 c\u01b0\u0303u, ch\u01b0\u01a1\u0301c t\xf4\u0309n chi.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: nghi\u0309 vi\xea\u0323c cu\u0309a mi\u0300nh ma\u0300 ti\xea\u0301n l\xean g\xe2\u0301p, giu\u0301p (cho ha\u0300o 4) nh\u01b0 v\xe2\u0323y thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i, nh\u01b0ng n\xean ch\xe2m ch\u01b0\u01a1\u0301c ca\u0301i gi\u0300 n\xean ru\u0301t b\u01a1\u0301t cu\u0309a mi\u0300nh \u0111\xea\u0309 giu\u0301p cho 4 thi\u0300 ha\u0303y ru\u0301t.\n","\n\u4e5d\u4e8c: \u5229\u8c9e, \u5f81\u51f6, \u5f17\u640d\u76ca\u4e4b\uff0e\nC\u1eedu nhi\u0323: l\u01a1\u0323i trinh, chi\u0301nh hung, ph\xe2\u0301t t\xf4\u0309n i\u0301ch chi.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 l\u01a1\u0323i, n\xea\u0301u v\xf4\u0323i ti\xea\u0301n ngay (bo\u0309 \u0111\u01b0\u0301c c\u01b0\u01a1ng trung cu\u0309a mi\u0300nh), \u0111\xea\u0309 chi\xea\u0300u ba\u0323n thi\u0300 x\xe2\u0301u; \u0111\u01b0\u0300ng la\u0300m t\xf4\u0309n ha\u0323i \u0111\u01b0\u0301c cu\u0309a mi\u0300nh cu\u0303ng la\u0300 i\u0301ch cho ba\u0323n \u0111\xe2\u0301y.\n","\n\u516d\u4e09: \u4e09\u4eba\u884c\u5247\u640d\u4e00\u4eba, \u4e00\u4eba\u884c\u5247\u5f97\u5176\u53cb\uff0e\nL\u1ee5c tam: tam nh\xe2n ha\u0300nh t\u0103\u0301c t\xf4\u0309n nh\xe2\u0301t nh\xe2n,\nnh\xe2\u0301t nh\xe2n ha\u0300nh t\u0103\u0301c \u0111\u0103\u0301c ki\u0300 h\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, \xe2m: Ba ng\u01b0\u01a1\u0300i \u0111i thi\u0300 b\u01a1\u0301t m\xf4\u0323t ng\u01b0\u01a1\u0300i, m\xf4\u0323t ng\u01b0\u01a1\u0300i \u0111i thi\u0300 \u0111\u01b0\u01a1\u0323c th\xeam ba\u0323n.\n","\n\u516d\u56db: \u640d\u5176\u75be, \u4f7f\u9044, \u6709\u559c, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: t\xf4\u0309n ki\u0300 t\xe2\u0323t, s\u01b0\u0309 thuy\xean, h\u01b0\u0303u hi\u0309, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: la\u0300m b\u01a1\u0301t ca\u0301i t\xe2\u0323t (\xe2m nhu) cu\u0309a mi\u0300nh cho mau h\xea\u0301t, \u0111a\u0301ng m\u01b0\u0300ng, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94: \u6216\u76ca\u4e4b\u5341\u670b\u4e4b\u9f9c, \u5f17\u514b\u9055, \u5143\u5409\uff0e\nL\u1ee5c ngu\u0303: Ho\u0103\u0323c i\u0301ch chi th\xe2\u0323p b\u0103\u0300ng chi qui\u0301, ph\xe2\u0301t kh\u0103\u0301c vi, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: thi\u0300nh li\u0300nh co\u0301 ng\u01b0\u01a1\u0300i la\u0300m i\u0301ch cho mi\u0300nh, m\xf4\u0323t con ru\u0300a l\u01a1\u0301n \u0111a\u0301ng gia\u0301 m\u01b0\u01a1\u0300i \u201cb\u0103\u0300ng\u201d, kh\xf4ng t\u01b0\u0300 ch\xf4\u0301i \u0111\u01b0\u01a1\u0323c, r\xe2\u0301t t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u5f17\u640d\u76ca\u4e4b, \u65e0\u548e\uff0e\u8c9e\u5409\uff0e\u5229\u6709\u6538\u5f80, \u5f97\u81e3\u65e0\u5bb6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: ph\xe2\u0301t t\xf4\u0309n i\u0301ch chi, trinh ca\u0301t.\nL\u1ee3i h\u01b0\u0303u du va\u0303ng, \u0111\u0103\u0301c th\xe2\u0300n v\xf4 gia .\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: la\u0300m i\u0301ch cho ng\u01b0\u01a1\u0300i ma\u0300 ch\u0103\u0309ng t\xf4\u0309n gi\u0300 cu\u0309a mi\u0300nh, kh\xf4ng l\xf4\u0303i, chi\u0301nh \u0111a\u0301ng thi\u0300 t\xf4\u0301t, la\u0300m vi\xea\u0323c gi\u0300 cu\u0303ng v\xf4 l\u01a1\u0323i, vi\u0300 \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i qui phu, ch\u0103\u0309ng pha\u0309i chi nha\u0300 mi\u0300nh m\u01a1\u0301i la\u0300 nha\u0300 (y\u0301 no\u0301i \u0111\xe2u cu\u0303ng la\u0300 nha\u0300 mi\u0300nh, ai cu\u0303ng la\u0300 ng\u01b0\u01a1\u0300i nha\u0300 mi\u0300nh).\n")
if(s&&r.b===0&&r.c===1&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba H\u1ecfa Minh Di",c5,r.b,r.c,r.d,r.e,r.f,"QU\xc1 GIANG CHI\u1ebeT KI\u1ec0U",o,n,m,n,m,l,b8,"",3,0,4,b7,a4,r.r[58],"\n\u521d\u4e5d: \u660e\u5937, \u4e8e\u98db \u5782\u5176\u7ffc\uff0e\u541b\u5b50\u4e8e\u884c, \u4e09\u65e5\u4e0d\u98df, \u6709\u6538\u5f80, \u4e3b\u4eba\u6709\u8a00\uff0e\nS\u01a1\u0309 c\u01b0\u0309u: Minh di, vu phi thu\u0300y ki\u0300 d\u01b0\u0323c. Qu\xe2n t\u01b0\u0309 vu ha\u0300nh,\ntam nh\xe2\u0323t b\xe2\u0301t th\u01b0\u0323c, h\u01b0\u0303u du va\u0303ng, chu\u0309 nh\xe2n h\u01b0\u0303u ng\xf4n.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : \u01a1\u0309 th\u01a1\u0300i u a\u0301m (a\u0301nh sa\u0301ng bi\u0323 t\xf4\u0309n ha\u0323i), ha\u0300o na\u0300y nh\u01b0 con chim mu\xf4\u0301n bay ma\u0300 ca\u0301nh ru\u0303 xu\xf4\u0301ng. Ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 bi\xea\u0301t th\u01a1\u0300i c\u01a1 thi\u0300 bo\u0309 \u0111i ngay, du\u0300 (kh\xf4ng co\u0301 ti\xea\u0300n) pha\u0309i nhi\u0323n \u0111o\u0301i ba nga\u0300y, ma\u0300 \u0111i t\u01a1\u0301i \u0111\xe2u, g\u0103\u0323p chu\u0309 cu\u0303, cu\u0303ng bi\u0323 chu\u0309 cu\u0303 ch\xea tra\u0301ch.\n","\n\u516d\u4e8c: \u660e\u5937, \u5937\u4e8e\u5de6\u80a1, \u7528\u62ef\u99ac\u58ef, \u5409\uff0e\nL\u1ee5c nhi\u0323: Minh di, di vu ta\u0309 c\xf4\u0309, du\u0323ng ch\u01b0\u0309ng ma\u0303 tra\u0301ng, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: \u01a0\u0309 th\u01a1\u0300i a\u0301nh sa\u0301ng bi\u0323 t\xf4\u0309n ha\u0323i, ha\u0300o na\u0300y nh\u01b0 bi\u0323 \u0111au \u01a1\u0309 \u0111u\u0300i b\xean tra\u0301i, nh\u01b0ng cu\u0303ng mau kho\u0309i, se\u0303 nh\u01b0 con ng\u01b0\u0323a ma\u0323nh me\u0303 ti\xea\u0301n l\xean, t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u660e\u5937, \u4e8e\u5357\u72e9, \u5f97\u5176\u5927\u9996, \u4e0d\u53ef\u75be, \u8c9e\uff0e\nCu\u0309u tam: Minh di, vu nam thu\u0301, \u0111\u0103\u0301c ki\u0300 \u0111a\u0323i thu\u0309, b\xe2\u0301t kha\u0309 t\xe2\u0323t, trinh.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: \u01a1\u0309 th\u01a1\u0300i a\u0301nh sa\u0301ng bi\u0323 t\xf4\u0309n ha\u0323i, \u0111i tu\xe2\u0300n v\xea\u0300 ph\u01b0\u01a1ng Nam, b\u0103\u0301t \u0111\u01b0\u01a1\u0323c ke\u0309 \u0111\xe2\u0300u so\u0309, nh\u01b0ng \u0111\u01b0\u0300ng ha\u0300nh \u0111\xf4\u0323ng g\xe2\u0301p, pha\u0309i b\xea\u0300n chi\u0301.\n","\n\u516d\u56db: \u5165\u4e8e\u5de6\u8179, \u7372\u660e\u5937\u4e4b\u5fc3, \u4e8e\u51fa\u9580\u5ead\uff0e\nL\u1ee5c t\u01b0\u0301: Nh\xe2\u0323p vu ta\u0309 phu\u0301c, hoa\u0323ch minh di chi t\xe2m, vu xu\xe2\u0301t m\xf4n \u0111i\u0300nh.\nD\u1ecbch: Ha\u0300o 4, \xe2m: nh\u01b0 v\xf4 phi\u0301a b\xean tra\u0301i cu\u0309a bu\u0323ng (y\u0301 no\u0301i ch\xf4\u0303 u a\u0301m); t\xe2\u0301m lo\u0300ng \u01a1\u0309 th\u01a1\u0300i u a\u0301m (minh di) la\u0300 n\xean bo\u0309 nha\u0300 ma\u0300 ra \u0111i.\n","\n\u516d\u4e94: \u7b95\u5b50\u4e4b\u660e\u5937, \u5229\u8c9e\uff0e\nL\u1ee5c ngu\u0303: c\u01a1 t\u01b0\u0309 chi Minh di, l\u01a1\u0323i trinh.\nD\u1ecbch: Ha\u0300o 5, \xe2m: nh\u01b0 \xf4ng C\u01a1 T\u01b0\u0309 \u01a1\u0309 th\u01a1\u0300i u a\u0301m (Minh di), c\u01b0\u0301 b\xea\u0300n gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 l\u01a1\u0323i.\n","\n\u4e0a\u516d: \u4e0d\u660e\u6666, \u521d\u767b\u4e8e\u5929, \u5f8c\u5165\u4e8e\u5730\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: B\xe2\u0301t minh di, s\u01a1 \u0111\u0103ng vu thi\xean, h\xe2\u0323u nh\xe2\u0323p vu \u0111i\u0323a.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: kh\xf4ng co\u0300n la\u0300 a\u0301nh sa\u0301ng bi\u0323 t\xf4\u0309n th\u01b0\u01a1ng n\u01b0\u0303a, l\xean cao t\u01a1\u0301i tr\u01a1\u0300i ma\u0300 r\xf4\u0300i su\u0323p xu\xf4\u0301ng \u0111\xe2\u0301t.\n")
if(s&&r.b===0&&r.c===1&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean H\u1ecfa \u0110\u1ed3ng Nh\xe2n",c5,r.b,r.c,r.d,r.e,r.f,"TI\xcaN NH\xc2N CH\u1ec8 L\u1ed8",o,n,m,i,h,g,"","",0,0,3,b9,a8,r.r[1],"\n \u521d\u4e5d: \u540c\u4eba\u4e8e\u9580, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: \u0110\xf4\u0300ng nh\xe2n vu m\xf4n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: Ra kho\u0309i c\u01b0\u0309a \u0111\xea\u0309 cu\u0300ng chung v\u01a1\u0301i ng\u01b0\u01a1\u0300i thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e8c: \u540c\u4eba\u4e8e\u5b97, \u541d\uff0e\nL\u1ee5c nhi\u0323: \u0110\xf4\u0300ng nh\xe2n vu t\xf4n, l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 2, \xe2m: (chi\u0309) chung h\u01a1\u0323p v\u01a1\u0301i ng\u01b0\u01a1\u0300i trong ho\u0323, trong \u0111a\u0309ng pha\u0301i, x\xe2\u0301u h\xf4\u0309.\n","\n\u4e5d\u4e09: \u4f0f\u620e\u4e8e\u83bd, \u5347\u5176\u9ad8\u9675, \u4e09\u6b72\u4e0d\u8208\uff0e\nC\u1eedu tam: Phu\u0323c nhung vu ma\u0303ng,\nTh\u0103ng ki\u0300 cao l\u0103ng, tam tu\xea\u0301 b\xe2\u0301t h\u01b0ng.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: nu\u0301p qu\xe2n \u01a1\u0309 r\u01b0\u0300ng r\xe2\u0323m (ma\u0300 th\xe2\u0323p tho\u0300) l\xean go\u0300 cao, ba n\u0103m ch\u0103\u0309ng h\u01b0ng v\u01b0\u01a1\u0323ng \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d\u56db: \u4e58\u5176\u5889, \u5f17, \u514b\u653b, \u5409\uff0e\nC\u1eedu t\u01b0\u0301: th\u01b0\u0300a ky\u0300 dung, ph\xe2\u0301t, kh\u0103\u0301c c\xf4ng, ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: c\u01b0\u01a1\u0303i l\xean t\u01b0\u01a1\u0300ng \u0111\xe2\u0301t r\xf4\u0300i ma\u0300 kh\xf4ng da\u0301m \u0111a\u0301nh th\xea\u0301 la\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e94: \u540c\u4eba, \u5148\u865f\u54b7\u800c. \u5f8c\u7b11, \u5927\u5e2b\u514b\u76f8\u9047\uff0e\nC\u1eedu ngu\u0303: \u0110\xf4\u0300ng nh\xe2n, ti\xean ha\u0300o \u0111a\u0300o nhi\nH\xe2\u0323u ti\xea\u0301u, \u0111a\u0323i s\u01b0 kh\u0103\u0301c t\u01b0\u01a1ng ng\xf4\u0323.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Cu\u0300ng v\u01a1\u0301i ng\u01b0\u01a1\u0300i, tr\u01b0\u01a1\u0301c thi\u0300 k\xeau r\xeau, sau thi\u0300 c\u01b0\u01a1\u0300i, pha\u0309i du\u0300ng \u0111a\u0323i qu\xe2n \u0111a\u0301nh r\xf4\u0300i m\u01a1\u0301i g\u0103\u0323p nhau.\n","\n\u4e0a\u4e5d: \u540c\u4eba\u4e8e\u90ca, \u65e0\u6094\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: \u0110\xf4\u0300ng nh\xe2n vu giao, v\xf4 h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: cu\u0300ng v\u01a1\u0301i ng\u01b0\u01a1\u0300i \u01a1\u0309 ca\u0301nh \u0111\xf4\u0300ng ngoa\u0300i \u0111\xf4 tha\u0300nh, kh\xf4ng h\xf4\u0301i h\xe2\u0323n.\n")
if(s&&r.b===0&&r.c===1&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch H\u1ecfa C\xe1ch",c5,r.b,r.c,r.d,r.e,r.f,"H\u1ea0N MI\xcaU \u0110\u1eaeC V\u0168",o,n,m,m,l,q,b8,"",3,0,4,b7,"",r.r[8],"\n\u521d\u4e5d: \u978f\u7528\u9ec3\u725b\u4e4b\u9769\uff0e\nS\u01a1 c\u01b0\u0309u: cu\u0309ng du\u0323ng hoa\u0300ng ng\u01b0u chi ca\u0301ch.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: bo\u0301 ch\u0103\u0323t b\u0103\u0300ng da con bo\u0300 va\u0300ng.\n","\n\u516d\u4e8c: \u5df2\u65e5\u4e43\u9769\u4e4b, \u5f81\u5409, \u65e0\u548e\uff0e\nL\u1ee5c nhi\u0323: Di\u0303 nh\xe2\u0323t na\u0303i ca\u0301ch chi, chinh ca\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, \xe2m: chu\xe2\u0309n bi\u0323 l\xe2u nga\u0300y r\xf4\u0300i ca\u0309i ca\u0301ch, ti\xea\u0301n \u0111i thi\u0300 t\xf4\u0301t, kh\xf4ng l\xf4\u0303i.\n","\n\u4e5d\u4e09: \u5f81\u51f6, \u8c9e\u53b2, \u9769\u8a00\u4e09\u5c31, \u6709\u5b5a\uff0e\nC\u1eedu tam: chi\u0301nh hung, trinh l\xea\u0323, ca\u0301ch ng\xf4n tam t\u01b0\u0323u, h\u01b0\u0303u phu.\nD\u1ecbch: ha\u0309o, d\u01b0\u01a1ng: h\u0103ng ha\u0301i ti\xea\u0301n li\xea\u0300u thi\u0300 x\xe2\u0301u, b\xea\u0300n v\u01b0\u0303ng gi\u01b0\u0303 \u0111a\u0323o va\u0300 th\xe2\u0323n tro\u0323ng lo l\u0103\u0301ng, ti\u0301nh toa\u0301n s\u0103\u0301p \u0111\u0103\u0323t k\xea\u0301 hoa\u0323ch t\u01a1\u0301i 3 l\xe2\u0300n thi\u0300 k\xea\u0301t qua\u0309 m\u01a1\u0301i ch\u0103\u0301c ch\u0103\u0301n.\n","\n\u4e5d\u56db: \u6094\u4ea1, \u6709\u5b5a, \u6539\u547d, \u5409\uff0e\nC\u1eedu t\u01b0\u0301: H\xf4\u0301i vong, h\u01b0\u0303u phu, ca\u0309i m\xea\u0323nh, ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: H\xf4\u0301i h\xe2\u0323n ti\xeau h\xea\u0301t, co\u0301 lo\u0300ng chi\u0301 tha\u0300nh, tr\xean d\u01b0\u01a1\u0301i \u0111\xea\u0300u tin theo, \u0111\xf4\u0309i m\xea\u0323nh (ca\u0309i ca\u0301ch l\u01a1\u0301n) \u0111\u01b0\u01a1\u0323c, t\xf4\u0301t.\n","\n\u4e5d\u4e94: \u5927\u4eba, \u864e\u8b8a\uff0e\u672a\u5360\u6709\u5b5a\uff0e\nC\u1eedu ngu\u0303: \u0110a\u0323i nh\xe2n, h\xf4\u0309 bi\xea\u0301n; vi\u0323 chi\xeam h\u01b0\u0303u phu.\nD\u1ecbch: Ha\u0300o 5 d\u01b0\u01a1ng: B\xe2\u0323c \u0111a\u0323i nh\xe2n la\u0300m cho xa\u0303 h\xf4\u0323i thay \u0111\xf4\u0309i nh\u01b0 con h\xf4\u0309 thay l\xf4ng (m\u01b0\u01a1\u0301t, \u0111e\u0323p h\u01a1n) ch\u01b0a bo\u0301i cu\u0303ng \u0111a\u0303 tin nh\u01b0 v\xe2\u0323y r\xf4\u0300i.\n","\n\u4e0a\u516d: \u541b\u5b50\u8c79\u8b8a, \u5c0f\u4eba\u9769\u9762. \u5f81\u51f6, \u5c45\u8c9e, \u5409\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Qu\xe2n t\u01b0\u0309 ba\u0301o bi\xea\u0301n, ti\xea\u0309u nh\xe2n ca\u0301ch di\xea\u0323n. Chi\u0301nh hung, c\u01b0 trinh, ca\u0301t.\nD\u1ecbch: Ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 (th\u01b0\u0323c hi\xea\u0309u va\u0300 theo s\u01b0\u0323 ca\u0309i ca\u0301ch nh\u01b0) con ba\u0301o thay l\xf4ng; ke\u0309 ti\xea\u0309u nh\xe2n mi\xea\u0303n c\u01b0\u01a1\u0303ng theo ngoa\u0300i m\u0103\u0323t. C\xf4ng vi\xea\u0323c ca\u0309i ca\u0301ch \u0111\xea\u0301n \u0111\xe2y \u0111a\u0303 xong, n\xean ng\u01b0\u0300ng la\u0323i, ti\xea\u0301n n\u01b0\u0303a thi\u0300 x\xe2\u0301u, c\u01b0\u0301 gi\u01b0\u0303 v\u01b0\u0303ng chi\u0301nh \u0111a\u0323o thi\u0300 t\xf4\u0301t.\n")
if(s&&r.b===0&&r.c===1&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("B\xe1t Thu\u1ea7n Ly",c5,r.b,r.c,r.d,r.e,r.f,"THI\xcaN QUAN T\u1ee8 PH\xdaC",o,n,m,l,q,p,"","",0,0,6,b9,j,r.r[23],"\n\u521d\u4e5d: \u5c65\u932f\u7136, \u656c\u4e4b, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: Ly\u0301 tha\u0301c nhi\xean, ki\u0301nh chi, v\xf4 c\u01b0\u0309u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : D\xe2\u0303m b\xe2\u0323y ba\u0323; pha\u0309i th\xe2\u0323n tro\u0323ng thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e8c: \u9ec3\u96e2, \u5143\u5409\uff0e\nL\u1ee5c nhi\u0323: Hoa\u0300ng ly, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m : S\u0103\u0301c va\u0300ng phu\u0323 va\u0300o \u01a1\u0309 gi\u01b0\u0303a, r\xe2\u0301t t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u65e5\u6603\u4e4b\u96e2, \u4e0d\u9f13 \u7f36\u800c\u6b4c, \u5247\u5927\u800b\u4e4b\u55df, \u51f6\uff0e\nC\u1eedu tam: Nh\xe2\u0323t tr\u0103\u0301c chi Ly, b\xe2\u0301t c\xf4\u0309 ph\xe2\u0309u nhi ca, t\u0103\u0301c \u0111a\u0323i di\xea\u0323t chi ta, hung.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : m\u0103\u0323t tr\u01a1\u0300i x\xea\u0301 chi\xea\u0300u l\u0103\u0323n, (y\u0301 no\u0301i ng\u01b0\u01a1\u0300i gia\u0300, ti\u0301nh ti\u0300nh th\xe2\u0301t th\u01b0\u01a1\u0300ng, kh\xf4ng \u0111a\u0301ng vui ma\u0300 vui. Kh\xf4ng \u0111a\u0301ng bu\xf4\u0300n ma\u0300 bu\xf4\u0300n). Khi thi\u0300 go\u0303 ca\u0301i ph\xe2\u0303u (vo\u0300 b\u0103\u0300ng \u0111\xe2\u0301t, \u0111\u01b0\u0323ng r\u01b0\u01a1\u0323u ma\u0300 cu\u0303ng du\u0300ng la\u0300m nha\u0323c khi\u0301) ma\u0300 ha\u0301t, lu\u0301c la\u0323i than th\xe2n gia\u0300 nua; x\xe2\u0301u , (H\xf4\u0300i x\u01b0a khi ha\u0301t thi\u0300 go\u0303 nhi\u0323p b\u0103\u0300ng ca\u0301i ph\xe2\u0303u).\n","\n\u4e5d\u56db: \u7a81\u5982, \u5176\u4f86\u5982, \u711a\u5982, \u6b7b\u5982, \u68c4\u5982\uff0e\nC\u1eedu t\u01b0\u0301: \u0110\xf4\u0323t nh\u01b0, ki\u0300 lai nh\u01b0, ph\xe2\u0300n nh\u01b0, t\u01b0\u0309 nh\u01b0, khi\u0301 nh\u01b0.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: thi\u0300nh li\u0300nh cha\u0323y t\u01a1\u0301i, nh\u01b0 mu\xf4\u0301n \u0111\xf4\u0301t ng\u01b0\u01a1\u0300i ta v\xe2\u0323y, thi\u0300 se\u0303 ch\xea\u0301t, bi\u0323 mo\u0323i ng\u01b0\u01a1\u0300i bo\u0309.\n","\n\u516d\u4e94: \u51fa\u6d95\u6cb1\u82e5, \u621a\u55df\u82e5, \u5409\uff0e\nL\u1ee5c ngu\u0303: xu\xe2\u0301t th\xea\u0301 \u0111a\u0300 nh\u01b0\u01a1\u0323c, thi\u0301ch ta nh\u01b0\u01a1\u0323c, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: N\u01b0\u01a1\u0301c m\u0103\u0301t ro\u0300ng ro\u0300ng, nh\u01b0ng bi\xea\u0301t bu\xf4\u0300n lo than th\u01a1\u0309, n\xean t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u738b\u7528\u51fa\u5f81, \u6709\u5609; \u6298\u9996, \u7372\u532a\u5176\u919c, \u65e0\u548e\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: V\u01b0\u01a1ng du\u0323ng xu\xe2\u0301t chinh,\nH\u01b0\u0303u gia; chi\xea\u0301t thu\u0309, hoa\u0323ch phi\u0309 ki\u0300 xu\u0301, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: vua du\u0300ng (ng\u01b0\u01a1\u0300i co\u0301 ta\u0300i, t\u01b0\u0301c ha\u0300o na\u0300y) \u0111\xea\u0309 ra qu\xe2n chinh pha\u0323t, co\u0301 c\xf4ng t\xf4\u0301t \u0111e\u0323p, gi\xea\u0301t \u0111\xe2\u0300u \u0111a\u0309ng ma\u0300 b\u0103\u0301t s\xf4\u0301ng ke\u0309 x\xe2\u0301u \u0111i thi\u0300 th\xf4i, nh\u01b0 v\xe2\u0323y thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n")
if(s&&r.b===0&&r.c===1&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i H\u1ecfa Phong",c5,r.b,r.c,r.d,r.e,r.f,"C\u1ed4 K\xcdNH TR\xd9NG MINH",o,n,m,i,h,g,"","",0,0,5,b7,"",r.r[30],"\n\u521d\u4e5d: \u9047\u5176\u914d\u4e3b, \u96d6\u65ec, \u65e0\u548e, \u5f80\u6709\u5c1a\uff0e\nS\u01a1 c\u01b0\u0309u: Ng\xf4\u0323 ki\u0300 ph\xf4\u0301i chu\u0309, tuy tu\xe2\u0300n, v\xf4 c\u01b0\u0303u, va\u0303ng h\u01b0\u0303u th\u01b0\u01a1\u0323ng.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: G\u0103\u0323p \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i chu\u0309 h\u01a1\u0323p v\u01a1\u0301i mi\u0300nh, tuy ngang nhau nh\u01b0ng kh\xf4ng co\u0301 l\xf4\u0303i ti\xea\u0301n \u0111i thi\u0300 co\u0301 c\xf4ng nghi\xea\u0323p \u0111a\u0301ng khen.\n","\n\u516d\u4e8c: \u8c50\u5176\u8500, \u65e5\u4e2d\u898b\u6597\uff0e\u5f80, \u5f97\u7591\u75be, \u6709\u5b5a\u767c\u82e5, \u5409\uff0e\nL\u1ee5c nhi\u0323: phong ki\u0300 b\xf4\u0323, nh\xe2\u0323t trung ki\xea\u0301n \u0111\xe2\u0309u;\nVa\u0303ng, \u0111\u0103\u0301c nghi t\xe2\u0323t, h\u01b0\u0303u phu pha\u0301t nh\u01b0\u01a1\u0323c, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Bi\u0323 ma\u0300n che l\u01a1\u0301n, da\u0300y qua\u0301, nh\u01b0 ban nga\u0300y (m\u0103\u0323t tr\u01a1\u0300 bi\u0323 che l\xe2\u0301p) ma\u0300 th\xe2\u0301y sao B\u0103\u0301c \u0111\xe2\u0309u; ti\xea\u0301n \u0111i thi\u0300 bi\u0323 ng\u01a1\u0300 va\u0300 ghe\u0301t, c\u01b0\u0301 l\xe2\u0301y lo\u0300ng chi\u0301 tha\u0300nh ma\u0300 ca\u0309m hoa\u0301 \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i tr\xean thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u8c50\u5176\u6c9b, \u65e5\u4e2d\u898b\u6cac\uff0e\u6298\u5176\u53f3\u80b1, \u65e0\u548e\uff0e\nC\u1eedu tam: Phong ky\u0300 ba\u0301i, nh\xe2\u0323t trung ki\xea\u0301n mu\xf4\u0323i.\nChi\xea\u0301t ki\u0300 h\u01b0\u0303u qu\u0103ng, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3 d\u01b0\u01a1ng: bi\u0323 ma\u0300n che ki\u0301n mi\u0301t, ban nga\u0300y ma\u0300 th\xe2\u0301y sao nho\u0309 (mu\xf4\u0323i) g\xe2\u0309y ca\u0301nh tay pha\u0309i, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u56db: \u8c50\u5176\u8500, \u65e5\u4e2d\u898b\u6597, \u9047\u5176\u5937\u4e3b, \u5409\uff0e\nC\u1eedu t\u01b0\u0301: Phong ki b\xf4\u0323, nh\xe2\u0323t trung ki\xea\u0301n \u0111\xe2\u0309u, ng\xf4\u0323 ki\u0300 di chu\u0309, ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: Bi\u0323 ma\u0300n che l\u01a1\u0301n da\u0300y qua\u0301, nh\u01b0 ban nga\u0300y ma\u0300 th\xe2\u0301y sao B\u0103\u0301c \xd0\xe2\u0309u g\u0103\u0323p \u0111\u01b0\u01a1\u0323c ba\u0323n b\u0103\u0300ng vai v\xea\u0301, t\xf4\u0301t.\n","\n\u516d\u4e94: \u4f86\u7ae0, \u6709\u6176, \u8b7d, \u5409\uff0e\nL\u1ee5c ngu\u0303: Lai ch\u01b0\u01a1ng, h\u01b0\u0303u kha\u0301nh, d\u01b0\u0323, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: M\u01a1\u0300i nh\u01b0\u0303ng nh\xe2n ta\u0300i giu\u0301p mi\u0300nh thi\u0300 \u0111\u01b0\u01a1\u0323c phu\u0301c, co\u0301 ti\xea\u0301ng khen, t\xf4\u0301t.\n","\n\u4e0a\u516d: \u8c50\u5176\u5c4b, \u8500\u5176\u5bb6, \u95da\u5176\u6236\uff0e\u95c3\u5176\u65e0\u4eba,\u4e09\u6b72\u4e0d\u89bf, \u51f6\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Phong ki\u0300 \xf4\u0301c, b\xf4\u0323 ki\u0300 gia, khuy ki\u0300 h\xf4\u0323,\nHuy\u0301ch ki\u0300 v\xf4 nh\xe2n, tam tu\xea\u0301 b\xe2\u0301t \u0111i\u0323ch, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: C\xe2\u0301t no\u0301c nha\u0300 r\xe2\u0301t cao l\u01a1\u0301n ma\u0300 pho\u0300ng mi\u0300nh \u01a1\u0309 la\u0323i nho\u0309 he\u0323p, bi\u0323 b\u01b0ng bi\u0301t (t\u01b0\u0323 mi\u0300nh kh\xf4ng mu\xf4\u0301n ai lui t\u01a1\u0301i v\u01a1\u0301i mi\u0300nh), cho n\xean nhi\u0300n va\u0300o c\u01b0\u0309a, l\u0103\u0323ng tanh kh\xf4ng th\xe2\u0301y bo\u0301ng ng\u01b0\u01a1\u0300i, ba n\u0103m kh\xf4ng th\xe2\u0301y ai (ho\u0103\u0323c kh\xf4ng gia\u0301c ng\xf4\u0323) x\xe2\u0301u.\n")
if(s&&r.b===0&&r.c===1&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong H\u1ecfa Gia Nh\xe2n",c5,r.b,r.c,r.d,r.e,r.f,"C\u1ea2NH L\xdd QUAN HOA",o,n,m,q,p,o,b2,"",3,0,2,b3,"",r.r[37],"\n\u521d\u4e5d: \u9591\u6709\u5bb6, \u6094\u4ea1\uff0e\nS\u01a1 c\u01b0\u0309u: nha\u0300n h\u01b0\u0303u gia, h\xf4\u0301i vong.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: pho\u0300ng ng\u01b0\u0300a ngay t\u01b0\u0300 khi m\u01a1\u0301i co\u0301 nha\u0300 thi\u0300 kh\xf4ng h\xf4\u0301i h\xe2\u0323n gi\u0300 ca\u0309.\n","\n\u516d\u4e8c: \u65e0\u6538\u9042, \u5728\u4e2d\u994b, \u8c9e\u5409\uff0e\nL\u1ee5c nhi\u0323: v\xf4 du loa\u0323i, ta\u0323i trung qui\u0303, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: kh\xf4ng vi\xea\u0323c gi\u0300 ma\u0300 t\u01b0\u0323 chuy\xean l\xe2\u0301y tha\u0300nh c\xf4ng (n\u0103\u0301m h\xea\u0301t tra\u0301ch nhi\xea\u0323m), c\u01b0\u0301 \u01a1\u0309 trong nha\u0300 lo vi\xea\u0323c n\xe2\u0301u n\u01b0\u01a1\u0301ng, gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u5bb6\u4eba\u55c3\u55c3, \u6094\u53b2, \u5409\uff0e\u5a66\u5b50\u563b\u563b, \u7d42\u541d\uff0e\nC\u1eedu tam: Gia nh\xe2n ha\u0301c ha\u0301c, h\xf4\u0301i l\xea\u0323, ca\u0301t; phu\u0323 t\u01b0\u0309 hi hi, chung l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: ng\u01b0\u01a1\u0300i chu\u0309 nha\u0300 nghi\xeam kh\u0103\u0301c, tuy h\xf4\u0301i h\xe2\u0323n, co\u0301 nguy nh\u01b0ng la\u0323i t\xf4\u0301t; (n\xea\u0301u qua\u0301 khoan \u0111\xea\u0309 cho) d\xe2u con nhi\u0301 nha\u0309nh ch\u01a1i \u0111u\u0300a thi\u0300 la\u0323i h\xf4\u0301i ti\xea\u0301c.\n","\n\u516d\u56db: \u5bcc\u5bb6, \u5927\u5409\uff0e\nL\u1ee5c t\u01b0\u0301: phu\u0301 gia, \u0111a\u0323i ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, \xe2m: La\u0300m gia\u0300u thi\u0323nh cho nha\u0300, r\xe2\u0301t r\xf4\u0301t.\n","\n\u4e5d\u4e94: \u738b\u5047\u6709\u5bb6, \u52ff\u6064, \u5409\uff0e\nC\u1eedu ngu\u0303: V\u01b0\u01a1ng ca\u0301ch h\u01b0\u0303u gia, v\xe2\u0323t tu\xe2\u0301t, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5 d\u01b0\u01a1ng : vua (ho\u0103\u0323c gia chu\u0309) r\xe2\u0301t khe\u0301o v\xea\u0300 vi\xea\u0323c tri\u0323 gia (ca\u0301ch la\u0300 r\xe2\u0301t t\xf4\u0301t kh\xf4ng co\u0301 gi\u0300 pha\u0309i lo, t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u6709\u5b5a, \u5a01\u5982, \u7d42\u5409\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: H\u01b0\u0303u phu, uy nh\u01b0, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: (ng\u01b0\u01a1\u0300i tr\xean) co\u0301 lo\u0300ng chi\u0301 tha\u0300nh va\u0300 tha\u0301i \u0111\xf4\u0323 uy nghi\xeam (kh\xf4ng l\u01a1\u0300n) thi\u0300 cu\xf4\u0301i cu\u0300ng se\u0303 t\xf4\u0301t.\n")
if(s&&r.b===0&&r.c===1&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("Th\u1ee7y H\u1ecfa K\xfd T\u1ebf",c5,r.b,r.c,r.d,r.e,r.f,"KIM B\u1ea2NG \u0110\u1ec0 DANH",o,n,m,h,g,a7,b8,"",3,0,3,b7,"",r.r[44],"\n\u521d\u4e5d: \u66f3\u5176\u8f2a, \u6fe1\u5176\u5c3e, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: du\xea ki\u0300 lu\xe2n, nhu ki\u0300 vi\u0303, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: ke\u0301o l\xea\u0301t ba\u0301nh xe (ch\xe2\u0323m la\u0323i), la\u0300m \u01b0\u01a1\u0301t ca\u0301i \u0111u\xf4i thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e8c: \u5a66\u55aa\u5176\u8300, \u52ff\u9010, \u4e03\u65e5\u5f97\uff0e\nL\u1ee5c nhi\u0323: Phu\u0323 ta\u0301ng ky\u0300 ph\xe2\u0301t, v\xe2\u0323t tru\u0323c, th\xe2\u0301t nh\xe2\u0323t \u0111\u0103\u0301c.\nD\u1ecbch : Ha\u0300o 2, \xe2m: Nh\u01b0 ng\u01b0\u01a1\u0300i \u0111a\u0300n ba\u0300 \u0111a\u0301nh m\xe2\u0301t ca\u0301i ma\u0300n xe, \u0111\u01b0\u0300ng \u0111u\xf4\u0309i theo ma\u0300 l\xe2\u0301y la\u0323i c\u01b0\u0301 \u0111\u01a1\u0323i ba\u0309y nga\u0300y se\u0303 \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d\u4e09: \u9ad8\u5b97\u4f10\u9b3c\u65b9\u4e09\u5e74,\u514b\u4e4b\uff0e\u5c0f\u4eba\u52ff\u7528\uff0e\nC\u1eedu tam: Cao t\xf4n pha\u0323t qui\u0309 Ph\u01b0\u01a1ng tam ni\xean, kh\u0103\u0301c chi. Ti\xea\u0309u nh\xe2n v\xe2\u0323t du\u0323ng.\nD\u1ecbch : Ha\u0300o 3, d\u01b0\u01a1ng: Vua Cao T\xf4n \u0111a\u0301nh n\u01b0\u01a1\u0301c Qui\u0309 Ph\u01b0\u01a1ng, ba n\u0103m m\u01a1\u0301i \u0111\u01b0\u01a1\u0323c, \u0111\u01b0\u0300ng du\u0300ng ke\u0309 ti\xea\u0309u nh\xe2n.\n","\n\u516d\u56db: \u7e7b\u6709\u8863\u88bd, \u7d42\u65e5\u6212\uff0e\nL\u1ee5c t\u01b0\u0301: chu h\u01b0\u0303u y nh\u01b0, chung nh\xe2\u0323t gi\u01a1\u0301i.\nD\u1ecbch : Ha\u0300o 4, \xe2m: Thuy\xea\u0300n bi\u0323 n\u01b0\u01a1\u0301c va\u0300o, co\u0301 gie\u0309 \u0111\xea\u0309 bi\u0301t l\xf4\u0303, pha\u0309i r\u0103n s\u01a1\u0323 su\xf4\u0301t nga\u0300y.\n","\n\u4e5d\u4e94: \u6771\u9130\u6bba\u725b, \u4e0d\u5982\u897f\u9130\u4e4b\u79b4\u796d, \u5be6\u53d7\u5176\u798f\uff0e\nC\u1eedu ngu\u0303: \u0110\xf4ng l\xe2n sa\u0301t ng\u01b0u, b\xe2\u0301t nh\u01b0 t\xe2y l\xe2n chi th\u01b0\u01a1\u0323c t\xea\u0301, th\u01b0\u0323c thu\u0323 ki\u0300 phu\u0301c.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Ha\u0300ng xo\u0301m b\xean \u0111\xf4ng m\xf4\u0309 bo\u0300 (la\u0300m t\xea\u0301 l\xea\u0303 l\u01a1\u0301n) ma\u0300 th\u01b0\u0323c t\xea\u0301 kh\xf4ng h\u01b0\u01a1\u0309ng \u0111\u01b0\u01a1\u0323c phu\u0301c b\u0103\u0300ng ha\u0300ng xo\u0301m b\xean t\xe2y chi\u0309 t\xea\u0301 l\xea\u0303 s\u01a1 sa\u0300i.\n","\n\u4e0a\u516d: \u6fe1\u5176\u9996, \u53b2\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Nhu ki\u0300 thu\u0309, l\xea\u0323.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: \u01af\u01a1\u0301t ca\u0301i \u0111\xe2\u0300u, nguy.\n")
if(s&&r.b===0&&r.c===1&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n H\u1ecfa B\xed",c5,r.b,r.c,r.d,r.e,r.f,"H\u1ec8 KH\xcd DOANH M\xd4N",o,n,m,g,a7,a9,"Ph\u1ee5 Ng\u1ecd",b4,2,3,1,b5,d,r.r[51],c,b,a,a0,a1,a2)
if(s&&r.b===0&&r.c===0&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba L\xf4i Ph\u1ee5c",c5,r.b,r.c,r.d,r.e,r.f,"PHU TH\xca PH\u1ea2N M\u1ee4C",a7,a9,b0,n,m,l,b1,"",2,0,1,k,d,r.r[59],"\n\u521d\u4e5d: \u4e0d\u9060\u5fa9, \u65e0\u7947\u6094, \u5143\u5409\uff0e\nS\u01a1 c\u01b0\u0309u: B\xe2\u0301t vi\xea\u0303n phu\u0323c, v\xf4 ki\u0300 h\xf4\u0301i, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng. Tuy l\xe2\u0300m l\xf4\u0303i nh\u01b0ng th\u01a1\u0300i gian ch\u0103\u0309ng xa, tr\u01a1\u0309 la\u0323i t\xf4\u0301t la\u0300nh ngay, thi\u0300 kh\xf4ng \u0111\xea\u0301n n\xf4\u0303i \u0103n n\u0103n l\u01a1\u0301n; r\xe2\u0301t t\xf4\u0301t (ch\u01b0\u0303 Ki\u0300 \u01a1\u0309 \u0111\xe2y co\u0301 nghi\u0303a la\u0300 l\u01a1\u0301n).\n","\n\u516d\u4e8c: \u4f11\u5fa9, \u5409\uff0e\nL\u1ee5c nhi\u0323: H\u01b0u phu\u0323c, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Tr\u01a1\u0309 la\u0323i \u0111e\u0323p \u0111e\u0303 (h\u01b0\u0303u), t\xf4\u0301t.\n","\n\u516d\u4e09: \u983b\u5fa9, \u53b2, \u65e0\u548e\uff0e\nL\u1ee5c tam: T\xe2\u0300n phu\u0323c, l\xea\u0323, v\xf4 c\u01b0\u0309u.\nD\u1ecbch: ha\u0300o 3, \xe2m (M\u0103\u0301c l\xf4\u0303i nh\u01b0ng) s\u01b0\u0309a la\u0323i nhi\xea\u0300u l\xe2\u0300n, tuy \u0111a\u0301ng nguy, ma\u0300 k\xea\u0301t qua\u0309 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u56db: \u4e2d\u884c, \u7368\u5fa9\uff0e\nL\u1ee5c t\u01b0\u0301: Trung ha\u0300nh, \u0111\xf4\u0323c phu\u0323c.\nD\u1ecbch: Ha\u0300o 4, \xe2m: \u01a1\u0309 gi\u01b0\u0303a ca\u0301c ti\xea\u0309u nh\xe2n (ca\u0301c ha\u0300o \xe2m: 2,3 va\u0300 5,6 ) ma\u0300 m\xf4\u0323t mi\u0300nh tr\u01a1\u0309 la\u0323i theo qu\xe2n t\u01b0\u0309 (ha\u0300o 1), t\u01b0\u0301c theo \u0111a\u0323o.\n","\n\u516d\u4e94: \u6566\u5fa9, \u65e0\u6094\uff0e\nL\u1ee5c ngu\u0303: \u0110\xf4n phu\u0323c, v\xf4 h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Co\u0301 \u0111\u01b0\u0301c da\u0300y tr\u01a1\u0309 la\u0323i \u0111i\xea\u0300u thi\xea\u0323n, kh\xf4ng co\u0301 gi\u0300 h\xf4\u0301i h\xe2\u0323n.\n","\n\u4e0a\u516d: \u8ff7\u5fa9, \u51f6\uff0e\u6709\u707d\u771a\uff0e\u7528\u884c\u5e2b, \u7d42\u6709\u5927\u6557, \u4ee5\u5176\u570b\u541b\u51f6, \u81f3\u4e8e\u5341\u5e74, \u4e0d\u514b\u5f81\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: M\xea phu\u0323c, hung, h\u01b0\u0303u tai sa\u0309nh,\nDu\u0323ng ha\u0300nh s\u01b0, chung h\u01b0\u0303u \u0111a\u0323i ba\u0323i, di\u0303 ki\u0300 qu\xf4\u0301c qu\xe2n hung, chi\u0301 vu th\xe2\u0323p ni\xean, b\xe2\u0301t kh\u0103\u0301c chi\u0301nh.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: M\xea mu\xf4\u0323i, kh\xf4ng tr\u01a1\u0309 la\u0323i, se\u0303 bi\u0323 tai va\u0323 t\u01b0\u0300 ngoa\u0300i \u0111\u01b0a \u0111\xea\u0301n (tai) va\u0300 t\u01b0\u0323 mi\u0300nh g\xe2y n\xean (sa\u0309nh); \u0111a\u0303 v\xe2\u0323y la\u0323i c\xe2\u0323y vo\u0303 l\u01b0\u0323c ma\u0300 du\u0300ng qu\xe2n \u0111a\u0300n a\u0301p ng\u01b0\u01a1\u0300i, r\xf4\u0301t cu\xf4\u0323c se\u0303 \u0111a\u0323i ba\u0323i, la\u0300m cho qu\xf4\u0301c qu\xe2n cu\u0303ng bi\u0323 kh\xf4\u0301n na\u0323n (hung), t\u01a1\u0301i m\u01b0\u01a1\u0300i n\u0103m (t\u01a1\u0301i chung cu\u0323c) cu\u0303ng kh\xf4ng kha\u0301 \u0111\u01b0\u01a1\u0323c.\n")
if(s&&r.b===0&&r.c===0&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean L\xf4i V\xf4 V\u1ecdng",c5,r.b,r.c,r.d,r.e,r.f,"\u0110I\u1ec2U B\u1eca LAO LUNG",a7,a9,b0,i,h,g,"","",0,0,4,b3,j,r.r[2],"\n\u521d\u4e5d: \u65e0\u5984, \u5f80\u5409\uff0e\nS\u01a1 c\u01b0\u0309u: v\xf4 vo\u0323ng, va\u0303ng ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: kh\xf4ng co\u0300n b\xe2\u0323y, ma\u0300 ti\xea\u0301n \u0111i thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e8c: \u4e0d\u8015\u7a6b, \u4e0d\u83d1\u756c, \u5247\u5229\u6709\u6538\u5f80\uff0e\nL\u1ee5c nhi\u0323: B\xe2\u0301t canh hoa\u0323ch, b\xe2\u0301t tri d\u01b0, t\u0103\u0301c l\u01a1\u0323i h\u01b0\u0303u du va\u0303ng.\nD\u1ecbch: Khi ca\u0300y thi\u0300 kh\xf4ng nghi\u0303 t\u01a1\u0301i lu\u0301c g\u0103\u0323t, khi m\u01a1\u0301i khai pha\u0301 (tri) thi\u0300 kh\xf4ng nghi\u0303 \u0111\xea\u0301n ru\xf4\u0323ng \u0111a\u0303 thu\xf4\u0323c (d\u01b0\u0323), nh\u01b0 v\xe2\u0323y ma\u0300 ti\xea\u0301n t\u01a1\u0301i thi\u0300 co\u0301 l\u01a1\u0323i.\n","\n\u516d\u4e09: \u65e0\u5984\u4e4b\u707d, \u6216\u7e6b\u4e4b\u725b, \u884c\u4eba\u4e4b\u5f97, \u9091\u4eba\u4e4b\u707d\uff0e\nL\u1ee5c tam: v\xf4 vo\u0323ng chi tai, ho\u0103\u0323c h\xea\u0323 chi ng\u01b0u,\nHa\u0300nh nh\xe2n chi \u0111\u0103\u0301c, \xe2\u0301p nh\xe2n chi tai.\nD\u1ecbch: Ha\u0300o 3, \xe2m: kh\xf4ng co\u0300n b\xe2\u0323y ma\u0300 bi\u0323 tai va\u0323 t\u01b0\u0323 nhi\xean \u0111\xea\u0301n nh\u01b0 co\u0301 ke\u0309 c\xf4\u0323t con bo\u0300 \u01a1\u0309 b\xean \u0111\u01b0\u01a1\u0300ng (r\xf4\u0300i bo\u0309 \u0111i ch\xf4\u0303 kha\u0301c), m\xf4\u0323t ng\u01b0\u01a1\u0300i \u0111i qua (th\xe2\u0301y bo\u0300 kh\xf4ng co\u0301 ai coi), d\u0103\u0301t tr\xf4\u0323m \u0111i, \u0111\u01b0\u01a1\u0323c bo\u0300, ma\u0300 ng\u01b0\u01a1\u0300i trong \xe2\u0301p bi\u0323 nghi oan la\u0300 l\xe2\u0301y tr\xf4\u0323m bo\u0300, ma\u0300 m\u0103\u0301c ho\u0323a.\n","\n\u4e5d\u56db: \u53ef\u8c9e,\u65e0\u548e\uff0e\nC\u1eedu t\u01b0\u0301: kha\u0309 trinh, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: n\xean gi\u01b0\u0303 v\u01b0\u0303ng t\u01b0 ca\u0301ch thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i (ho\u0103\u0323c: co\u0301 th\xea\u0309 gi\u01b0\u0303 v\u01b0\u0303ng \u0111\u01b0\u01a1\u0323c t\u01b0 ca\u0301ch, cho n\xean kh\xf4ng co\u0301 l\xf4\u0303i).\n","\n\u4e5d\u4e94: \u65e0\u5984\u4e4b\u75be, \u52ff\u85e5, \u6709\u559c\uff0e\nC\u1eedu ngu\u0303: v\xf4 vo\u0323ng chi t\xe2\u0323t, v\xe2\u0323t d\u01b0\u01a1\u0323c, h\u01b0\u0303u hi\u0309.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Kh\xf4ng ca\u0300n b\xe2\u0323y ma\u0300 v\xf4 c\u01a1\u0301 bi\u0323 b\xea\u0323nh (g\u0103\u0323p tai ho\u0323a) thi\u0300 \u0111\u01b0\u0300ng u\xf4\u0301ng thu\xf4\u0301c, se\u0303 h\xea\u0301t b\xea\u0323nh.\n","\n\u4e0a\u4e5d: \u65e0\u5984, \u884c\u6709\u771a, \u65e0\u6538\u5229\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: V\xf4 vo\u0323ng, ha\u0300nh h\u01b0\u0303u sa\u0309nh, v\xf4 du l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng. Kh\xf4ng ca\u0300n b\xe2\u0323y, nh\u01b0ng \u0111i (ha\u0300nh \u0111\xf4\u0323ng) thi\u0300 bi\u0323 ho\u0323a, kh\xf4ng l\u01a1\u0323i gi\u0300.\n")
if(s&&r.b===0&&r.c===0&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch L\xf4i T\xf9y",c5,r.b,r.c,r.d,r.e,r.f,"B\u1ed8 B\u1ed8 \u0110\u0102NG CAO",a7,a9,b0,m,l,q,c0,"",4,0,3,a5,a8,r.r[9],"\n\u521d\u4e5d: \u5b98\u6709\u6e1d, \u8c9e\u5409, \u51fa\u9580\u4ea4\u6709\u529f\uff0e\nS\u01a1 c\u01b0\u0309u: Quan h\u01b0\u0303u du, trinh ca\u0301t, xu\xe2\u0301t m\xf4n giao h\u01b0\u0303u c\xf4ng.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: chu\u0309 tr\u01b0\u01a1ng thay \u0111\xf4\u0309i, h\xea\u0303 chi\u0301nh thi\u0300 t\xf4\u0301t, ra ngoa\u0300i giao thi\xea\u0323p thi\u0300 co\u0301 c\xf4ng.\n","\n\u516d\u4e8c: \u4fc2\u5c0f\u5b50, \u5931\u4e08\u592b\uff0e\nL\u1ee5c nhi\u0323: H\xea\u0323 ti\xea\u0309u t\u01b0\u0309, th\xe2\u0301t tr\u01b0\u01a1\u0323ng phu.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Ra\u0300ng bu\xf4\u0323c v\u01a1\u0301i ke\u0309 th\xe2\u0301p ke\u0301m (nguy\xean v\u0103n la\u0300 : con ni\u0301t) ma\u0300 m\xe2\u0301t ke\u0309 tr\u01b0\u01a1\u0323ng phu.\n","\n\u516d\u4e09: \u4fc2\u4e08\u592b, \u5931\u5c0f\u5b50; \u96a8\u6709\u6c42\u5f97, \u5229\u5c45\u8c9e\uff0e\nL\u1ee5c tam: H\xea\u0323 tr\u01b0\u01a1\u0323ng phu, th\xe2\u0301t ti\xea\u0309u t\u01b0\u0309;\nTu\u0300y h\u01b0\u0303u c\xe2\u0300u \u0111\u0103\u0301c, l\u01a1\u0323i c\u01b0 trinh.\nD\u1ecbch: Ha\u0300o 3, \xe2m: Ra\u0300ng bu\xf4\u0323c v\u01a1\u0301i tr\u01b0\u01a1\u0323ng phu, bo\u0309 ke\u0309 th\xe2\u0301p ke\u0301m; theo nh\u01b0 v\xe2\u0323y c\xe2\u0300u xin ca\u0301i gi\u0300 thi\u0300 \u0111\u01b0\u0323\u01a1c \u0111\xe2\u0301y, nh\u01b0ng pha\u0309i chi\u0301nh \u0111a\u0301ng m\u01a1\u0301i co\u0301 l\u01a1\u0323i.\n","\n\u4e5d\u56db: \u96a8\u6709\u7372, \u8c9e\u51f6\uff0e\u6709\u5b5a, \u5728\u9053, \u4ee5\u660e\u4f55\u548e\uff0e\nC\u1eedu t\u01b0\u0301: Tu\u0300y h\u01b0\u0303u hoa\u0323ch, trinh, hung.\nH\u01b0\u0303u phu, ta\u0323i \u0111a\u0323o, di\u0303 minh ha\u0300 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : Theo thi\u0300 thu hoa\u0323ch \u0111\u01b0\u01a1\u0323c l\u01a1\u0301n \u0111\xe2\u0301y, nh\u01b0ng du\u0300 le\u0303 v\xe2\u0303n ngay ma\u0300 cu\u0303ng co\u0301 th\xea\u0309 g\u0103\u0323p hung \u0111\u01b0\u01a1\u0323c. C\u01b0\u0301 gi\u01b0\u0303 lo\u0300ng chi\u0301 tha\u0300nh, theo \u0111a\u0323o ly\u0301, l\xe2\u0301y \u0111\u01b0\u0301c sa\u0301ng su\xf4\u0301t ma\u0300 \u01b0\u0301ng pho\u0301 thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e94: \u5b5a\u4e8e\u5609, \u5409\uff0e\nC\u1eedu ngu\u0303: phu vu gia, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng. Ti\u0301n tha\u0300nh v\u01a1\u0301i \u0111i\xea\u0300u thi\xea\u0323n thi\u0300 t\xf4\u0301t.\n","\n\u4e0a\u516d: \u62d8\u4fc2\u4e4b, \u4e43\u5f9e\u7dad\u4e4b\uff0e\u738b\u7528\u4ea8\u4e8e\u897f\u5c71\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: c\xe2u h\xea\u0323 chi, ma\u0303i to\u0300ng duy chi.\nV\u01b0\u01a1ng du\u0323ng hanh vu T\xe2y S\u01a1n.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m. Ra\u0300ng bu\xf4\u0323c l\xe2\u0301y, theo ma\u0300 th\u0103\u0301t ch\u0103\u0323t l\xe2\u0301y; Tha\u0301i V\u01b0\u01a1ng nha\u0300 Chu, \u0111\u01b0\u01a1\u0323c nh\xe2n t\xe2m nh\u01b0 v\xe2\u0323y m\u01a1\u0301i l\xe2\u0323p \u0111\u01b0\u01a1\u0323c nghi\xea\u0323p v\u01b0\u01a1ng hanh thi\u0323nh \u01a1\u0309 T\xe2y s\u01a1n (t\u01b0\u0301c Ky\u0300 s\u01a1n).\n")
if(s&&r.b===0&&r.c===0&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa L\xf4i Ph\u1ec7 H\u1ea1p",c5,r.b,r.c,r.d,r.e,r.f,"C\u01a0 NH\xc2N NG\u1ed8 TH\u1ef0C",a7,a9,b0,l,q,p,"","",0,0,5,b3,"",r.r[16],"\n\u521d\u4e5d: \u5c68\u6821\u6ec5\u8dbe, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: Li\u0301 gia\u0309o di\xea\u0323t chi\u0309, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : vi\u0301 nh\u01b0 ch\xe2n \u0111a\u0323p va\u0300o ca\u0301i cu\u0300m ma\u0300 \u0111\u01b0\u0301t ngo\u0301n ch\xe2n ca\u0301i, kh\xf4ng co\u0301 l\xf4\u0303i l\u01a1\u0301n.\n","\n\u516d\u4e8c: \u566c\u819a, \u6ec5\u9f3b, \u65e0\u548e\uff0e\nL\u1ee5c nhi\u0323: Ph\xea\u0323 phu, di\xea\u0323t ti\u0323, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, \xe2m: C\u0103\u0301n mi\xea\u0301ng thi\u0323t m\xea\u0300m, s\u01b0\u0301t ca\u0301i mu\u0303i, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e09: \u566c\u814a\u8089, \u9047\u6bd2, \u5c0f\u541d, \u65e0\u548e\uff0e\nL\u1ee5c tam: Ph\xea\u0323 ti\u0301ch nhu\u0323c, ng\xf4\u0323 \u0111\xf4\u0323c, ti\xea\u0309u l\xe2\u0323n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, \xe2m: C\u0103\u0301n pha\u0309i mi\xea\u0301ng thi\u0323t co\u0301 x\u01b0\u01a1ng la\u0323i ng\xf4\u0323 \u0111\xf4\u0323c, \u0111a\u0301ng \xe2n h\xe2\u0323n m\xf4\u0323t chu\u0301t, nh\u01b0ng kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u56db: \u566c \u4e7e\u80cf, \u5f97\u91d1\u77e2, \u5229\u8271\u8c9e, \u5409\uff0e\nC\u1eedu t\u01b0\u0301: ph\xea\u0323 can tri\u0309 (co\u0301 ng\u01b0\u01a1\u0300i \u0111o\u0323c la\u0300 ti\u0309)\n\u0110\u0103\u0301c kim thi\u0309, l\u01a1\u0323i gian trinh, ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : C\u0103\u0301n pha\u0309i th\u01b0\u0301 thi\u0323t li\xea\u0300n x\u01b0\u01a1ng ma\u0300 ph\u01a1i kh\xf4, \u0111\u01b0\u01a1\u0323c mu\u0303i t\xean \u0111\xf4\u0300ng, chi\u0323u kho\u0301 nho\u0323c ma\u0300 v\u01b0\u0303ng lo\u0300ng gi\u01b0\u0303 \u0111\u01b0\u01a1\u0300ng chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e94: \u566c\u4e7e\u8089, \u5f97\u9ec3\u91d1, \u8c9e\u53b2, \u65e0\u548e\uff0e\nL\u1ee5c ngu\u0303: ph\xea\u0323 can nhu\u0323c, \u0111\u0103\u0301c hoa\u0300ng kim, trinh, l\xea\u0323, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5, \xe2m: C\u0103\u0301n mi\xea\u0301ng thi\u0323t kh\xf4, \u0111\u01b0\u01a1\u0323c va\u0300ng (danh d\u01b0\u0323 qui\u0301 ba\u0301u); pha\u0309i gi\u01b0\u0303 v\u01b0\u0303ng \u0111a\u0323o, th\u01b0\u01a1\u0300ng lo s\u01a1\u0323, thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e0a\u4e5d: \u4f55\u6821\u6ec5\u8033, \u51f6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Ha\u0323 gia\u0309o di\xea\u0323t nhi\u0303, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng : c\xf4\u0309 tra va\u0300o g\xf4ng, bi\u0323 t\xf4\u0323i c\u0103\u0301t tai, x\xe2\u0301u.\n")
if(s&&r.b===0&&r.c===0&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("B\xe1t Thu\u1ea7n Ch\u1ea5n",c5,r.b,r.c,r.d,r.e,r.f,"KIM CHUNG D\u1ea0 TR\xc0NG",a7,a9,b0,i,h,g,"","",0,0,6,a5,j,r.r[31],"\n\u521d\u4e5d: \u9707\u4f86\u8669\u8669, \u5f8c\u7b11\u8a00\u555e\u555e, \u5409\uff0e\nS\u01a1 c\u01b0\u0309u: ch\xe2\u0301n lai hi\u0301ch hi\u0301ch, h\xe2\u0323u ti\xea\u0301u ng\xf4n a\u0301ch a\u0301ch, ca\u0301t.\nD\u1ecbch: Ha\u0300o na\u0300y \u01a1\u0309 \u0111\xe2\u0300u th\u01a1\u0300i s\xe2\u0301m \u0111\xf4\u0323ng. Ha\u0300o t\u01b0\u0300 y h\xea\u0323t Thoa\u0301n t\u01b0\u0300, chi\u0309 th\xeam hai ch\u01b0\u0303 \u201ch\xe2\u0323u\u201d (sau) va\u0300 \u201cca\u0301t\u201d t\xf4\u0301t.\n","\n\u516d\u4e8c: \u9707\u4f86, \u53b2\uff0e\u5104\u55aa\u8c9d, \u8e8b\u4e8e\u4e5d\u9675, \u52ff\u9010\u4e03\u65e5\u5f97\uff0e\nL\u1ee5c nhi\u0323: Ch\xe2\u0301n lai, l\xea\u0323; \u01b0\u0301c ta\u0301ng b\xf4\u0301i, t\xea vu c\u01b0\u0309u l\u0103ng, v\xe2\u0323t tru\u0323c, th\xe2\u0301t nh\xe2\u0323t \u0111\u0103\u0301c.\nD\u1ecbch: Ha\u0300o 2, \xe2m: S\xe2\u0301m n\xf4\u0309, co\u0301 c\u01a1 nguy, e m\xe2\u0301t cu\u0309a ch\u0103\u0309ng (s\u01a1\u0323 ha\u0303i) cha\u0323y l\xean chi\u0301n t\u01b0\u0300ng go\u0300 \u0111\xea\u0309 tra\u0301nh; du\u0300 m\xe2\u0301t cu\u0309a nh\u01b0\u0303ng \u0111\u01b0\u0300ng \u0111u\xf4\u0309i theo, ba\u0309y nga\u0300y se\u0303 \u0111\u01b0\u01a1\u0323c.\n","\n\u516d\u4e09: \u9707\u8607\u8607, \u9707\u884c\u65e0\u771a\uff0e\nL\u1ee5c tam: Ch\xe2\u0301n t\xf4 t\xf4, ch\xe2\u0301n ha\u0300nh v\xf4 sa\u0309nh.\nD\u1ecbch: S\xe2\u0301m \u0111\xf4\u0323ng ma\u0300 sinh tha\u0301c loa\u0323n; c\u01b0\u0301 tra\u0301nh \u0111i, bo\u0309 \u0111i\xea\u0300u b\xe2\u0301t chi\u0301nh thi\u0300 kh\xf4ng bi\u0323 hoa\u0323.\n","\n\u4e5d\u56db: \u9707, \u9042\u6ce5\uff0e\nC\u1eedu t\u01b0\u0301: ch\xe2\u0301n, toa\u0323i n\xea.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: s\xe2\u0301m \u0111\xf4\u0323ng, bi say m\xea chi\u0300m \u0111\u0103\u0301m.\n","\n\u516d\u4e94: \u9707\u5f80\u4f86, \u53b2\uff0e\u610f\u65e0\u55aa, \u6709\u4e8b\uff0e\nL\u1ee5c ngu\u0303: Ch\xe2\u0301n va\u0303ng lai, l\xea\u0323; \u01b0\u0301c v\xf4 ta\u0301ng, h\u01b0\u0303u s\u01b0\u0323.\nD\u1ecbch: Ha\u0300o 5, \xe2m: S\xe2\u0301m t\u01a1\u0301i hay lui cu\u0303ng \u0111\xea\u0300u th\xe2\u0301y nguy; c\u01b0\u0301 lo (\u01b0\u0301c) sao cho kho\u0309i m\xe2\u0301t \u0111\u01b0\u0301c trung (v\xf4 ta\u0301ng), thi\u0300 la\u0300m \u0111\u01b0\u01a1\u0323c c\xf4ng vi\xea\u0323c.\n","\n\u4e0a\u516d: \u9707\u7d22\u7d22, \u8996\u77cd\u77cd, \u5f81\u51f6\uff0e\u9707\u4e0d\u4e8e\u5176\u8eac, \u4e8e\u5176\u9130, \u65e0\u548e, \u5a5a\u5abe\u6709\u8a00\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Ch\xe2\u0301n ta\u0301c ta\u0301c, thi\u0323 qu\u0103\u0301c qu\u0103\u0301c, chinh hung.\nCh\xe2\u0301n b\xe2\u0301t vu ki\u0300 cung, vu ki\u0300 l\xe2n, v\xf4 c\u01b0\u0303u, h\xf4n c\xe2\u0301u h\u01b0\u0303u ng\xf4n.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng: S\xe2\u0301m \u0111\xf4\u0323ng ma\u0300 kinh hoa\u0309ng, m\u0103\u0301t nh\u01a1\u0301n nha\u0301c, n\xea\u0301u \u0111i t\u01a1\u0301i (ha\u0300nh \u0111\xf4\u0323ng) thi\u0300 x\xe2\u0301u. N\xea\u0301u \u0111\xea\u0300 pho\u0300ng tr\u01b0\u01a1\u0301c t\u01b0\u0300 khi s\u01b0\u0323 ch\xe2\u0301n \u0111\xf4\u0323ng ch\u01b0a t\u01a1\u0301i ba\u0309n th\xe2n mi\u0300nh, m\u01a1\u0301i t\u01a1\u0301i ha\u0300ng xo\u0301m, thi\u0300 kh\xf4ng l\xe2\u0300m l\xf4\u0303i, m\u0103\u0323c d\xe2\u0300u ba\u0300 con co\u0301 ke\u0309 ch\xea c\u01b0\u01a1\u0300i mi\u0300nh.\n")
if(s&&r.b===0&&r.c===0&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong L\xf4i \xcdch",c5,r.b,r.c,r.d,r.e,r.f,"KH\xd4 M\u1ed8C KHAI HOA",a7,a9,b0,q,p,o,b2,"",3,0,3,b3,"",r.r[38],"\n\u521d\u4e5d: \u5229\u7528\u70ba\u5927\u4f5c, \u5143\u5409, \u65e0\u548e\uff0e\nS\u01a1 c\u01b0\u0309u: L\u01a1\u0323i du\u0323ng vi \u0111a\u0323i ta\u0301c, nguy\xean ca\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng: L\u01a1\u0323i du\u0323ng (s\u01b0\u0323 giu\u0301p \u0111\u01a1\u0303 cu\u0309a ng\u01b0\u01a1\u0300i) ma\u0300 la\u0300m vi\xea\u0323c l\u01a1\u0301n; nh\u01b0ng pha\u0309i khe\u0301o ti\u0301nh toa\u0301n, ha\u0300nh \u0111\xf4\u0323ng cho \u0111u\u0301ng, hoa\u0300n thi\xea\u0323n (nguy\xean ca\u0301t) thi\u0300 m\u01a1\u0301i kh\xf4ng co\u0301 l\xf4\u0303i. S\u01a1\u0309 di\u0303 khuy\xean nh\u01b0 v\xe2\u0323y vi\u0300 ha\u0300o na\u0300y \u01a1\u0309 \u0111i\u0323a vi\u0323 th\xe2\u0301p, kh\xf4ng n\xean la\u0303nh vi\xea\u0323c n\u0103\u0323ng n\xea\u0300 qua\u0301 (ha\u0323 b\xe2\u0301t h\xe2\u0323u s\u01b0\u0323 da\u0303, l\u01a1\u0300i Ti\xea\u0309u T\u01b0\u01a1\u0323ng truy\xea\u0323n).\n","\n\u516d\u4e8c: \u6216\u76ca\u4e4b\u5341\u670b\u4e4b\u9f9c \u5f17\u514b\u9055, \u6c38\u8c9e\u5409\uff0e\u738b\u7528\u4eab\u4e8e\u5e1d, \u5409\uff0e\nL\u1ee5c nhi\u0323: Ho\u0103\u0323c i\u0301ch chi th\xe2\u0323p b\u0103\u0300ng chi qui, ph\xe2\u0301t kh\u0103\u0301c vi, vi\u0303nh trinh ca\u0301t. V\u01b0\u01a1ng du\u0323ng h\u01b0\u01a1\u0309ng vu \u0111\xea\u0301, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Thi\u0300nh li\u0300nh co\u0301 ng\u01b0\u01a1\u0300i giu\u0301p cho mi\u0300nh m\xf4\u0323t con ru\u0300a l\u01a1\u0301n \u0111a\u0301ng gia\u0301 m\u01b0\u01a1\u0300i \u201cb\u0103\u0300ng\u201d, kh\xf4ng t\u01b0\u0300 ch\xf4\u0301i \u0111\u01b0\u01a1\u0323c, r\xe2\u0301t t\xf4\u0301t. N\xea\u0301u la\u0300 vua du\u0300ng \u0111\u01b0\u0301c \u0111\xea\u0309 t\xea\u0301 Th\u01b0\u01a1\u0323ng \xd0\xea\u0301, Th\u01b0\u01a1\u0323ng \u0110\xea\u0301 cu\u0303ng h\u01b0\u01a1\u0309ng, ma\u0300 \u0111\u01b0\u01a1\u0323c phu\u0301c, t\xf4\u0301t.\n","\n\u516d\u4e09: \u76ca\u4e4b\u7528\u51f6\u4e8b, \u65e0\u548e\uff0e\u6709\u5b5a\u4e2d\u884c, \u544a\u516c\u7528\u572d\uff0e\nL\u1ee5c tam: I\u0301ch chi du\u0323ng hung s\u01b0\u0323, v\xf4 c\u01b0\u0303u.\nH\u01b0\u0303u phu trung ha\u0300nh, ca\u0301o c\xf4ng du\u0323ng khu\xea.\nD\u1ecbch: Ha\u0300o 3, \xe2m: giu\u0301p i\u0301ch cho b\u0103\u0300ng ca\u0301ch b\u0103\u0301t chi\u0323u hoa\u0323n na\u0323n (hay tr\u01b0\u0300ng pha\u0323t) thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i. N\xea\u0301u ch\xe2n tha\u0300nh s\u01b0\u0309a l\xf4\u0303i, gi\u01b0\u0303 \u0111a\u0323o trung (vi\u0301 v\u01a1\u0301i ngo\u0323c khu\xea) thi\u0300 \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i tr\xean (vi\u0301 v\u01a1\u0301i vi\u0323 c\xf4ng) ch\xe2\u0301p nh\xe2\u0323n.\n","\n\u56db: \u4e2d\u884c, \u544a\u516c\u5f9e\uff0e\u5229\u7528\u70ba\u4f9d\u9077\u570b\uff0e\nL\u1ee5c t\u01b0\u0301: Trung ha\u0300nh, ca\u0301o c\xf4ng to\u0300ng; l\u01a1\u0323i du\u0323ng vi y thi\xean qu\xf4\u0301c.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Ra\u0301n theo \u0111a\u0323o trung ma\u0300 th\u01b0a v\u01a1\u0301i b\xe2\u0323c \u201cc\xf4ng\u201d thi\u0300 b\xe2\u0323c \u201cc\xf4ng\u201d se\u0303 theo; l\u01a1\u0323i du\u0323ng \u0111a\u0323o trung \u0111o\u0301 la\u0300m ch\xf4\u0303 t\u01b0\u0323a thi\u0300 du\u0300 vi\xea\u0323c l\u01a1\u0301n nh\u01b0 d\u01a1\u0300i \u0111\xf4 cu\u0303ng la\u0300m n\xf4\u0303i.\n","\n\u4e5d\u4e94: \u6709\u5b5a, \u60e0\u5fc3, \u52ff\u5468, \u5143\u5409\uff0e\u6709\u5b5a, \u60e0\u6211\u5fb7\uff0e\nC\u1eedu ngu\u0303: H\u01b0\u0303u phu, hu\xea t\xe2m, v\xe2\u0323t v\xe2\u0301n, nguy\xean ca\u0301t.\nH\u01b0\u0303u phu, hu\xea\u0323 nga\u0303 \u0111\u01b0\u0301c.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: co\u0301 lo\u0300ng chi\u0301 tha\u0300nh la\u0300m \xe2n \u0111\u01b0\u0301c, thi\u0300 ch\u0103\u0309ng c\xe2\u0300n ho\u0309i, cu\u0303ng bi\xea\u0301t la\u0300 r\xe2\u0301t t\xf4\u0301t r\xf4\u0300i. Thi\xean ha\u0323 ai cu\u0303ng tin va\u0300o \u0111\u01b0\u0301c ban \xe2n hu\xea\u0323 cu\u0309a 5.\n","\n\u4e0a\u4e5d: \u83ab\u76ca\u4e4b\u6216\u64ca\u4e4b\uff0e\u7acb\u5fc3\u52ff\u6046, \u51f6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Ma\u0323c i\u0301ch chi ho\u0103\u0323c ki\u0301ch chi. L\xe2\u0323p t\xe2m v\xe2\u0323t h\u0103\u0300ng, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: Kh\xf4ng ai la\u0300m i\u0301ch cho mi\u0300nh ma\u0300 co\u0301 ke\u0309 \u0111a\u0309 ki\u0301ch mi\u0300nh n\u01b0\u0303a, la\u0300 vi\u0300 kh\xf4ng gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c h\u0103\u0300ng t\xe2m (lo\u0300ng lu\xf4n lu\xf4n t\xf4\u0301t), x\xe2\u0301u.\n")
if(s&&r.b===0&&r.c===0&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("Th\u1ee7y L\xf4i Tru\xe2n",c5,r.b,r.c,r.d,r.e,r.f,"LO\u1ea0N TI V\xd4 \u0110\u1ea6U",a7,a9,b0,h,g,a7,b8,"",3,0,2,b7,"",r.r[45],"\n\u521d \u4e5d: \u78d0 \u6853, \u5229 \u5c45 \u8c9e, \u5229 \u5efa \u4faf \uff0e\nS\u01a1 c\u01b0\u0309u: Ba\u0300n hoa\u0300n, l\u01a1\u0323i c\u01b0 trinh, l\u01a1\u0323i ki\xea\u0301n h\xe2\u0300u.\nD\u1ecbch: Ha\u0300o 1, d\u01b0\u01a1ng : co\u0300n du\u0300ng d\u0103\u0300ng, gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c \u0111i\xea\u0300u chi\u0301nh thi\u0300 l\u01a1\u0323i, \u0111\u01b0\u01a1\u0323c \u0111\u0103\u0323t l\xean t\u01b0\u01a1\u0301c h\xe2\u0300u (nghi\u0303a la\u0300 \u0111\u01b0\u01a1\u0323c giao cho vi\xea\u0323c giu\u0301p \u0111\u01a1\u0300i lu\u0301c gian tru\xe2n) thi\u0300 l\u01a1\u0323i.\n","\n\u516d \u4e8c: \u5c6f \u5982 \u9085 \u5982, \u4e58 \u99ac \u73ed \u5982, \u532a \u5bc7 \u5a5a \u5abe \uff0e \u5973 \u5b50 \u8c9e \u4e0d \u5b57, \u5341 \u5e74 \u4e43 \u5b57 \uff0e\nL\u1ee5c nhi\u0323: Tru\xe2n nh\u01b0, chuy\xean nh\u01b0, th\u01b0\u0300a ma\u0303 ban nh\u01b0. Phi\u0309 kh\xe2\u0301u h\xf4n c\xe2\u0301u, n\u01b0\u0303 t\u01b0\u0309 trinh b\xe2\u0301t t\u01b0\u0323, th\xe2\u0323p ni\xean na\u0303i t\u01b0\u0323.\nD\u1ecbch: ha\u0300o 2, \xe2m : Kh\xf4\u0301n \u0111\xf4\u0301n kho\u0301 kh\u0103n nh\u01b0 ng\u01b0\u01a1\u0300i c\u01b0\u01a1\u0303i ng\u01b0\u0323a co\u0300n du\u0300ng d\u0103\u0300ng l\xe2\u0303n qu\xe2\u0309n (Nh\u01b0ng ha\u0300o 1 kia) kh\xf4ng pha\u0309i la\u0300 ke\u0309 c\u01b0\u01a1\u0301p, chi\u0309 la\u0300 mu\xf4\u0301n c\xe2\u0300u h\xf4n v\u01a1\u0301i mi\u0300nh th\xf4i. Mi\u0300nh c\u01b0\u0301 gi\u01b0\u0303 v\u01b0\u0303ng chi\u0301, \u0111\u01b0\u0300ng chi\u0323u, m\u01b0\u01a1\u0300i n\u0103m n\u01b0\u0303a se\u0303 k\xea\u0301t h\xf4n (v\u01a1\u0301i ha\u0300o 5).\n","\n\u516d \u4e09: \u5373 \u9e7f, \u65e0 \u865e, \u60df \u5165 \u4e8e \u6797 \u4e2d\uff0e \u541b \u5b50 \u5e7e, \u4e0d \u5982 \u820d, \u5f80 \u541d \uff0e\nL\u1ee5c tam: T\u01b0\u0301c l\xf4\u0323c, v\xf4 ngu, duy nh\xe2\u0323p vu l\xe2m trung. Qu\xe2n t\u01b0\u0309 c\u01a1, b\xe2\u0301t nh\u01b0 xa\u0309, va\u0303ng l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 3 \xe2m: \u0111u\xf4\u0309i h\u01b0\u01a1u ma\u0300 kh\xf4ng co\u0301 th\u01a1\u0323 s\u0103n giu\u0301p s\u01b0\u0301c thi\u0300 chi\u0309 v\xf4 s\xe2u trong r\u01b0\u0300ng th\xf4i (kh\xf4ng b\u0103\u0301t \u0111\u01b0\u01a1\u0323c). Ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 hi\xea\u0309u c\u01a1 s\u01b0\u0323 \xe2\u0301y thi\u0300 bo\u0309 \u0111i co\u0300n h\u01a1n, c\u01b0\u0301 ti\u0301\xea\u0301p tu\u0323c ti\xea\u0301n n\u01b0\u0303a thi\u0300 se\u0303 h\xf4\u0301i h\xe2\u0323n.\n","\n\u516d \u56db: \u4e58 \u99ac \u73ed \u5982 \uff0e \u6c42 \u5a5a \u5abe, \u5f80 \u5409, \u65e0 \u4e0d \u5229 \uff0e\nL\u1ee5c t\u01b0\u0301: Th\u01b0\u0300a ma\u0303 ban nh\u01b0. C\xe2\u0300u h\xf4n c\xe2\u0301u, va\u0303ng ca\u0301t, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 4, \xe2m: c\u01b0\u01a1\u0303i ng\u01b0\u0323a ma\u0300 du\u0300ng d\u0103\u0300ng. C\xe2\u0300u ba\u0323n tr\u0103m n\u0103m (hay \u0111\xf4\u0300ng t\xe2m) \u01a1\u0309 d\u01b0\u01a1\u0301i (\u01a1\u0309 xa) thi\u0300 kh\xf4ng gi\u0300 la\u0300 kh\xf4ng t\xf4\u0301t.\n","\n\u4e5d \u4e94: \u5c6f \u5176 \u818f; \u5c0f \u8c9e \u5409, \u5927 \u8c9e \u51f6 \uff0e\nC\u1eedu ngu\u0303: Tru\xe2n ki\u0300 cao; ti\xea\u0309u trinh ca\u0301t, \u0111a\u0323i trinh hung\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: \xc2n tra\u0323ch kh\xf4ng ban b\xf4\u0301 \u0111\u01b0\u01a1\u0323c (nguy\xean v\u0103n: d\xe2\u0300u m\u01a1\u0303 (cao) kh\xf4ng tr\u01a1n (tru\xe2n), chi\u0309nh \u0111\xf4\u0301n vi\xea\u0323c nho\u0309 thi\u0300 t\xf4\u0301t, vi\xea\u0323c l\u01a1\u0301n thi\u0300 x\xe2\u0301u.\n","\n\u4e0a\u516d: \u4e58 \u99ac \u73ed \u5982, \u6ce3 \u8840 \u6f23 \u5982 \uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Th\u01b0\u0300a ma\u0303 ban nh\u01b0, kh\xe2\u0301p huy\xea\u0301t li\xean nh\u01b0.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng \xe2m. C\u01b0\u01a1\u0303i ng\u01b0\u0323a ma\u0300 du\u0300ng d\u0103\u0300ng, kho\u0301c t\u01a1\u0301i ma\u0301u m\u0103\u0301t cha\u0309y \u0111\xe2\u0300m \u0111i\u0300a.\n")
if(s&&r.b===0&&r.c===0&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n L\xf4i Di",c5,r.b,r.c,r.d,r.e,r.f,"V\u1eca TH\u1ee6Y PH\u1eceNG HI\u1ec0N",a7,a9,b0,g,a7,a9,b2,"T\u1eed T\u1ecb",3,5,4,b3,a4,r.r[52],"\n\u521d\u4e5d: \u820d\u723e\u9748\u9f9c, \u89c0\u6211\u6735\u9824, \u51f6\uff0e\nS\u01a1 c\u01b0\u0309u: Xa\u0303 nhi\u0309 linh qui, quan nga\u0303 \u0111o\u0301a di, hung.\nD\u1ecbch: ha\u0300o 1, d\u01b0\u01a1ng: chu\u0301 bo\u0309 con ru\u0300a thi\xeang (t\u01b0\u01a1\u0323ng tr\u01b0ng ph\xe2\u0300n tinh th\xe2\u0300n qui\u0301 ba\u0301u) cu\u0309a chu\u0301 \u0111i ma\u0300 c\u01b0\u0301 ngo\u0301 ta, t\u01a1\u0301i x\xea\u0323 me\u0301p xu\xf4\u0301ng, x\xe2\u0301u.\n","\n\u516d\u4e8c: \u985b\u9824, \u62c2\u7d93, \u4e8e\u4e18 \u9824, \u5f81\u51f6\uff0e\nL\u1ee5c nhi\u0323: \u0111i\xean di, ph\xe2\u0301t kinh, vu kh\xe2u di, chinh hung .\nD\u1ecbch: Ha\u0300o 2, \xe2m: \u0110a\u0309o l\xf4\u0323n ca\u0301ch nu\xf4i mi\u0300nh, tra\u0301i v\u01a1\u0301i le\u0303 th\u01b0\u01a1\u0300ng, c\xe2\u0300u s\u01b0\u0323 nu\xf4i d\u01b0\u01a1\u0303ng \u01a1\u0309 go\u0300 cao, ti\xea\u0301n l\xean thi\u0300 x\xe2\u0301u.\n","\n\u516d\u4e09: \u62c2\u9824, \u8c9e\u51f6\uff0e\u5341\u5e74\u52ff\u7528\u65e0\u6538\u5229\uff0e\nL\u1ee5c tam: Ph\xe2\u0323t di, trinh hung. Th\xe2\u0323p ni\xean v\xe2\u0323t du\u0323ng v\xf4 du l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 3 \xe2m: Ca\u0301ch nu\xf4i tra\u0301i h\u0103\u0309n v\u01a1\u0301i chi\u0301nh \u0111a\u0323o, x\xe2\u0301u. M\u01b0\u01a1\u0300i n\u0103m (co\u0301 nghi\u0303a la\u0300 t\u01a1\u0301i cu\u0300ng) cu\u0303ng kh\xf4ng t\xf4\u0301t \u0111\u01b0\u01a1\u0323c kh\xf4ng la\u0300m n\xean gi\u0300.\n","\n\u516d\u56db: \u985b\u9824, \u5409\uff0e\u864e\u8996\u7708\u7708, \u5176\u6b32\u9010\u9010, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: \u0111i\xean di, ca\u0301t. H\xf4\u0309 thi\u0323 \u0111am \u0111am, ki\u0300 du\u0323c tru\u0323c tru\u0323c, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: \u0110a\u0309o l\xf4\u0323n ca\u0301ch nu\xf4i ma\u0300 t\xf4\u0301t. M\u0103\u0301t h\xf4\u0309 nhi\u0300n \u0111\u0103m \u0111\u0103m, lo\u0300ng ham mu\xf4\u0301n day d\u01b0\u0301t kh\xf4ng ng\u01a1\u0301t, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94: \u62c2\u7d93, \u5c45\u8c9e, \u5409\uff0e\u4e0d\u53ef\u6d89\u5927\u5ddd\uff0e\nL\u1ee5c ngu\u0303: Ph\xe2\u0323t kinh, c\u01b0 trinh, ca\u0301t. B\xe2\u0301t kha\u0309 thi\xea\u0323p \u0111a\u0323i xuy\xean.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Tra\u0301i le\u0303 th\u01b0\u01a1\u0300ng, b\xea\u0300n chi\u0301 gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4\u0301t. Kh\xf4ng th\xea\u0309 v\u01b0\u01a1\u0323t s\xf4ng l\u01a1\u0301n \u0111\u01b0\u01a1\u0323c.\n","\n\u4e0a\u4e5d: \u7531\u9824, \u53b2\u5409, \u5229\u6d89\u5927\u5ddd\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: do di, l\xea\u0323 ca\u0301t. L\u01a1\u0323i thi\xea\u0323p \u0111a\u0323i xuy\xean.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng. Thi\xean ha\u0323 nh\u01a1\u0300 mi\u0300nh ma\u0300 \u0111\u01b0\u01a1\u0323c nu\xf4i, tra\u0301ch nhi\xea\u0323m mi\u0300nh l\u01a1\u0301n nh\u01b0 v\xe2\u0323y, mi\u0300nh pha\u0309i th\u01b0\u01a1\u0300ng lo l\u0103\u0301ng, s\u01a1\u0323 ha\u0303i thi\u0300 \u0111\u01b0\u01a1\u0323c t\xf4\u0301t. Qua s\xf4ng l\u01a1\u0301n \u0111\u01b0\u01a1\u0323c.\n")
if(c6&&r.b===1&&r.c===1&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba Phong Th\u0103ng",c5,r.b,r.c,r.d,r.e,r.f,"CH\u1ec8 NH\u1eacT CAO TH\u0102NG",n,m,l,n,m,l,c1,c0,2,4,4,a5,"",r.r[60],"\n\u521d\u516d: \u5141\u5347, \u5927\u5409\nS\u01a1 lu\u0323c: Doa\u0303n th\u0103ng, \u0111a\u0323i ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, \xe2m : co\u0301 lo\u0300ng tin ma\u0300 ti\xea\u0301n l\xean, r\xe2\u0301t t\xf4\u0301t.\n","\n\u4e5d\u4e8c: \u5b5a, \u4e43\u5229\u7528\u79b4, \u65e0\u548e\uff0e\nC\u1eedu nhi\u0323: Phu, na\u0303i l\u01a1\u0323i du\u0323ng th\u01b0\u01a1\u0323c, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: tin nhau co\u0301 lo\u0300ng chi\u0301 tha\u0300nh thi\u0300 du\u0300ng l\xea\u0303 nho\u0309 cu\u0303ng \u0111\u01b0\u01a1\u0323c, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e09: \u5347, \u865b\u9091\uff0e\nC\u1eedu tam: Th\u0103ng, nh\u01b0 \xe2\u0301p.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: l\xean d\xea\u0303 da\u0300ng nh\u01b0 va\u0300o ca\u0301i \xe2\u0301p kh\xf4ng ng\u01b0\u01a1\u0300i .\n","\n\u516d\u56db: \u738b\u7528\u4ea8\u4e8e\u5c90\u5c71, \u5409, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: V\u01b0\u01a1ng du\u0323ng hanh vu Ki\u0300 s\u01a1n, ca\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: vua V\u0103n V\u01b0\u01a1ng du\u0300ng \u0111a\u0323o ma\u0300 hanh thi\u0323nh \u01a1\u0309 nu\u0301i Ki\u0300 s\u01a1n, t\xf4\u0301t, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e94, \u8c9e\u5409, \u5347\u968e\uff0e\nL\u1ee5c ngu\u0303: Trinh ca\u0301t, th\u0103ng giai.\nD\u1ecbch: Ha\u0300o 5, \xe2m: gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4\u0301t, d\xea\u0303 da\u0300ng l\xean th\xea\u0300m.\n","\n\u4e0a\u516d: \u51a5\u5347, \u5229\u4e8e\u4e0d\u606f\u4e4b\u8c9e\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Minh th\u0103ng, l\u01a1\u0323i vu v\xe2\u0323t t\u01b0\u0301c chi trinh.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m:H\xf4n a\u0301m c\u01b0\u0301 mu\xf4\u0301n l\xean hoa\u0300i, n\xea\u0301u s\u01b0\u0309a \u0111\u01b0\u0301c cho h\u01a1\u0323p \u0111a\u0323o chi\u0301nh, kh\xf4ng bao gi\u01a1\u0300 nghi\u0309 thi\u0300 co\u0301 l\u01a1\u0323i.\n")
if(c6&&r.b===1&&r.c===1&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean Phong C\u1ea5u",c5,r.b,r.c,r.d,r.e,r.f,"THA H\u01af\u01a0NG NG\u1ed8 H\u1eeeU",n,m,l,i,h,g,"T\xe0i D\u1ea7n","",2,0,1,e,"",r.r[3],"\n \u521d\u516d: \u7e6b\u4e8e\u91d1\u67c5, \u8c9e\u5409\uff0e\u6709\u6538\u5f80\u898b\u51f6\uff0e\u7fb8\u8c55\u5b5a\u8e62\u8e85\uff0e\nS\u01a1 lu\u0323c: H\xea\u0323 vu Kim n\xea, trinh ca\u0301t; h\u01b0\u0303u du va\u0303ng ki\xea\u0301n hung. Luy thi\u0309 phu tri\u0323ch tru\u0323c.\nD\u1ecbch: Ha\u0300o 1, \xe2m: ch\u0103\u0323n no\u0301 la\u0323i b\u0103\u0300ng ca\u0301i ha\u0303m xe b\u0103\u0300ng kim khi\u0301, thi\u0300 \u0111a\u0323o chi\u0301nh m\u01a1\u0301i t\xf4\u0301t; n\xea\u0301u \u0111\xea\u0309 cho no\u0301 (ha\u0300o 1) ti\xea\u0301n l\xean thi\u0300 x\xe2\u0301u. Con heo \xe2\u0301y tuy g\xe2\u0300y y\xea\u0301u, nh\u01b0ng quy\xea\u0301t ch\u0103\u0301c co\u0301 nga\u0300y no\u0301 se\u0303 nha\u0309y nho\u0301t lung tung.\n","\n\u4e5d\u4e8c: \u5305\u6709\u9b5a, \u65e0\u548e\uff0e\u4e0d\u5229\u8cd3\uff0e\nC\u1eedu nhi\u0323: Bao h\u01b0\u0303u ng\u01b0, v\xf4 c\u01b0\u0303u; b\xe2\u0301t l\u01a1\u0323i t\xe2n.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: nh\xf4\u0301t con ca\u0301 (ha\u0300o 1) va\u0300o trong bo\u0323c, kh\xf4ng co\u0301 l\xf4\u0303i; nh\u01b0ng \u0111\u01b0\u0300ng cho no\u0301 (ha\u0300o 1) g\u0103\u0323p kha\u0301ch.\n","\n\u4e5d\u4e09: \u81c0\u65e0\u819a, \u5176\u884c\u6b21\u4e14, \u53b2, \u65e0\u5927\u548e\uff0e\nC\u1eedu tam: \u0110\xf4\u0300n v\xf4 phu, ki\u0300 ha\u0300nh t\u01b0 th\u01b0, l\xea\u0323, v\xf4 \u0111a\u0323i c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: nh\u01b0 ba\u0300n toa\u0323 kh\xf4ng co\u0301 da (ng\xf4\u0300i kh\xf4ng y\xean ma\u0300 \u0111\u01b0\u0301ng d\xe2\u0323y) \u0111i thi\u0300 ch\xe2\u0323p ch\u01b0\u0303ng, co\u0301 th\xea\u0309 nguy \u0111\xe2\u0301y, nh\u01b0ng kh\xf4ng co\u0301 l\xf4\u0303i l\u01a1\u0301n.\n","\n\u4e5d\u56db: \u5305\u65e0\u9b5a, \u8d77\u51f6\uff0e\nC\u1eedu t\u01b0\u0301: Bao v\xf4 ng\u01b0, kh\u01a1\u0309i hung.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: Trong bo\u0323c cu\u0309a mi\u0300nh kh\xf4ng co\u0301 ca\u0301, hoa\u0323 se\u0303 pha\u0301t.\n","\n\u4e5d\u4e94: \u4ee5\u675e\u5305\u74dc, \u542b\u7ae0, \u6709\u9695\u81ea\u5929\uff0e\nC\u1eedu ngu\u0303: Di\u0303 ki\u0309 bao qua, ha\u0300m ch\u01b0\u01a1ng, h\u01b0\u0303u v\xe2\u0303n t\u01b0\u0323 thi\xean.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: du\u0300ng c\xe2y ki\u0309 ma\u0300 bao che c\xe2y d\u01b0a, ng\xe2\u0323m ch\u01b0\u0301a \u0111\u01b0\u0301c t\xf4\u0301t, (s\u01b0\u0323 t\xf4\u0301t la\u0300nh) t\u01b0\u0300 tr\xean tr\u01a1\u0300i r\u01a1\u0301t xu\xf4\u0301ng.\n","\n\u4e0a\u4e5d: \u59e4\u5176\u89d2, \u541d, \u65e0\u548e\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: C\xe2\u0301u ki\u0300 gia\u0301c, l\xe2\u0323n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: g\u0103\u0323p b\u0103\u0300ng ca\u0301i s\u01b0\u0300ng, \u0111a\u0301ng h\xf4\u0301i ti\xea\u0301c, kh\xf4ng \u0111\xf4\u0309 l\xf4\u0303i cho ai \u0111\u01b0\u01a1\u0323c.\n")
if(c6&&r.b===1&&r.c===1&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch Phong \u0110\u1ea1i Qu\xe1",c5,r.b,r.c,r.d,r.e,r.f,"D\u1ea0 M\u1ed8NG KIM NG\xc2N",n,m,l,m,l,q,c1,c0,2,4,4,a5,a4,r.r[10],"\n\u521d\u516d: \u85c9\u7528\u767d\u8305, \u65e0\u548e\uff0e\nS\u01a1 lu\u0323c: Ta\u0323 du\u0323ng ba\u0323ch mao, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Lo\u0301t (v\xe2\u0323t gi\u0300) b\u0103\u0300ng c\xe2y co\u0309 mao tr\u0103\u0301ng, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u67af\u694a\u751f\u7a0a, \u8001\u592b\u5f97\u5176\u5973\u59bb, \u65e0\u4e0d\u5229\uff0e\nC\u1eedu nhi\u0323: Kh\xf4 d\u01b0\u01a1ng sinh \u0111\xea\u0300, la\u0303o phu \u0111\u0103\u0301c ki\u0300 n\u01b0\u0303 th\xea, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : c\xe2y d\u01b0\u01a1ng kh\xf4 \u0111\xe2m r\xea\u0303 m\u01a1\u0301i, \u0111a\u0300n \xf4ng gia\u0300 c\u01b0\u01a1\u0301i \u0111\u01b0\u01a1\u0323c v\u01a1\u0323 tre\u0309, kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n","\n\u4e5d\u4e09: \u68df\u6a48, \u51f6\uff0e\nC\u1eedu tam: \u0110\xf4\u0301ng na\u0323o, hung.\nD\u1ecbch: Ha\u0300o ba, d\u01b0\u01a1ng: ca\u0301i c\xf4\u0323t cong xu\xf4\u0301ng, x\xe2\u0301u.\n","\n\u4e5d\u56db: \u68df\u9686, \u5409\uff0e\u6709\u5b83, \u541d\uff0e\nC\u1eedu t\u01b0\u0301: \u0110\xf4\u0301ng long, ca\u0301t. H\u01b0\u0303u tha, l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : nh\u01b0 c\xe2y c\xf4\u0323t l\u01a1\u0301n, v\u01b0\u0303ng , t\xf4\u0301t. N\xea\u0301u co\u0301 y\u0301 nghi\u0303a gi\u0300 kha\u0301c thi\u0300 h\xf4\u0301i ti\xea\u0301c.\n","\n\u4e5d\u4e94: \u67af\u694a\u751f\u83ef, \u8001\u5a66\u5f97\u5176\u58eb\u592b, \u65e0\u548e, \u65e0\u8b7d\uff0e\nC\u1eedu ngu\u0303: Kh\xf4 d\u01b0\u01a1ng sinh hoa, la\u0303o phu\u0323 \u0111\u0103\u0301c ki\u0300 si\u0303 phu, v\xf4 c\u01b0\u0303u, v\xf4 d\u01b0\u0323.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng : C\xe2y d\u01b0\u01a1ng kh\xf4 ra hoa, ba\u0300 gia\u0300 co\u0301 ch\xf4\u0300ng trai tra\u0301ng, kh\xf4ng ch\xea cu\u0303ng kh\xf4ng khen.\n","\n\u4e0a\u516d: \u904e\u6d89, \u6ec5\u9802, \u51f6, \u65e0\u548e\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: qua\u0301 thi\xea\u0323p, di\xea\u0323t \u0111i\u0301nh, hung, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m. L\xf4\u0323i qua ch\xf4\u0303 n\u01b0\u01a1\u0301c s\xe2u, n\u01b0\u01a1\u0301c ng\xe2\u0323p \u0111\xe2\u0300u, x\xe2\u0301u: nh\u01b0ng kh\xf4ng co\u0301 l\xf4\u0303i.\n")
if(c6&&r.b===1&&r.c===1&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa Phong \u0110\u1ec9nh",c5,r.b,r.c,r.d,r.e,r.f,"NG\u01af \xd4NG \u0110\u1eaeC L\u1ee2I",n,m,l,l,q,p,"Ph\u1ee5 M\xe3o","",1,0,2,b9,"",r.r[17],"\n\u521d\u516d: \u9f0e\u985b\u8dbe, \u5229\u51fa\u5426, \u5f97\u59be, \u4ee5\u5176\u5b50, \u65e0\u548e\uff0e\nS\u01a1 lu\u0323c: \u0110i\u0309nh \u0111i\xean chi\u0309, l\u01a1\u0323i xu\xe2\u0301t bi\u0303, \u0111\u0103\u0301c thi\xea\u0301p, di\u0303 ki\u0300 t\u01b0\u0309, v\xf4 c\u01b0\u0303u\nD\u1ecbch: Ha\u0300o 1, \xe2m :Va\u0323c ch\xf4\u0301ng ch\xe2n l\xean, tru\u0301t nh\u01b0\u0303ng \u0111\xf4\u0300 d\u01a1 bu\u0323i b\u0103\u0323m (bi\u0303) ra thi\u0300 l\u01a1\u0323i; (ng\xe2\u0303u nhi\xean g\u0103\u0323p may) nh\u01b0 g\u0103\u0323p \u0111\u01b0\u01a1\u0323c ng\u01b0\u01a1\u0300i thi\xea\u0301p \u0111\xea\u0309 sinh con cho mi\u0300nh, kh\xf4ng l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u9f0e\u6709\u5be6, \u6211\u4ec7\u6709\u75be, \u4e0d\u6211\u80fd\u5373, \u5409\uff0e\nC\u1eedu nhi\u0323: \u0110i\u0309nh h\u01b0\u0303u th\u01b0\u0323c, nga\u0303 c\u01b0\u0309u h\u01b0\u0303u t\xe2\u0323t, b\xe2\u0301t nga\u0303 n\u0103ng t\u01b0\u0301c, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: Va\u0323c ch\u01b0\u0301a th\u01b0\u0301c \u0103n r\xf4\u0300i; ke\u0309 thu\u0300 oa\u0301n ta vi\u0300 ghen tu\xf4ng, nh\u01b0ng kh\xf4ng t\u01a1\u0301i g\xe2\u0300n ta \u0111\u01b0\u01a1\u0323c. t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u9f0e\u8033\u9769, \u5176\u884c\u585e, \u96c9\u818f\u4e0d\u98df\uff0e\u65b9\u96e8, \u8667\u6094, \u7d42\u5409\uff0e\nC\u1eedu tam: \u0110i\u0309nh nhi\u0303 ca\u0301ch, ki\u0300 ha\u0300nh t\u0103\u0301c, tri\u0303 cao b\xe2\u0301t th\u01b0\u0323c; ph\u01b0\u01a1ng vu\u0303, khuy h\xf4\u0301i, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: nh\u01b0 ca\u0301i tai va\u0323c d\u01b0\u01a1ng thay \u0111\xf4\u0309i, ch\u01b0a c\xe2\u0301t va\u0323c l\xean \u0111\u01b0\u01a1\u0323c, tha\u0300nh th\u01b0\u0309 m\u01a1\u0303 chim tri\u0303 (m\u01a1\u0303 ngon) ch\u01b0a \u0111em ra cho ng\u01b0\u01a1\u0300i ta \u0103n; nh\u01b0ng s\u0103\u0301p m\u01b0a r\xf4\u0300i, kh\xf4ng co\u0300n \u0103n n\u0103n n\u01b0\u0303a, k\xea\u0301t qua\u0309 se\u0303 t\xf4\u0301t.\n","\n\u4e5d\u56db: \u9f0e\u6298\u8db3, \u8986\u516c\u9917\u5176\u5f62\u6e25, \u51f6\uff0e\nC\u1eedu t\u01b0\u0301: \u0110i\u0309nh chi\xea\u0301t tu\u0301c, phu\u0301c c\xf4ng t\xf4\u0301c (tu\u0301c) ki\u0300 hi\u0300nh \xf4\u0301c, hung.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: Ch\xe2n va\u0323c g\xe2\u0303y, \u0111a\u0301nh \u0111\xf4\u0309 th\u01b0\u0301c \u0103n cu\u0309a nha\u0300 c\xf4ng h\xe2\u0300u, ma\u0300 bi\u0323 hi\u0300nh pha\u0323t n\u0103\u0323ng, x\xe2\u0301u.\n","\n\u516d\u4e94: \u9f0e\u9ec3\u8033, \u91d1\u9249, \u5229\u8c9e\uff0e\nL\u1ee5c ngu\u0303: \u0110i\u0309nh hoa\u0300ng nhi\u0303, kim huy\xea\u0303n, l\u01a1\u0323i trinh.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Va\u0323c co\u0301 tai ma\u0300u va\u0300ng, co\u0301 \u0111o\u0300n x\xe2u b\u0103\u0300ng kim khi\u0301; gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c \u0111a\u0323o chi\u0301nh thi\u0300 b\xea\u0300n.\n","\n\u4e0a\u4e5d: \u9f0e\u7389\u9249, \u5927\u5409, \u65e0\u4e0d\u5229.\nTh\u01b0\u1ee3ng c\u01b0\u0309u: \u0110i\u0309nh ngo\u0323c huy\xea\u0303n, \u0111a\u0323i ca\u0301t, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng d\u01b0\u01a1ng: va\u0323c co\u0301 ca\u0301i \u0111o\u0300n x\xe2u b\u0103\u0300ng ngo\u0323c r\xe2\u0301t t\xf4\u0301t, kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n")
if(c6&&r.b===1&&r.c===1&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i Phong H\u1eb1ng",c5,r.b,r.c,r.d,r.e,r.f,"NG\u01af LAI TR\xc0NG V\xd5NG",n,m,l,i,h,g,c1,"",2,0,3,a5,"",r.r[24],"\n\u521d\u516d: \u6d5a\u6046, \u8c9e\u51f6, \u65e0\u6538\u5229\uff0e\nS\u01a1 lu\u0323c: tu\xe2\u0301n h\u0103\u0300ng, trinh hung, v\xf4 du l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Qua\u0301 mong \u0111\u01b0\u01a1\u0323c th\xe2n m\xe2\u0323t l\xe2u da\u0300i; c\u01b0\u0301 quy\xea\u0301t (trinh) nh\u01b0 v\xe2\u0323y, kh\xf4ng chi\u0323u bo\u0309 thi\u0300 x\xe2\u0301u, kh\xf4ng la\u0300m gi\u0300 \u0111\u01b0\u01a1\u0323c thu\xe2\u0323n l\u01a1\u0323i ca\u0309.\n","\n\u4e5d\u4e8c: \u6094\u4ea1\uff0e\nC\u1eedu nhi\u0323: h\xf4\u0301i vong.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: h\xf4\u0301i h\xe2\u0323n ti\xeau h\xea\u0301t.\n","\n\u4e5d\u4e09: \u4e0d\u6046\u5176\u5fb7, \u6216\u627f\u4e4b\u7f9e, \u8c9e\u541d\uff0e\nC\u1eedu tam: B\xe2\u0301t h\u0103\u0300ng ki\u0300 \u0111\u01b0\u0301c, ho\u0103\u0323c th\u01b0\u0300a chi tu, trinh l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : kh\xf4ng th\u01b0\u01a1\u0300ng gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c ca\u0301i \u0111\u01b0\u0301c cu\u0309a mi\u0300nh, co\u0301 khi bi\u0323 x\xe2\u0301u h\xf4\u0309, du\u0300 chi\u0301nh \u0111a\u0301ng cu\u0303ng \u0111a\u0301ng ti\xea\u0301c.\n","\n\u4e5d\u56db: \u7530\u65e0\u79bd\uff0e\nC\u1eedu t\u01b0\u0301: \u0110i\xea\u0300n v\xf4 c\xe2\u0300m.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : nh\u01b0 \u0111i s\u0103n ma\u0300 kh\xf4ng \u0111\u01b0\u01a1\u0323c c\xe2\u0300m thu\u0301.\n","\n\u516d\u4e94: \u6046\u5176\u5fb7, \u8c9e. \u5a66\u4eba\u5409, \u592b\u5b50\u51f6\uff0e\nL\u1ee5c ngu\u0303: H\u0103\u0300ng ky\u0300 \u0111\u01b0\u0301c, trinh. Phu\u0323 nh\xe2n ca\u0301t, phu t\u01b0\u0309 hung.\nD\u1ecbch: Ha\u0300o 5, \xe2m: gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c th\u01b0\u01a1\u0300ng (l\xe2u) \u0111\u01b0\u0301c cu\u0309a mi\u0300nh, b\xea\u0300n ma\u0300 chi\u0301nh. \u0110a\u0300n ba\u0300 thi\u0300 t\xf4\u0301t, \u0111a\u0300n \xf4ng thi\u0300 x\xe2\u0301u.\n","\n\u4e0a\u516d: \u632f\u6046, \u51f6\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: ch\xe2\u0301n h\u0103\u0300ng, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: c\u01b0\u0309 \u0111\xf4\u0323ng hoa\u0300i, kh\xf4ng chi\u0323u y\xean thi\u0300 x\xe2\u0301u.\n")
if(c6&&r.b===1&&r.c===1&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("B\xe1t Thu\u1ea7n T\u1ed1n",c5,r.b,r.c,r.d,r.e,r.f,"CH\xc2U \u0110\u1eaeC THU\u1eacN PHONG",n,m,l,q,p,o,"","",0,0,6,b3,j,r.r[39],"\n\u521d\u516d: \u9032\u9000, \u5229\u6b66\u4eba\u4e4b\u8c9e\uff0e\nS\u01a1 lu\u0323c: ti\xea\u0301n thoa\u0301i, l\u01a1\u0323i vu\u0303 nh\xe2n chi trinh.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Ti\xea\u0301n lui t\u01b0\u0323 do, th\xeam va\u0300o ca\u0301i chi\u0301 h\u01b0\u01a1\u0301ng b\xea\u0300n cu\u0309a ha\u0323ng vo\u0303 du\u0303ng thi\u0300 co\u0301 l\u01a1\u0323i.\n","\n\u4e5d\u4e8c: \u5dfd\u5728\u5e8a\u4e0b, \u7528\u53f2\u5deb \u7d1b\u82e5, \u5409,\u65e0\u548e\uff0e\nC\u1eedu nhi\u0323: T\xf4\u0301n ta\u0323i sa\u0300ng ha\u0323, du\u0323ng s\u01b0\u0309 vu ph\xe2n nh\u01b0\u01a1\u0323c, ca\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: Thu\xe2\u0323n ne\u0301p \u01a1\u0309 d\u01b0\u01a1\u0301i gi\u01b0\u01a1\u0300ng, du\u0300ng va\u0300o vi\xea\u0323c l\xea\u0303 ba\u0301i, \u0111\xf4\u0300ng c\xf4\u0301t r\xf4\u0301i ren thi\u0300 t\xf4\u0301t, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e09: \u983b\u5dfd\u541d\uff0e\nC\u1eedu tam: T\xe2\u0300n t\xf4\u0301n, l\xe2\u0323n.\nD\u1ecbch: Thu\xe2\u0323n to\u0300ng qua\u0301 nhi\xea\u0300u l\xe2\u0300n (qua\u0301 m\u01b0\u0301c), \u0111a\u0301ng x\xe2\u0301u h\xf4\u0309.\n","\n\u516d\u56db: \u6094\u4ea1, \u7530\u7372\u4e09\u54c1\uff0e\nL\u1ee5c t\u01b0\u0301: H\xf4\u0301i vong, \u0111i\xea\u0300n hoa\u0323ch tam ph\xe2\u0309m.\nD\u1ecbch: Ha\u0300o 4, \xe2m: H\xf4\u0301i h\xe2\u0323n m\xe2\u0301t \u0111i; \u0111i s\u0103n v\xea\u0300, \u0111\u01b0\u01a1\u0323c chia cho ba ph\xe2\u0300n.\n","\n\u4e5d\u4e94: \u8c9e\u5409, \u6094\u4ea1, \u65e0\u4e0d\u5229, \u65e0\u521d\u6709\u7d42.\n\u5148\u5e9a\u4e09\u65e5, \u5f8c\u5e9a\u4e09\u65e5\uff0e\u5409\uff0e\nC\u1eedu ngu\u0303: Trinh ca\u0301t, h\xf4\u0301i vong, v\xf4 b\xe2\u0301t l\u01a1\u0323i, v\xf4 s\u01a1\u0309 h\u01b0\u0303u chung.\nTi\xean canh tam nh\xe2\u0323t, h\xe2\u0323u canh tam nh\xe2\u0323t, ca\u0301t\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng : gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4t, h\xf4\u0301i h\xe2\u0323n m\xe2\u0301t \u0111i, kh\xf4ng co\u0301 gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i, m\u01a1\u0301i \u0111\xe2\u0300u kh\xf4ng kha\u0301 ma\u0300 cu\xf4\u0301i cu\u0300ng t\xf4\u0301t; (\u0111inh ninh nh\u01b0 ) tr\u01b0\u01a1\u0301c nga\u0300y canh ba nga\u0300y, (\u0111\u0103\u0301n \u0111o nh\u01b0) sau nga\u0300y canh ba nga\u0300y, t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u5dfd\u5728\u5e8a\u4e0b, \u55aa\u5176\u8cc7\u65a7, \u8c9e\u51f6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: T\xf4\u0301n ta\u0323i sa\u0300ng ha\u0323, ta\u0301ng ki\u0300 t\u01b0 phu\u0309, trinh hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: Thu\xe2\u0323n ne\u0301p \u01a1\u0309 d\u01b0\u01a1\u0301i gi\u01b0\u01a1\u0300ng, m\xe2\u0301t \u0111\xf4\u0300 h\xf4\u0323 th\xe2n, c\u01b0\u0301 gi\u01b0\u0303 tho\u0301i x\xe2\u0301u \u0111o\u0301 thi\u0300 ca\u0300ng bi\u0323 hoa\u0323.\n")
if(c6&&r.b===1&&r.c===1&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("Th\u1ee7y Phong T\u1ec9nh",c5,r.b,r.c,r.d,r.e,r.f,"KH\xd4 T\u1ec8NH SINH TUY\u1ec0N",n,m,l,h,g,a7,c1,c0,2,4,5,a5,"",r.r[46],"\n\u521d\u516d: \u4e95\u6ce5\u4e0d\u98df\uff0e\u820a\u4e95\u65e0\u79bd\uff0e\nS\u01a1 lu\u0323c: ti\u0309nh n\xea, b\xe2\u0301t th\u01b0\u0323c, c\u01b0\u0323u ti\u0309nh v\xf4 c\xe2\u0300m.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Gi\xea\u0301ng l\xe2\u0300y bu\u0300n, kh\xf4ng ai la\u0323i l\xe2\u0301y n\u01b0\u01a1\u0301c; kh\xf4ng co\u0301 con v\xe2\u0323t na\u0300o la\u0323i m\xf4\u0323t gi\xea\u0301ng cu\u0303.\n","\n\u4e5d\u4e8c: \u4e95\u8c37, \u5c04\u9b92, \u7515\u655d\u6f0f\uff0e\nC\u1eedu nhi\u0323: Ti\u0309nh c\xf4\u0301c, xa\u0323 phu\u0323, u\u0309ng t\xea\u0323 l\xe2\u0323u.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: gi\xea\u0301ng \u01a1\u0309 trong hang (co\u0301 ng\u01b0\u01a1\u0300i hi\xea\u0309u la\u0300 gi\xea\u0301ng co\u0301 ca\u0301i hang), n\u01b0\u01a1\u0301c chi\u0309 la\u0301ch ta\u0301ch i\u0301t gio\u0323t b\u0103\u0301n va\u0300o con gi\xea\u0301c, nh\u01b0 ca\u0301i chum n\u01b0\u0301t, n\u01b0\u01a1\u0301c di\u0309 ra.\n","\n\u4e5d\u4e09: \u4e95\u6e2b\u4e0d\u98df, \u70ba\u6211\u5fc3\u60fb\uff0e\u53ef\u7528\u6c72. \u738b\u660e, \u4e26\u53d7\u5176\u798f\uff0e\nC\u1eedu tam: ti\u0309nh ti\xea\u0301t b\xe2\u0301t th\u01b0\u0323c, vi nga\u0303 t\xe2m tr\u0103\u0301c.\nKha\u0309 du\u0323ng c\xe2\u0301p; v\u01b0\u01a1ng minh, ti\u0323nh thu\u0323 ki\u0300 phu\u0301c.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: gi\xea\u0301ng trong ma\u0300 ch\u0103\u0309ng \u0103n, \u0111\xea\u0309 lo\u0300ng ta th\u01b0\u01a1ng xo\u0301t, co\u0301 th\xea\u0309 du\u0300ng ma\u0300 mu\u0301c l\xean \u0111\u01b0\u01a1\u0323c; g\u0103\u0323p \xf4ng vua sa\u0301ng su\xf4\u0301t thi\u0300 mo\u0323i ng\u01b0\u01a1\u0300i \u0111\xea\u0300u \u0111\u01b0\u01a1\u0323c phu\u0301c.\n","\n\u516d\u56db: \u4e95\u7503, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: Ti\u0309nh tr\u01b0\u0301u, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Gi\xea\u0301ng ma\u0300 tha\u0300nh va\u0300 \u0111a\u0301y x\xea\u0301p \u0111a\u0301, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e94: \u4e95\u6d0c, \u5bd2\u6cc9\u98df\uff0e\nC\u1eedu ngu\u0303: Ti\u0309nh li\xea\u0323t, ha\u0300n tuy\xea\u0300n th\u01b0\u0323c.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: N\u01b0\u01a1\u0301c gi\xea\u0301ng trong, la\u0323nh, mu\u0301c l\xean \u0103n \u0111\u01b0\u01a1\u0323c.\n","\n\u4e0a\u516d: \u4e95\u6536, \u52ff\u5e55, \u6709\u5b5a, \u5143\u5409\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Ti\u0309nh thu, v\xe2\u0323t ma\u0323c, h\u01b0\u0303u phu, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: N\u01b0\u01a1\u0301c gi\xea\u0301ng mu\u0301c l\xean r\xf4\u0300i, \u0111\u01b0\u0300ng che \u0111\xe2\u0323y, c\u01b0\u0301 ma\u0303i ma\u0303i nh\u01b0 v\xe2\u0323y, kh\xf4ng thay \u0111\xf4\u0309i thi\u0300 r\xe2\u0301t t\xf4\u0301t.\n")
if(c6&&r.b===1&&r.c===1&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n Phong C\u1ed5",c5,r.b,r.c,r.d,r.e,r.f,"TH\xd4I MA PH\u1ea6N \u0110\u1ea0O",n,m,l,g,a7,a9,"T\u1eed T\u1ecb","",5,0,3,b3,a8,r.r[53],"\n\u521d\u516d: \u5e79\u7236\u4e4b\u8831, \u6709\u5b50, \u8003\u65e0\u548e, \u53b2, \u7d42\u5409\uff0e\nS\u01a1 lu\u0323c: Ca\u0301n phu\u0323 chi c\xf4\u0309, h\u01b0\u0303u t\u01b0\u0309, kha\u0309o v\xf4 c\u01b0\u0303u , l\xea\u0323, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, \xe2m: S\u01b0\u0309a sang s\u01b0\u0323 \u0111\xf4\u0309 na\u0301t cu\u0309a cha; nh\u01a1\u0300 con ma\u0300 cha kh\xf4ng l\xf4\u0303i; nh\u01b0ng cu\u0303ng co\u0301 th\xea\u0309 nguy \u0111\xe2\u0301y, pha\u0309i bi\xea\u0301t r\u0103n s\u01a1\u0323, sau m\u01a1\u0301i t\xf4\u0301t.\n","\n\u4e5d\u4e8c: \u5e79\u6bcd\u4e4b\u8831, \u4e0d\u53ef\u8c9e\uff0e\nC\u1eedu nhi\u0323: Ca\u0301n m\xe2\u0303u chi c\xf4\u0309, b\xe2\u0301t kha\u0309 trinh.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : S\u01b0\u0309a sang s\u01b0\u0323 \u0111\xf4\u0309 na\u0301t cu\u0309a me\u0323, kh\xf4ng n\xean c\xf4\u0301 ch\xe2\u0301p (trinh)\n","\n\u4e5d\u4e09: \u5e79\u7236\u4e4b\u8831, \u5c0f\u6709\u6094, \u65e0\u5927\u548e\uff0e\nC\u1eedu tam: Ca\u0301n phu\u0323 chi c\xf4\u0309, ti\xea\u0309u h\u01b0\u0303u h\xf4\u0301i, v\xf4 \u0111a\u0323i c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: s\u01b0\u0309a sang s\u01b0\u0323 \u0111\xf4\u0309 na\u0301t cu\u0309a cha, co\u0301 chu\u0301t h\xf4\u0301i h\xe2\u0323n nh\u01b0\u0303ng kh\xf4ng co\u0301 l\xf4\u0303i l\u01a1\u0301n.\n","\n\u516d\u56db: \u88d5\u7236\u4e4b\u8831, \u5f80\u898b\u541d\uff0e\nL\u1ee5c t\u01b0\u0301: Du\u0323 phu\u0323 chi C\xf4\u0309, va\u0303ng ki\xea\u0301n l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 4, \xe2m: (Vi\u0300 du\u0300ng d\u0103\u0300ng ma\u0300 chi\u0309) ke\u0301o da\u0300i s\u01b0\u0323 \u0111\xf4\u0309 na\u0301t cu\u0309a cha, n\xea\u0301u c\u01b0\u0301 nh\u01b0 v\xe2\u0323y hoa\u0300i thi\u0300 se\u0303 h\xf4\u0301i ti\xea\u0301c.\n","\n\u516d\u4e94: \u5e79 \u7236\u4e4b\u8831, \u7528\u8b7d\uff0e\nL\u1ee5c ngu\u0303: Ca\u0301n phu\u0323 chi c\xf4\u0309, du\u0323ng d\u01b0\u0323\nD\u1ecbch: Ha\u0300o 5, \xe2m: s\u01b0\u0309a s\u01b0\u0323 \u0111\xf4\u0309 na\u0301t cho cha, ma\u0300 \u0111\u01b0\u01a1\u0323c ti\xea\u0301ng khen.\n","\n\u4e0a\u4e5d: \u4e0d\u4e8b\u738b\u4faf, \u9ad8\u5c1a \u5176\u4e8b\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: B\xe2\u0301t s\u01b0\u0323 v\u01b0\u01a1ng h\xe2\u0300u, cao th\u01b0\u01a1\u0323ng ky\u0300 s\u01b0\u0323.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng : Kh\xf4ng xu phu\u0323 b\xe2\u0323c v\u01b0\u01a1ng h\xe2\u0300u, ma\u0300 n\xeau cao t\u01b0 ca\u0301ch (\u0111\u01b0\u0301c cu\u0309a mi\u0300nh.)\n")
if(c6&&r.b===1&&r.c===0&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba Th\u1ee7y S\u01b0",c5,r.b,r.c,r.d,r.e,r.f,"M\xc3 \u0110\xc1O TH\xc0NH C\xd4NG",a9,b0,i,n,m,l,"","",0,0,3,b7,a8,r.r[61],"\n\u521d \u516d : \u5e2b, \u51fa \u4ee5 \u5f8b , \u5426 \u81e7, \u51f6 \uff0e\nS\u01a1 lu\u0323c: s\u01b0, xu\xe2\u0301t di\u0303 lu\xe2\u0323t, phu\u0309 ta\u0300ng, hung\nD\u1ecbch: Ha\u0300o 1, \xe2m: Ra qu\xe2n thi\u0300 pha\u0309i co\u0301 ky\u0309 lu\xe2\u0323t, kh\xf4ng khe\u0301o (ch\u01b0\u0303 phu\u0309 ta\u0300ng nghi\u0303a la\u0300 b\xe2\u0301t thi\xea\u0323n ) thi x\xe2\u0301u.\n","\n\u4e5d \u4e8c : \u5728 \u5e2b, \u4e2d, \u5409, \u65e0 \u548e , \u738b \u4e09 \u932b \u547d \uff0e\nC\u1eedu nhi\u0323: Ta\u0323i s\u01b0, trung, ca\u0301t, v\xf4 c\u01b0\u0303u, v\u01b0\u01a1ng tam ti\u0301ch m\xea\u0323nh.\nD\u1ecbch: Ha\u0300o 2 d\u01b0\u01a1ng: Trong qu\xe2n, co\u0301 \u0111\u01b0\u0301c trung thi\u0300 t\xf4\u0301t, kh\xf4ng t\xf4\u0323i l\xf4\u0303i, \u0111\u01b0\u01a1\u0323c vua ba l\xe2\u0300n ban th\u01b0\u01a1\u0309ng.\n","\n\u516d \u4e09 : \u5e2b, \u6216 \u8f3f \u5c38 , \u51f6 \uff0e\nL\u1ee5c tam: S\u01b0, ho\u0103\u0323c d\u01b0 thi, hung.\nD\u1ecbch: Ha\u0300o 3, \xe2m: b\xe2\u0301t chi\u0301nh (vi\u0300 ha\u0300o \xe2m \u01a1\u0309 ng\xf4i d\u01b0\u01a1ng) la\u0323i b\xe2\u0301t trung ,x\xe2\u0301u, th\xe2\u0301t tr\xe2\u0323n, co\u0301 th\xea\u0309 pha\u0309i ch\u01a1\u0309 xa\u0301c ch\xea\u0301t v\xea\u0300 . \n","\n\u516d \u56db : \u5e2b, \u5de6 \u6b21 , \u65e0 \u548e \uff0e\nL\u1ee5c t\u01b0\u0301: S\u01b0, ta\u0309 th\u01b0\u0301, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Ra qu\xe2n r\xf4\u0300i ma\u0300 lui v\xea\u0300 \u0111o\u0301ng (th\u01b0\u0301) \u01a1\u0309 phi\u0301a sau (ta\u0309) kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d \u4e94 : \u7530 \u6709 \u79bd \uff0e \u5229 \u57f7 \u8a00 \uff0e \u65e0 \u548e \uff0e \u9577 \u5b50 \u5e25 \u5e2b \uff0e \u5f1f \u5b50 \u8f3f \u5c38 \uff0e \u8c9e \u51f6 \uff0e\nL\u1ee5c ngu\u0303: \u0110i\xea\u0300n h\u01b0\u0303u c\xe2\u0300m, l\u01a1\u0323i ch\xe2\u0301p ng\xf4n, v\xf4 c\u01b0\u0303u.\nTr\u01b0\u01a1\u0309ng t\u01b0\u0309 xu\xe2\u0301t s\u01b0, \u0111\xea\u0323 t\u01b0\u0309 d\u01b0 thi, trinh hung.\nD\u1ecbch: Ha\u0300o 5 \xe2m: Nh\u01b0 \u0111\xf4\u0300ng co\u0309 mu\xf4ng thu\u0301 (v\xea\u0300 pha\u0301), b\u0103\u0301t chu\u0301ng (ch\u01b0\u0303 ng\xf4n [\u8a00] \u01a1\u0309 \u0111\xe2y,du\u0300ng nh\u01b0 ch\u01b0\u0303 chi [\u4e4b], thay ch\u01b0\u0303 c\xe2\u0300m [\u79bd]) thi\u0300 l\u01a1\u0323i.(du\u0300ng) ng\u01b0\u01a1\u0300i la\u0303o tha\u0300nh la\u0300m t\u01b0\u01a1\u0301ng su\u0301y \u0111\xea\u0309 c\xe2\u0300m qu\xe2n, n\xea\u0301u du\u0300ng bo\u0323n tre\u0309 (ta\u0300i ke\u0301m) thi\u0300 pha\u0309i ch\u01a1\u0309 th\xe2y ma\u0300 v\xea\u0300, va\u0300 du\u0300 danh nghi\u0303a chi\u0301nh \u0111a\u0301ng (trinh) k\xea\u0301t qua\u0309 v\xe2\u0303n x\xe2\u0301u.\n","\n\u4e0a \u516d : \u5927 \u541b \u6709 \u547d \uff0e \u958b \u570b \u627f \u5bb6 , \u5c0f \u4eba \u52ff \u7528 \uff0e\nTh\u01b0\u1ee3ng lu\u0323c: \u0111a\u0323i qu\xe2n h\u01b0\u0303u m\xea\u0323nh.\nKhai qu\xf4\u0301c th\u01b0\u0300a gia, ti\xea\u0309u nh\xe2n v\xe2\u0323t du\u0323ng.\nD\u1ecbch Ha\u0300o tr\xean cu\u0300ng, \xe2m: (Sau khi kha\u0309i ho\u0300an) vua ra l\xea\u0323nh gi\u0300 quan h\xea\u0323 \u0111\xea\u0301n vi\xea\u0323c m\u01a1\u0309 n\u01b0\u01a1\u0301c tri\u0323 nha\u0300 thi\u0300 \u0111\u01b0\u0300ng du\u0300ng ke\u0309 ti\xea\u0309u nh\xe2n (du\u0300 ho\u0323 co\u0301 c\xf4ng chi\xea\u0301n \u0111\xe2\u0301u).\n")
if(c6&&r.b===1&&r.c===0&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean Th\u1ee7y T\u1ee5ng",c5,r.b,r.c,r.d,r.e,r.f,"NH\u1eca NH\xc2N TRANH L\u1ed8",a9,b0,i,i,h,g,c2,"",3,0,4,b9,a4,r.r[4],"\n\u521d \u516d: \u4e0d \u6c38 \u6240 \u4e8b , \u5c0f \u6709 \u8a00 , \u7d42 \u5409 \uff0e\nS\u01a1 lu\u0323c: B\xe2\u0301t vinh s\u01a1\u0309 s\u01b0\u0323, ti\xea\u0309u h\u01b0\u0303u ng\xf4n, chung ca\u0301t.\nD\u1ecbch: Ha\u0300o 1 \xe2m: \u0111\u01b0\u0300ng ke\u0301o da\u0300i (vu\u0323 ki\xea\u0323n) la\u0300m gi\u0300, tuy bi\u0323 tra\u0301ch m\xf4\u0323t chu\u0301t, nh\u01b0ng sau \u0111\u01b0\u01a1\u0323c t\xf4\u0301t.\n","\n\u4e5d \u4e8c: \u4e0d \u514b \u8a1f , \u6b78 \u800c \u900b. \u5176 \u9091 \u4eba \u4e09 \u767e \u6236, \u65e0 \u771a\uff0e\nC\u1eedu nhi\u0323: B\xe2\u0301t kh\u0103\u0301c tu\u0323ng, qui nhi b\xf4. Ki\u0300 \xe2\u0301p nh\xe2n tam ba\u0301ch h\xf4\u0323, v\xf4 sa\u0309nh.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng : kh\xf4ng n\xean ki\xea\u0323n, lui v\xea\u0300 ma\u0300 tra\u0301nh \u0111i, \xe2\u0301p mi\u0300nh chi\u0309 co\u0301 ba tr\u0103m no\u0301c nha\u0300 th\xf4i (y\u0301 no\u0301i \u0111i\u0323a vi\u0323 mi\u0300nh th\xe2\u0301p, th\xea\u0301 mi\u0300nh nho\u0309), nh\u01b0 v\xe2\u0323y thi\u0300 kh\xf4ng bi\u0323 ho\u0323a.\n","\n\u516d \u4e09 : \u98df \u820a \u5fb7, \u8c9e \u53b2, \u7d42 \u5409 \uff0e \u6216 \u5f9e \u738b \u4e8b , \u65e0 \u6210.\nL\u1ee5c tam: Th\u01b0\u0323c c\u01b0\u0323u \u0111\u01b0\u0301c, trinh l\xea\u0323,\nChung ca\u0301t; ho\u0103\u0323c to\u0300ng v\u01b0\u01a1ng s\u01b0\u0323, v\xf4 tha\u0300nh.\nD\u1ecbch: Ha\u0300o 3 \xe2m, C\u01b0\u0301 (y\xean \xf4\u0309n) h\u01b0\u01a1\u0309ng ca\u0301i \u0111\u01b0\u0301c (\xe2n tra\u0323ch) cu\u0303 cu\u0309a mi\u0300nh (Chu Hi hi\xea\u0309u la\u0300 gi\u01b0\u0303 ca\u0301i n\xea\u0301p cu\u0303), \u0103n \u01a1\u0309 cho chi\u0301nh \u0111a\u0301ng ma\u0300 th\u01b0\u01a1\u0300ng \u0111\xea\u0309 lo\u0300ng lo s\u01a1\u0323 thi\u0300 k\xea\u0301t qua\u0309 se\u0303 t\xf4\u0301t; n\xea\u0301u pha\u0309i \u0111i theo la\u0300m v\u01a1\u0301i ng\u01b0\u01a1\u0300i tr\xean (ch\u01b0\u0303 v\u01b0\u01a1ng \u01a1\u0309 \u0111\xe2y tr\u01a1\u0309 ng\u01b0\u01a1\u0300i tr\xean, kh\xf4ng nh\xe2\u0301t \u0111i\u0323nh la\u0300 vua), thi\u0300 cu\u0303ng \u0111\u01b0\u0300ng mong tha\u0300nh c\xf4ng.\n","\n\u4e5d \u56db : \u4e0d\u514b \u8a1f , \u5fa9 \u5373 \u547d, \u6e1d , \u5b89 \u8c9e \u5409 \uff0e\nC\u1eedu t\u01b0\u0301: B\xe2\u0301t kh\u0103\u0301c tu\u0323ng, phu\u0323c t\u01b0\u0301c m\xea\u0323nh, du, an trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : kh\xf4ng th\xea\u0309 ki\xea\u0323n ca\u0301o \u0111\u01b0\u01a1\u0323c, tr\u01a1\u0309 la\u0323i theo thi\xean m\xea\u0323nh (le\u0303 chi\u0301nh \u0111a\u0301ng), \u0111\xf4\u0309i y\u0301 \u0111i, \u01a1\u0309 y\xean theo \u0111i\xea\u0300u chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u4e5d \u4e94 : \u8a1f, \u5143 \u5409 \uff0e\nC\u1eedu ngu\u0303: Tu\u0323ng, nguy\xean ca\u0301t.\nD\u1ecbch: Ha\u0300o 5 d\u01b0\u01a1ng : x\u01b0\u0309 ki\xea\u0323n hay \u0111i ki\xea\u0323n, \u0111\xea\u0300u r\xe2\u0301t t\xf4\u0301t.\n","\n\u4e0a \u4e5d : \u6216 \u932b \u4e4b \u97b6 \u5e36 , \u7d42 \u671d, \u4e09 \u892b \u4e4b\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: ho\u0103\u0323c ti\u0301ch chi ba\u0300n \u0111a\u0301i, chung tri\xeau, tam si\u0309 chi.\nD\u1ecbch: ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng : (ki\xea\u0323n ) may ma\u0300 \u0111\u01b0\u01a1\u0323c ca\u0301i \u0111ai l\u01a1\u0301n (cu\u0309a quan ch\u01b0\u0301c) thi\u0300 trong m\xf4\u0323t bu\xf4\u0309i sa\u0301ng se\u0303 bi\u0323 c\u01b0\u01a1\u0301p ba l\xe2\u0300n.\n")
if(c6&&r.b===1&&r.c===0&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch Th\u1ee7y Kh\u1ed1n",c5,r.b,r.c,r.d,r.e,r.f,"THO\xc1T L\xc3NG TR\u1eeaU \u0110\xca",a9,b0,i,m,l,q,"","",0,0,1,a3,d,r.r[11],"\n\u521d\u516d: \u81c0\u56f0\u4e8e\u682a\u6728, \u5165\u4e8e\u5e7d\u8c37, \u4e09\u6b72\u4e0d\u89bf\uff0e\nS\u01a1 lu\u0323c: \u0110\xf4\u0300n kh\xf4\u0301n vu ch\xe2u m\xf4\u0323c, nh\xe2\u0323p vu u c\xf4\u0301c, tam tu\xea\u0301 b\xe2\u0301t di\u0323ch.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Ba\u0300n toa\u0323 bi\u0323 kh\xf4\u0301n \u01a1\u0309 g\xf4\u0301c c\xe2y, la\u0323i su\u0323p va\u0300o trong hang t\xf4\u0301i, ba n\u0103m kh\xf4ng th\xe2\u0301y ai.\n","\n\u4e5d\u4e8c: \u56f0\u4e8e\u9152\u98df, \u6731\u7d31\u65b9\u4f86\uff0e\u5229\u7528\u4eab\u7940, \u5f81\u51f6, \u65e0\u548e\uff0e\nC\u1eedu nhi\u0323: Kh\xf4\u0301n vu t\u01b0\u0309u th\u01b0\u0323c, chu ph\xe2\u0301t lai.\nL\u1ee3i du\u0323ng h\u01b0\u01a1\u0309ng t\u01b0\u0323, chinh hung, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o na\u0300y d\u01b0\u01a1ng c\u01b0\u01a1ng, \u0111\u0103\u0301c trung, \u0111a\u0301ng le\u0303 t\xf4\u0301t, nh\u01b0ng \u01a1\u0309 th\u01a1\u0300i Kh\xf4\u0301n thi\u0300 cu\u0303ng v\xe2\u0303n bi\u0323 kh\xf4\u0301n vi\u0300 \u0103n u\xf4\u0301ng, do \u01a1n vua l\xf4\u0323c n\u01b0\u01a1\u0301c; \u0111\u01b0\u01a1\u0323c \u01a1\u0309 tr\xean \u01b0\u0301ng h\u01a1\u0323p la\u0323i nh\u01a1\u0300 giu\u0301p (\u01a1\u0309 \u0111\xe2y t\u01b0\u01a1\u0323ng tr\u01b0ng b\u0103\u0300ng vi\xea\u0323c \u0111em ca\u0301i \u201cph\xe2\u0301t\u201d \u0111o\u0309, m\xf4\u0323t b\xf4\u0323 ph\xe2\u0323n l\xea\u0303 phu\u0323c \u0111\xea\u0309 che \u0111\xe2\u0300u g\xf4\u0301i); n\xean \u0111em lo\u0300ng tinh tha\u0300nh \u0111\xea\u0309 t\xea\u0301 th\xe2\u0300n linh ma\u0300 x\u01b0\u0309 s\u01b0\u0323 trong th\u01a1\u0300i kh\xf4\u0301n na\u0300y; n\xea\u0301u c\u01b0\u0301 ti\xea\u0301n ha\u0300nh thi\u0300 kh\xf4ng g\u0103\u0323p th\u01a1\u0300i x\xe2\u0301u; gi\u01b0\u0303 \u0111a\u0323o thi\u0300 kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e09: \u56f0\u4e8e\u77f3, \u64da\u4e8e\u84ba\u853e, \u5165\u4e8e\u5176\u5bae, \u4e0d\u898b\u5176\u59bb, \u51f6\uff0e\nL\u1ee5c tam: Kh\xf4\u0301n vu tha\u0323ch, c\u01b0\u0301 vu t\xe2\u0323t l\xea, nh\xe2\u0323p vu ki\u0300 cung, b\xe2\u0301t ki\xea\u0301n ki\u0300 th\xea, hung.\nD\u1ecbch: Ha\u0300o 3, \xe2m: nh\u01b0 ng\u01b0\u01a1\u0300i bi\u0323 kh\xf4\u0301n vi\u0300 \u0111a\u0301, ma\u0300 la\u0323i d\u01b0\u0323a va\u0300o c\xe2y t\xe2\u0323t l\xea, v\xf4 nha\u0300 thi\u0300 kh\xf4ng th\xe2\u0301y v\u01a1\u0323, x\xe2\u0301u.\n","\n\u4e5d\u56db: \u4f86\u5f90\u5f90, \u56f0\u4e8e\u91d1\u8eca, \u541d, \u6709\u7d42\uff0e\nC\u1eedu t\u01b0\u0301: Lai t\u01b0\u0300 t\u01b0\u0300, Kh\xf4\u0301n vu kim xa, l\xe2\u0323n, h\u01b0\u0303u chung.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng : (Ba\u0323n mi\u0300nh) la\u0323i ch\xe2\u0323m vi\u0300 bi\u0323 c\xf4\u0303 xe b\u0103\u0300ng kim khi\u0301 ch\u0103\u0323n (kh\xf4\u0301n) co\u0301 \u0111i\xea\u0300u \xe2n h\xe2\u0323n, nh\u01b0ng \u0111\u01b0\u01a1\u0323c tro\u0323n ve\u0323n v\xea\u0300 sau.\n","\n\u4e5d\u4e94: \u5293\u5216, \u56f0\u4e8e\u8d64\u7d31\uff0e\u4e43\u5f90\u6709\u8aaa, \u5229\u7528\u796d\u7940\uff0e\nC\u1eedu ngu\u0303: ti\u0323 nguy\xea\u0323t, kh\xf4\u0301n vu xi\u0301ch ph\xe2\u0301t,\nN\xe3i t\u01b0\u0300 h\u01b0\u0303u duy\xea\u0323t, l\u01a1\u0323i du\u0323ng t\xea\u0301 t\u01b0\u0323.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Bi\u0323 xe\u0309o mu\u0303i, c\u0103\u0301t ch\xe2n, kh\xf4\u0301n vi\u0300 ca\u0301i \u201cph\xe2\u0301t\u201d \u0111o\u0309; thu\u0309ng th\u0103\u0309ng se\u0303 vui, n\xean du\u0300ng lo\u0300ng chi\u0301 tha\u0300nh lu\u0301c cu\u0301ng t\xea\u0301 (ma\u0300 x\u01b0\u0309 va\u0300o th\u01a1\u0300i Kh\xf4\u0301n).\n","\n\u4e0a\u516d: \u56f0\u4e8e\u845b\u85df, \u4e8e\u81f2\u537c\uff0e\u66f0: \u52d5\u6094, \u6709\u6094, \u5f81\u5409\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Kh\xf4\u0301n vu ca\u0301t lu\u0303y, vu ni\xea\u0301t ng\xf4\u0323t.\nVi\u1ebft \u0111\xf4\u0323ng h\xf4\u0301i, h\u01b0\u0303u h\xf4\u0301i, chinh ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng ,\xe2m: Bi\u0323 kh\xf4\u0301n vi\u0300 d\xe2y s\u0103\u0301n d\xe2y leo, kh\xe2\u0323p kh\xea\u0303nh, g\xe2\u0323p gh\xea\u0300nh; t\u01b0\u0323 ho\u0309i r\u0103\u0300ng; hoa\u0323t \u0111\xf4\u0323ng thi\u0300 \xe2n h\xe2\u0323n ch\u0103ng? Bi\xea\u0301t suy nghi\u0303 nh\u01b0 v\xe2\u0323y thi\u0300 ha\u0300nh \u0111\xf4\u0323ng se\u0303 t\xf4\u0301t.\n")
if(c6&&r.b===1&&r.c===0&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa Th\u1ee7y V\u1ecb T\u1ebf",c5,r.b,r.c,r.d,r.e,r.f,"TI\u1ec2U NH\xc2N H\xc3M H\u1ea0I",a9,b0,i,l,q,p,c2,"",3,0,3,b9,"",r.r[18],"\n\u521d\u516d: \u6fe1\u5176\u5c3e, \u541d\uff0e\nS\u01a1 lu\u0323c: nhu ki\u0300 vi\u0303, l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 1, \xe2m: \u0111\xea\u0309 \u01b0\u01a1\u0301t ca\u0301i \u0111u\xf4i, \u0111a\u0301ng \xe2n h\xe2\u0323n.\n","\n\u4e5d\u4e8c: \u66f3\u5176\u8f2a, \u8c9e\u5409\uff0e\nC\u1eedu nhi\u0323: Du\xea\u0323 ki\u0300 lu\xe2n, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: ke\u0301o l\xea\u0301t ba\u0301nh xe, gi\u01b0\u0303 \u0111a\u0323o trung chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e09: \u672a\u6fdf, \u5f81\u51f6, \u5229\u6d89\u5927\u5ddd\uff0e\nL\u1ee5c tam: Vi\u0323 t\xea\u0301: chinh hung, l\u01a1\u0323i thi\xea\u0323p \u0111a\u0323i xuy\xean.\nD\u1ecbch: Ha\u0300o 3, \xe2m: ch\u01b0a tha\u0300nh \u0111\xe2u, n\xea\u0301u c\u01b0\u0301 ti\xea\u0301n ha\u0300nh thi\u0300 bi\u0323 hoa\u0323, v\u01b0\u01a1\u0323t qua s\xf4ng l\u01a1\u0301n thi\u0300 l\u01a1\u0323i.\n","\n\u4e5d\u56db: \u8c9e\u5409, \u6094\u4ea1\uff0e\u9707\u7528\u4f10\u9b3c\u65b9, \u4e09\u5e74. \u6709\u8cde\u4e8e\u5927\u570b\uff0e\nC\u1eedu t\u01b0\u0301: trinh ca\u0301t, h\xf4\u0301i vong. Ch\xe2\u0301n du\u0323ng pha\u0323t Qui\u0309 Ph\u01b0\u01a1ng, tam ni\xean. H\u01b0\u0303u th\u01b0\u01a1\u0309ng vu \u0111a\u0323i qu\xf4\u0301c.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4\u0301t, h\xf4\u0301i h\xe2\u0323n m\xe2\u0301t \u0111i. Ph\xe2\u0301n pha\u0301t (Ch\xe2\u0301n) tinh th\xe2\u0300n, c\xf4\u0309 vu\u0303 du\u0303ng khi ma\u0300 \u0111a\u0301nh n\u01b0\u01a1\u0301c qui\u0309 Ph\u01b0\u01a1ng, l\xe2u ba n\u0103m, nh\u01b0ng r\xf4\u0300i \u0111\u01b0\u01a1\u0323c n\u01b0\u01a1\u0301c l\u01a1\u0301n th\u01b0\u01a1\u0309ng cho.\n","\n\u516d\u4e94: \u8c9e,\u5409,\u65e0\u6094\uff0e\u541b\u5b50\u4e4b\u5149\u6709\u5b5a.\u5409\uff0e\nL\u1ee5c ngu\u0303: trinh, ca\u0301t, v\xf4 h\xf4\u0301i. Qu\xe2n t\u01b0\u0309 chi quang h\u01b0\u0303u phu, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Co\u0301 \u0111\u01b0\u0301c trung chi\u0301nh, t\xf4\u0301t, kh\xf4ng co\u0301 l\xf4\u0303i. \u0110\u01b0\u0301c v\u0103n minh cu\u0309a ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 do chi\u0301 tha\u0300nh ma\u0300 r\u01b0\u0323c r\u01a1\u0303, t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u6709\u5b5a\u4e8e\u98f2\u9152, \u65e0\u548e\uff0e\u6fe1\u5176\u9996, \u6709\u5b5a, \u5931\u662f\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0303u: H\u01b0\u0303u phu vu \xe2\u0309m t\u01b0\u0309u, v\xf4 c\u01b0\u0303u\nNhu ki\u0300 thu\u0309, h\u01b0\u0303u phu, th\xe2\u0301t thi\u0323.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: tin t\u01b0\u01a1\u0309ng ch\u01a1\u0300 \u0111\u01a1\u0323i nh\u01b0 thong tha\u0309 u\xf4\u0301ng r\u01b0\u01a1\u0323u ch\u01a1i thi\u0300 kh\xf4ng l\xf4\u0303i, n\xea\u0301u qua\u0301 t\u01b0\u0323 tin ma\u0300 chi\u0300m \u0111\u0103\u0301m trong r\u01b0\u01a1\u0323u che\u0300 (\u01b0\u01a1\u0301t ca\u0301i \u0111\xe2\u0300u) thi\u0300 la\u0300 b\xe2\u0323y.\n")
if(c6&&r.b===1&&r.c===0&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i Th\u1ee7y Gi\u1ea3i",c5,r.b,r.c,r.d,r.e,r.f,"NG\u0168 QUAN THO\xc1T N\u1ea0N",a9,b0,i,i,h,g,"Ph\u1ee5 T\xfd","",1,0,2,a5,"",r.r[25],"\n\u521d\u516d: \u65e0\u548e.\nS\u01a1 lu\u0323c: V\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, \xe2m: kh\xf4ng l\xf4\u0303i.\n","\n\u4e5d\u4e8c: \u7530\u7372\u4e09\u72d0, \u5f97\u9ec3\u77e2, \u8c9e, \u5409\uff0e\nC\u1eedu nhi\u0323: \u0110i\xea\u0300n hoa\u0323ch tam h\xf4\u0300, \u0111\u0103\u0301c hoa\u0300ng thi\u0309, trinh, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: \u0110i s\u0103n \u0111\u01b0\u01a1\u0323c ba con ca\u0301o, \u0111\u01b0\u01a1\u0323c mu\u0303i t\xean ma\u0300u va\u0300ng, gi\u01b0\u0303 \u0111a\u0323o chi\u0301nh thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e09: \u8ca0\u4e14\u4e58, \u81f4\u5bc7\u81f3\uff0e\u8c9e\u541d\uff0e\nL\u1ee5c tam: Phu\u0323 tha\u0309 th\u01b0\u0300a, tri\u0301 kh\xe2\u0301u chi\u0301; trinh l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 3, \xe2m: ke\u0309 mang \u0111\xf4\u0323i \u0111\xf4\u0300 v\xe2\u0323t ma\u0300 la\u0323i ng\xf4\u0300i xe la\u0300 xui bo\u0323n c\u01b0\u01a1\u0301p t\u01a1\u0301i, n\xea\u0301u c\u01b0\u0301 gi\u01b0\u0303 ca\u0301i tho\u0301i \u0111o\u0301 (trinh \u01a1\u0309 \u0111\xe2y nghi\u0303a kha\u0301c trinh \u01a1\u0309 ha\u0300o tr\xean ) thi\u0300 pha\u0309i h\xf4\u0301i h\xe2\u0323n.\n","\n\u4e5d\u56db: \u89e3\u800c\u62c7, \u670b\u81f3\u65af\u5b5a\uff0e\nC\u1eedu t\u01b0\u0301: Gia\u0309i nhi m\xe2\u0303u, b\u0103\u0300ng chi\u0301 t\u01b0 phu.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: Bo\u0309 ngo\u0301n ch\xe2n ca\u0301i cu\u0309a anh \u0111i (ch\u01b0\u0303 nhi \u01a1\u0309 \u0111\xe2y la\u0300 \u0111a\u0323i danh t\u01b0\u0300) thi\u0300 ba\u0323n (t\xf4\u0301t) m\u01a1\u0301i t\u01a1\u0301i va\u0300 tin c\xe2\u0323y anh.\n","\n\u516d\u4e94: \u541b\u5b50\u7dad\u6709\u89e3, \u5409\uff0e\u6709\u5b5a\u4e8e\u5c0f\u4eba\uff0e\nL\u1ee5c ngu\u0303: Qu\xe2n t\u01b0\u0309 duy h\u01b0\u0303u gia\u0309i, ca\u0301t; h\u01b0\u0303u phu vu ti\xea\u0309u nh\xe2n\nD\u1ecbch: Ha\u0300o 5, \xe2m: ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 pha\u0309i gia\u0309i ta\u0301n bo\u0323n ti\xea\u0309u nh\xe2n \u0111i thi\u0300 m\u01a1\u0301i t\xf4\u0301t; c\u01b0\u0301 xem bo\u0323n ti\xea\u0309u nh\xe2n co\u0301 lui \u0111i kh\xf4ng thi\u0300 m\u01a1\u0301i bi\xea\u0301t ch\u0103\u0301c \u0111\u01b0\u01a1\u0323c mi\u0300nh co\u0301 qu\xe2n t\u01b0\u0309 hay kh\xf4ng.\n","\n\u4e0a\u516d: \u516c\u7528\u5c04\u96bc\u4e8e\u9ad8\u5889\u4e4b\u4e0a\uff0e\u7372\u4e4b, \u65e0\u4e0d\u5229\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: C\xf4ng du\u0323ng xa\u0323 chu\xe2\u0309n vu cao dung chi th\u01b0\u01a1\u0323ng. Hoa\u0323ch chi, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: M\xf4\u0323t vi\u0323 c\xf4ng nh\u0103\u0301m b\u0103\u0301n con chim chu\xe2\u0309n \u01a1\u0309 tr\xean b\u01b0\u0301c t\u01b0\u01a1\u0300ng cao. B\u0103\u0301n \u0111\u01b0\u01a1\u0323c, kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n")
if(c6&&r.b===1&&r.c===0&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong Th\u1ee7y Ho\xe1n",c5,r.b,r.c,r.d,r.e,r.f,"C\xc1CH H\xc0 V\u1eccNG KIM",a9,b0,i,q,p,o,c2,"T\xe0i D\u1eadu",3,4,5,b9,"",r.r[32],"\n\u521d\u516d: \u7528\u62ef, \u99ac\u58ef, \u5409\nS\u01a1 lu\u0323c: Du\u0323ng ch\u01b0\u0301ng, ma\u0303 tra\u0301ng, ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Du\u0300ng con ng\u01b0\u0323a ma\u0323nh \u0111\xea\u0309 c\u01b0\u0301u v\u01a1\u0301t, t\xf4\u0301t.\n","\n\u4e5d\u4e8c: \u6e19,\u5954\u5176\u673a, \u6094\u4ea1\uff0e\nC\u1eedu nhi\u0323: Hoa\u0301n, b\xf4n ki\u0300 ki\u0309, h\xf4\u0301i vong.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: Lu\u0301c ly ta\u0301n, n\xean \u0111\u01b0\u0323a va\u0300o ha\u0300o 1 la\u0300m gh\xea\u0301 ng\xf4\u0300i thi\u0300 h\xf4\u0301i h\xe2\u0323n m\xe2\u0301t \u0111i.\n","\n\u516d\u4e09: \u6e19\u5176\u8eac, \u65e0\u6094\uff0e\nL\u1ee5c tam: Hoa\u0301n ki\u0300 cung, v\xf4 h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o 3, \xe2m: \u0111a\u0301nh tan lo\u0300ng ri\xeang t\xe2y cu\u0309a mi\u0300nh \u0111i thi\u0300 kh\xf4ng h\xf4\u0301i h\xe2\u0323n.\n","\n\u516d\u56db: \u6e19\u5176\u7fa4, \u5143\u5409\uff0e\u6e19\u6709\u4e18, \u532a\u5937\u6240\u601d\uff0e\nL\u1ee5c t\u01b0\u0301: hoa\u0301n ki\u0300 qu\xe2\u0300n, nguy\xean ca\u0301t. Hoa\u0301n ki\u0300 kh\xe2u, phi\u0309 di s\u01a1\u0309 t\u01b0.\nD\u1ecbch: Ha\u0300o 4 \xe2m: Gia\u0309i ta\u0301n be\u0300 pha\u0301i cu\u0309a mi\u0300nh \u0111i, r\xe2\u0301t t\xf4\u0301t. Vi\u0300 nh\u01b0 v\xe2\u0323y la\u0300 gia\u0309i ta\u0301n ca\u0301i nho\u0309 \u0111\xea\u0309 t\xe2\u0323p h\u01a1\u0323p ca\u0301i l\u01a1\u0301n la\u0323i tha\u0300nh go\u0300 \u0111\xf4\u0301ng; \u0111i\xea\u0300u \u0111o\u0301 ng\u01b0\u01a1\u0300i th\u01b0\u01a1\u0300ng kh\xf4ng th\xea\u0309 nghi\u0303 t\u01a1\u0301i \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d\u4e94: \u6e19\u6c57\u5176\u5927\u865f, \u6e19\u738b\u5c45, \u65e0\u548e\uff0e\nC\u1eedu ngu\u0303: Hoa\u0301n ha\u0303n ki\u0300 \u0111a\u0323i hi\xea\u0323u, hoa\u0301n v\u01b0\u01a1ng c\u01b0,v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: Ban b\xf4\u0301 hi\xea\u0323u l\xea\u0323nh l\u01a1\u0301n kh\u0103\u0301p n\u01b0\u01a1\u0301c nh\u01b0 m\xf4\u0300 h\xf4i pha\u0301t ra \u01a1\u0309 kh\u0103\u0301p th\xe2n th\xea\u0309, pha\u0301t h\xea\u0301t kho l\xe2\u0303m cu\u0309a vua \u0111\xea\u0309 chu c\xe2\u0301p cho d\xe2n, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e0a\u4e5d: \u6e19\u5176\u8840\u53bb, \u9016\u51fa, \u65e0\u548e\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: hoa\u0301n ky\u0300 huy\xea\u0301t kh\u01b0\u0309, \u0111i\u0323ch xu\xe2\u0301t, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: Tan (tr\u01b0\u0300) \u0111\u01b0\u01a1\u0323c ma\u0301u )v\xea\u0301t th\u01b0\u01a1ng cu\u0303), thoa\u0301t kho\u0309i kinh s\u01a1\u0323 (ch\u01b0\u0303 [\u9016 ] \u01a1\u0309 \u0111\xe2y n\xean \u0111\xf4\u0309i la\u0300m ch\u01b0\u0303 di\u0323ch [\u60d5] la\u0300 kinh s\u01a1\u0323), kh\xf4ng co\u0301 l\xf4\u0303i.\n")
if(c6&&r.b===1&&r.c===0&&r.d===0&&r.e===1&&r.f===0)c4=A.ct("B\xe1t Thu\u1ea7n Kh\u1ea3m",c5,r.b,r.c,r.d,r.e,r.f,"TH\u1ee6Y \u0110\u1ec2 LAO NGUY\u1ec6T",a9,b0,i,h,g,a7,"","",0,0,6,b7,j,r.r[47],"\n\u521d\u516d: \u7fd2\u574e, \u5165\u4e8e\u574e\u7a9e, \u51f6\uff0e\nS\u01a1 lu\u0323c: T\xe2\u0323p kha\u0309m, nh\xe2\u0323p vu kha\u0309m n\u0103m ( co\u0301 ng\u01b0\u01a1\u0300i \u0111o\u0323c la\u0300 \u0111a\u0323m, ha\u0323m, l\u0103m), hung.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Hai l\xe2\u0300n hi\xea\u0309m, su\u0323p va\u0300o h\xf4\u0301 s\xe2u, x\xe2\u0301u.\n","\n\u4e5d\u4e8c: \u574e\u6709\u96aa, \u6c42\u5c0f\u5f97\uff0e\nC\u1eedu nhi\u0323: kha\u0309m h\u01b0\u0303u hi\xea\u0309m, c\xe2\u0300u ti\xea\u0309u \u0111\u0103\u0301c.\nD\u1ecbch: Ha\u0300o 2, d\u01b0\u01a1ng: \u01a1\u0309 ch\xf4\u0303 n\u01b0\u01a1\u0301c (hi\xea\u0309m) la\u0323i co\u0301 hi\xea\u0309m, mong la\u0300m \u0111\u01b0\u01a1\u0323c vi\xea\u0323c nho\u0309 th\xf4i.\n","\n\u516d\u4e09: \u4f86\u4e4b\u574e\u574e, \u96aa\u4e14\u6795, \u5165\u4e8e\u574e\u7a9e, \u52ff\u7528.\nL\u1ee5c tam: Lai chi kha\u0309m kha\u0309m, hi\xea\u0309m tha\u0309 ch\xe2\u0309m, nh\xe2\u0323p vu kha\u0309m n\u0103m, v\xe2\u0323t du\u0323ng.\nD\u1ecbch: Ha\u0300o 3, \xe2m : t\u01a1\u0301i lui (ch\u01b0\u0309 chi \u01a1\u0309 \u0111\xe2y nghi\u0303a la\u0300 \u0111i) \u0111\xea\u0300u bi\u0323 ha\u0303m, tr\u01b0\u01a1\u0301c m\u0103\u0323t la\u0300 hi\xea\u0309m ma\u0300 sau l\u01b0ng la\u0323i k\xea (d\u01b0\u0323a) va\u0300o hi\xea\u0309m, chi\u0309 ca\u0300ng su\u0323p va\u0300o ch\xf4\u0303 s\xe2u h\u01a1n th\xf4i, ch\u01a1\u0301 du\u0300ng (ng\u01b0\u01a1\u0300i \u01a1\u0309 hoa\u0300n ca\u0309nh ha\u0300o 3 na\u0300y, kh\xf4ng \u0111\u01b0\u01a1\u0323c vi\xea\u0323c gi\u0300 \u0111\xe2u).\n","\n\u516d\u56db: \u6a3d\u9152\u7c0b, \u8cb3 \u7528\u7f36, \u7d0d\u7d04\u81ea\u7256, \u7d42\u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: T\xf4n t\u01b0\u0309u qui\u0303, nhi\u0323 du\u0323ng ph\xe2\u0303u, na\u0323p \u01b0\u01a1\u0301c t\u01b0\u0323 du\u0303, chung v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Nh\u01b0 th\xea\u0309 chi\u0309 d\xe2ng m\xf4\u0323t che\u0301n r\u01b0\u01a1\u0323u, m\xf4\u0323t qui\u0303 th\u01b0\u0301c \u0103n, th\xeam m\xf4\u0323t ca\u0301i vo\u0300 d\u01b0\u0323ng va\u0300i th\u01b0\u0301c kha\u0301c n\u01b0\u0303a (kh\xf4ng c\xe2\u0300n nhi\xea\u0300u, h\xea\u0303 chi\u0301 tha\u0300nh la\u0300 \u0111\u01b0\u01a1\u0323c); (co\u0301 th\xea\u0309 tu\u0300y c\u01a1 \u01b0\u0301ng bi\xea\u0301n) d\u01b0\u0301t kh\xea\u0301 \u01b0\u01a1\u0301c qua c\u01b0\u0309a s\xf4\u0309 (ch\u01b0\u0301 kh\xf4ng \u0111\u01b0a qua c\u01b0\u0309a chi\u0301nh), nh\u01b0 v\xe2\u0323y kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e94: \u574e\u4e0d\u76c8, \u7957\u65e2\u5e73, \u65e0\u548e.\nC\u1eedu ngu\u0303: Kha\u0309m b\xe2\u0301t doanh, chi\u0309 ki\u0300 bi\u0300nh, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 5, \xe2m: N\u01b0\u01a1\u0301c (hi\xea\u0309m) ch\u01b0a \u0111\xe2\u0300y, nh\u01b0ng \u0111\xea\u0301n lu\u0301c n\u01b0\u01a1\u0301c \u0111\xe2\u0300y r\xf4\u0300i, l\u0103\u0323ng r\xf4\u0300i, thi\u0300 se\u0303 kho\u0309i hi\xea\u0309m, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e0a\u516d: \u4fc2\u7528\u9ef4\u7e86, \u5bd8\u4e8e\u53e2\u68d8, \u4e09\u6b72\u4e0d\u5f97, \u51f6\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: H\xea\u0323 du\u0323ng huy m\u0103\u0323c, tri\u0301 vu t\u01b0\u0300ng c\u01b0\u0301c, tam tu\xea\u0301 b\xe2\u0301t \u0111\u0103\u0301c, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: \u0111a\u0303 tro\u0301i b\u0103\u0300ng d\xe2y th\u01b0\u0300ng to, la\u0323i \u0111\u0103\u0323t va\u0300o bu\u0323i gai, ba n\u0103m kh\xf4ng \u0111\u01b0\u01a1\u0323c ra , x\xe2\u0301u.\n")
if(c6&&r.b===1&&r.c===0&&r.d===0&&r.e===0&&r.f===1)c4=A.ct("S\u01a1n Th\u1ee7y M\xf4ng",c5,r.b,r.c,r.d,r.e,r.f,"TI\u1ec2U QU\u1ef6 TH\xc2U TI\u1ec0N",a9,b0,i,g,a7,a9,"T\xe0i D\u1eadu","",4,0,4,b9,"",r.r[54],"\n\u521d \u516d: \u767c \u8499, \u5229 \u7528 \u5211 \u4eba, \u7528 \u8aaa \u684e \u688f, \u4ee5 \u5f80 \u541d\uff0e\nS\u01a1 lu\u0323c: pha\u0301t m\xf4ng, l\u01a1\u0323i du\u0323ng hi\u0300nh nh\xe2n, Du\u0323ng thoa\u0301t ch\xe2\u0301t c\xf4\u0301c, di\u0303 va\u0303ng l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 1, \xe2m: m\u01a1\u0309 mang ca\u0301i t\xf4\u0301i t\u0103m (cho ha\u0323ng ng\u01b0\u01a1\u0300i h\xf4n a\u0301m) thi\u0300 n\xean du\u0300ng hi\u0300nh pha\u0323t c\xf4\u0301t cho ho\u0323 thoa\u0301t kho\u0309i g\xf4ng cu\u0300m, nh\u01b0ng \u0111\u01b0\u0300ng \u0111i qua\u0301 m\u01b0\u0301c se\u0303 h\xf4\u0301i ti\xea\u0301c.\n","\n \u4e5d \u4e8c \uff0e \u5305 \u8499 \u5409 \uff0e \u7d0d \u5a66 \u5409 \uff0e \u5b50 \u514b \u5bb6 \uff0e\nC\u1eedu nhi\u0323: Bao m\xf4ng ca\u0301t, na\u0323p phu\u0323 ca\u0301t, t\u01b0\u0309 kh\u0103\u0301c gia.\nD\u1ecbch: Ha\u0300o, d\u01b0\u01a1ng: Bao dung ke\u0309 m\u01a1\u0300 t\xf4\u0301i, dung na\u0323p ha\u0323ng ng\u01b0\u01a1\u0300i nhu a\u0301m nh\u01b0 \u0111a\u0300n ba\u0300, t\xf4\u0301t; (\u01a1\u0309 ng\xf4i d\u01b0\u01a1\u0301i ma\u0300 ga\u0301nh va\u0301c vi\xea\u0323c tr\xean) nh\u01b0 ng\u01b0\u01a1\u0300i con cai qua\u0309n \u0111\u01b0\u01a1\u0323c vi\xea\u0323c nha\u0300.\n","\n\u516d \u4e09: \u52ff \u7528 \u53d6 \u5973 \u898b \u91d1 \u592b \uff0e\n\u4e0d \u6709 \u8eac, \u65e0 \u6538 \u5229\uff0e\nL\u1ee5c tam: V\u1eadt d\u1ee5ng th\u1ee7 n\u1eef ki\u1ebfn kim phu.\nB\u1ea5t h\u1eefu cung, v\xf4 du l\u1ee3i.\nD\u1ecbch : h\xe0o 3, \xe2m: \u0111\u1eebng d\xf9ng h\u1ea1ng con g\xe1i th\u1ea5y ai c\xf3 v\xe0ng b\u1ea1c l\xe0 (theo ngay) kh\xf4ng bi\u1ebft th\xe2n m\xecnh n\u1eefa; ch\u1eb3ng c\xf3 l\u1ee3i g\xec c\u1ea3.\n","\n\u516d \u56db : \u56f0, \u8499, \u541d \uff0e\nL\u1ee5c t\u1ee9 : Kh\u1ed1n, m\xf4ng, l\u1eadn.\nD\u1ecbch: H\xe0o 4, \xe2m: B\u1ecb kh\u1ed1n trong v\xf2ng h\xf4n \xe1m, h\u1ed1i ti\u1ebfc.\n","\n\u516d \u4e94: \u7ae5 \u8499 \u5409 \uff0e\nL\u1ee5c ngu\u0303: \u0110\xf4\u0300ng m\xf4ng ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: Be\u0301 con, ch\u01b0a bi\xea\u0301t gi\u0300 (nh\u01b0ng d\xea\u0303 da\u0323y), t\xf4\u0301t.\n","\n\u4e0a \u4e5d: \u64ca \u8499 \u4e0d \u5229 \u70ba \u5bc7 , \u5229 \u79a6 \u5bc7.\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Ki\u0301ch m\xf4ng b\xe2\u0301t l\u01a1\u0323i vi kh\xe2\u0301u, l\u01a1\u0323i ng\u01b0\u0323 kh\xe2\u0301u.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng : phe\u0301p tr\u01b0\u0300 ca\u0301i ngu t\xf4\u0301i ma\u0300 nghi\xeam kh\u0103\u0301c qua\u0301 thi\u0300 ke\u0309 mi\u0300nh da\u0323y d\xf4\u0303 se\u0303 ph\xe2\u0303n u\xe2\u0301t, co\u0301 th\xea\u0309 tha\u0300nh gi\u0103\u0323c, nh\u01b0 v\xe2\u0323y kh\xf4ng co\u0301 l\u01a1\u0323i, ng\u0103n ng\u01b0\u0300a gi\u0103\u0323c \u01a1\u0309 ngoa\u0300i (t\u01b0\u0301c nh\u01b0\u0303ng v\xe2\u0323t du\u0323c quy\xea\u0301n ru\u0303 ke\u0309 \u0111o\u0301) thi\u0300 co\u0301 l\u01a1\u0323i.\n")
if(c6&&r.b===0&&r.c===1&&r.d===0&&r.e===0&&r.f===0)c4=A.ct("\u0110\u1ecba S\u01a1n Khi\xeam",c5,r.b,r.c,r.d,r.e,r.f,"NH\u1eca NH\xc2N PH\xc2N KIM",b0,i,h,n,m,l,c3,"",2,0,5,a3,"",r.r[62],"\n\u521d\u516d: \u8b19\u8b19\u541b\u5b50, \u7528\u6d89\u5927\u5ddd, \u5409\uff0e\nS\u01a1 lu\u0323c: khi\xeam khi\xeam qu\xe2n t\u01b0\u0309, du\u0323ng thi\xea\u0323p \u0111a\u0323i xuy\xean, ca\u0301t.\nD\u1ecbch: Ha\u0300o 1, \xe2m \u2013 Nhu\u0301n nh\u01b0\u01a1\u0300ng, nhu\u0301n nh\u01b0\u01a1\u0300ng, ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 du\u0300ng \u0111\u01b0\u0301c \xe2\u0301y \u0111\xea\u0309 qua s\xf4ng l\u01a1\u0301n thi\u0300 t\xf4\u0301t.\n","\n\u516d\u4e8c: \u9cf4\u8b19, \u8c9e\u5409\uff0e\nL\u1ee5c nhi\u0323: Minh khi\xeam, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Ti\xea\u0301ng t\u0103m l\u01b0\u0300ng l\xe2\u0303y v\xea\u0300 \u0111\u01b0\u0301c khi\xeam, n\xea\u0301u chi\u0301nh \u0111a\u0301ng thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u52de\u8b19, \u541b\u5b50 \u6709\u7d42, \u5409\uff0e\nC\u1eedu tam: Lao khi\xeam, qu\xe2n t\u01b0\u0309 h\u01b0\u0303u chung, ca\u0301t.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : Kho\u0301 nho\u0323c (co\u0301 c\xf4ng lao) ma\u0300 nhu\u0301n nh\u01b0\u01a1\u0300ng, ng\u01b0\u01a1\u0300i qu\xe2n t\u01b0\u0309 gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c tro\u0323n ve\u0323n, t\xf4\u0301t.\n","\n\u516d\u56db: \u65e0\u4e0d\u5229, \u649d\u8b19\uff0e\nL\u1ee5c t\u01b0\u0301: v\xf4 b\xe2\u0301t l\u01a1\u0323i, huy khi\xeam.\nD\u1ecbch: Ha\u0300o 4, \xe2m: Pha\u0301t huy s\u01b0\u0323 nhu\u0301n nh\u01b0\u01a1\u0300ng thi\u0300 kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n","\n\u516d\u4e94: \u4e0d\u5bcc\u4ee5\u5176\u9130, \u5229\u7528\u4fb5\u4f10, \u65e0\u4e0d\u5229\uff0e\nL\u1ee5c ngu\u0303: B\xe2\u0301t phu\u0301 di\u0303 ky\u0300 l\xe2n, l\u01a1\u0323i du\u0323ng x\xe2m pha\u0323t, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o 5, \xe2m: ch\u0103\u0309ng c\xe2\u0300n gia\u0300u (co\u0301 th\xea\u0301 l\u01b0\u0323c) ma\u0300 th\xe2u phu\u0323c \u0111\u01b0\u0323\u01a1c la\u0301ng gi\xea\u0300ng (\u0111\u01b0\u01a1\u0323c nhi\xea\u0300u ng\u01b0\u01a1\u0300i theo); nh\u01b0ng pha\u0309i co\u0301 chu\u0301t uy, chinh pha\u0323t ke\u0309 na\u0300o ch\u01b0a phu\u0323c mi\u0300nh thi\u0300 m\u01a1\u0301i kh\xf4ng gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n","\n\u4e0a\u516d: \u9cf4\u8b19, \u5229\u7528\u884c\u5e2b, \u5f81\u9091\u570b\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Minh khi\xeam, l\u01a1\u0323i du\u0323ng ha\u0300nh s\u01b0, chi\u0301nh \xe2\u0301p qu\xf4\u0301c.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: Ti\xea\u0301ng t\u0103m l\u01b0\u0300ng l\xe2\u0303y v\xea\u0300 \u0111\u01b0\u0301c Khi\xeam, \u0111\u01b0\u01a1\u0323c nhi\xea\u0300u ng\u01b0\u01a1\u0300i theo co\u0301 th\xea\u0309 l\u01a1\u0323i du\u0323ng \u0111i\xea\u0300u \u0111o\u0301 ma\u0300 ra qu\xe2n, nh\u01b0ng cu\u0303ng chi\u0309 tri\u0323 \u0111\u01b0\u01a1\u0323c nh\u01b0\u0303ng ke\u0309 trong \xe2\u0301p cu\u0309a mi\u0300nh kh\xf4ng phu\u0323c mi\u0300nh th\xf4i.\n")
if(c6&&r.b===0&&r.c===1&&r.d===1&&r.e===1&&r.f===1)c4=A.ct("Thi\xean S\u01a1n \u0110\u1ed9n",c5,r.b,r.c,r.d,r.e,r.f,"N\xd9NG V\xc2N T\u1ebe NH\u1eacT",b0,i,h,i,h,g,f,"T\xe0i D\u1ea7n",1,2,2,e,"",r.r[5],"\n\u521d\u516d: \u906f\u5c3e, \u53b2, \u52ff\u7528\u6709\u6538\u5f80\uff0e\nS\u01a1 lu\u0323c: \u0111\xf4\u0323n vi\u0303, l\xea\u0323, v\xe2\u0323t du\u0323ng h\u01b0\u0303u du va\u0303ng.\nD\u1ecbch: Ha\u0300 1, \xe2m: Tr\xf4\u0301n sau cu\u0300ng, nh\u01b0 ca\u0301i \u0111u\xf4i, nguy \u0111\xe2\u0301y, \u0111\u01b0\u0300ng la\u0300m gi\u0300 ca\u0309.\n","\n\u516d\u4e8c: \u57f7\u4e4b\u7528\u9ec3\u725b\u4e4b\u9769, \u83ab\u4e4b\u52dd\u8aaa\uff0e\nL\u1ee5c nhi\u0323: ch\xe2\u0301p chi du\u0323ng hoa\u0300ng ng\u01b0u chi ca\u0301ch, ma\u0323c chi th\u0103ng thoa\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Hai b\xean (ha\u0300o 5 va\u0300 ha\u0300o 2) kh\u0103ng khi\u0301t (b\xea\u0300n ch\u0103\u0323t) v\u01a1\u0301i nhau nh\u01b0 bu\xf4\u0323c va\u0300o nhau b\u0103\u0300ng da bo\u0300 va\u0300ng, kh\xf4ng th\xea\u0309 na\u0300o c\u01a1\u0309i \u0111\u01b0\u01a1\u0323c.\n","\n\u4e5d\u4e09: \u4fc2\u906f, \u6709\u75be\u53b2, \u755c\u81e3\u59be, \u5409\uff0e\nC\u1eedu tam: H\xea\u0323 \u0111\xf4\u0323n, h\u01b0\u0303u t\xe2\u0323t l\xea\u0323, su\u0301c th\xe2\u0300n thi\xea\u0301p, ca\u0301t.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng, lu\u0301c pha\u0309i tr\xf4\u0301n ma\u0300 bi\u0323n ri\u0323n t\u01b0 ti\u0300nh thi\u0300 nguy; nh\u01b0ng nu\xf4i ke\u0309 t\xf4i t\u01a1\u0301 trai ga\u0301i thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u56db: \u597d\u906f, \u541b\u5b50\u5409, \u5c0f\u4eba\u5426\uff0e\nC\u1eedu t\u01b0\u0301: Hi\xea\u0301u \u0111\xf4\u0323n, qu\xe2n t\u01b0\u0309 ca\u0301t, ti\xea\u0309u nh\xe2n phu\u0309.\nD\u1ecbch: Ha\u0300o 4 d\u01b0\u01a1ng: Co\u0301 h\xea\u0323 lu\u0323y v\u01a1\u0301i ng\u01b0\u01a1\u0300i, nh\u01b0ng tr\xf4\u0301n \u0111\u01b0\u01a1\u0323c, qu\xe2n t\u01b0\u0309 thi\u0300 t\xf4\u0301t, ti\xea\u0309u nh\xe2n thi\u0300 kh\xf4ng.\n","\n\u4e5d\u4e94: \u5609\u906f, \u8c9e\u5409\uff0e\nC\u1eedu ngu\u0303: gia \u0111\xf4\u0323n, trinh ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng, tr\xf4\u0301n ma\u0300 theo \u0111i\xea\u0300u chi\u0301nh cho n\xean t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u80a5\u906f, \u65e0\u4e0d\u5229\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: Phi \u0111\xf4\u0323n, v\xf4 b\xe2\u0301t l\u01a1\u0323i.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: tr\xf4\u0301n ma\u0300 ung dung, \u0111a\u0300ng hoa\u0300ng, kh\xf4ng co\u0301 gi\u0300 la\u0300 kh\xf4ng l\u01a1\u0323i.\n")
if(c6&&r.b===0&&r.c===1&&r.d===1&&r.e===1&&r.f===0)c4=A.ct("Tr\u1ea1ch S\u01a1n H\xe0m",c5,r.b,r.c,r.d,r.e,r.f,"MANH NHA XU\u1ea4T TH\u1ed4",b0,i,h,m,l,q,c3,"",2,0,3,a3,"",r.r[12],"\n\u521d\u516d: \u54b8\u5176\u62c7\uff0e\nS\u01a1 lu\u0323c: Ha\u0300m ki\u0300 m\xe2\u0303u.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Nh\u01b0 ca\u0309m ngo\u0301n ch\xe2n ca\u0301i.\n","\n\u516d\u4e8c: \u54b8\u5176\u8153, \u51f6; \u5c45\u5409\uff0e\nL\u1ee5c nhi\u0323: Ha\u0300m ki\u0300 phi\u0300, hung; c\u01b0 ca\u0301t.\nD\u1ecbch: Ha\u0300o 2, \xe2m: Ca\u0309m \u0111\u01b0\u01a1\u0323c b\u0103\u0301p ch\xe2n, x\xe2\u0301u; \u01a1\u0309 y\xean thi\u0300 t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u54b8\u5176\u80a1, \u57f7\u5176\u96a8, \u5f80\u541d\uff0e\nC\u1eedu tam: Ha\u0300m ki\u0300 c\xf4\u0309, ch\xe2\u0301p ki\u0300 tu\u0300y, va\u0303ng l\xe2\u0323n.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng : ca\u0309m \u0111\u01b0\u01a1\u0323c t\u01a1\u0301i \u0111u\u0300i, chi\u0309 mu\xf4\u0301n theo ng\u01b0\u01a1\u0300i, c\u01b0\u0301 nh\u01b0 v\xe2\u0323y ma\u0300 ti\u0301\xea\u0301n thi\u0300 x\xe2\u0301u.\n","\n\u4e5d\u56db: \u8c9e\u5409\u6094\u4ea1; \u61a7\u61a7\u5f80\u4f86, \u670b\u5f9e\u723e\u601d\uff0e\nC\u1eedu t\u01b0\u0301: Trinh ca\u0301t h\xf4\u0301i vong; \u0111\xf4\u0300ng \u0111\xf4\u0300ng va\u0303ng lai, b\u0103\u0300ng to\u0300ng nhi\u0303 t\u01b0.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: h\xea\u0303 chi\u0301nh \u0111a\u0301ng thi\u0300 t\xf4\u0301t, ma\u0300 m\xe2\u0301t h\xea\u0301t nh\u01b0\u0303ng \u0111i\xea\u0300u \u0111a\u0301ng \u0103n n\u0103n. Nh\u01b0\u01a1\u0323c b\u0103\u0300ng n\xea\u0301u l\u0103ng x\u0103ng ti\u0301nh toa\u0301n co\u0301 qua co\u0301 la\u0323i v\u01a1\u0301i nhau thi\u0300 nh\u01b0\u0303ng ng\u01b0\u01a1\u0300i qua la\u0323i v\u01a1\u0301i anh chi\u0309 la\u0300 nh\u01b0\u0303ng ng\u01b0\u01a1\u0300i anh nghi\u0303 t\u01a1\u0301i ma\u0300 th\xf4i (y\u0301 no\u0301i: s\xf4\u0301 ba\u0323n kh\xf4ng \u0111\xf4ng, \u0111oa\u0300n th\xea\u0309 kh\xf4ng l\u01a1\u0301n).\n","\n\u4e5d\u4e94: \u54b8\u5176\u8122, \u65e0\u6094\uff0e\nC\u1eedu ngu\u0303: Ca\u0309m ki\u0300 m\xf4\u0303i, v\xf4 h\xf4\u0301i.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng : Ca\u0309m t\u01a1\u0301i b\u0103\u0301p thi\u0323t \u01a1\u0309 tr\xean l\u01b0ng, kh\xf4ng h\xf4\u0301i h\xe2\u0323n.\n","\n\u4e0a\u516d: \u54b8\u5176\u8f14, \u9830, \u820c\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: Ha\u0300m ki\u0300 phu\u0323, gia\u0301p, thi\xea\u0323t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: Ca\u0309m ng\u01b0\u01a1\u0300i b\u0103\u0300ng me\u0301p, ma\u0301, l\u01b0\u01a1\u0303i.\n")
if(c6&&r.b===0&&r.c===1&&r.d===1&&r.e===0&&r.f===1)c4=A.ct("H\u1ecfa S\u01a1n L\u1eef",c5,r.b,r.c,r.d,r.e,r.f,"T\xdaC \u0110I\u1ec2U PH\u1ea6N S\xc0O",b0,i,h,l,q,p,"Ph\u1ee5 M\xe3o",c2,1,3,1,b9,d,r.r[19],"\n\u521d\u516d: \u65c5\u7463\u7463, \u65af\u5176\u6240\u53d6\u707d\uff0e\nS\u01a1 lu\u0323c: L\u01b0\u0303 toa\u0309 toa\u0309, t\u01b0 ki\u0300 s\u01a1\u0309 thu\u0309 tai.\nD\u1ecbch: Ha\u0300o 1, \xe2m: \u01a0\u0309 \u0111\xe2\u0323u ma\u0300 t\u01b0 ca\u0301ch nho\u0309 nhen, t\u0103\u0309n m\u0103\u0309n t\u01b0\u0301c la\u0300 t\u01b0\u0323 chu\xf4\u0301c l\xe2\u0301y hoa\u0323.\n","\n\u516d\u4e8c: \u65c5\u5373\u6b21, \u61f7\u5176\u8cc7, \u5f97\u7ae5\u50d5, \u8c9e\uff0e\nL\u1ee5c nhi\u0323: L\u01b0\u0303 t\u01b0\u0301c th\u01b0\u0301, hoa\u0300i ki\u0300 t\u01b0, \u0111\u0103\u0301c \u0111\xf4\u0300ng b\xf4\u0323c, trinh.\nD\u1ecbch: Ha\u0300o 2, \xe2m: \u01a0\u0309 \u0111\xe2\u0301t kha\u0301ch, \u0111\u01b0\u01a1\u0323c ch\xf4\u0303 tro\u0323n an la\u0300nh, gi\u01b0\u0303 \u0111\u01b0\u01a1\u0323c ti\xea\u0300n ba\u0323c, la\u0323i co\u0301 \u0111\xe2\u0300y t\u01a1\u0301 ti\u0301n c\xe2\u0309n.\n","\n\u4e5d\u4e09: \u65c5, \u711a\u5176\u6b21, \u55aa\u5176\u7ae5\u50d5, \u8c9e, \u53b2\uff0e\nC\u1eedu tam: L\u01b0\u0303, ph\xe2\u0300n ki\u0300 th\u01b0\u0301, ta\u0301ng ki\u0300 \u0111\xf4\u0300ng b\xf4\u0323c, trinh, l\xea\u0323.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: \u01a0\u0309 \u0111\xe2\u0301t kha\u0301ch, ma\u0300 (t\u01b0\u0323 mi\u0300nh) \u0111\xf4\u0301t ch\xf4\u0303 tro\u0323, m\xe2\u0301t \u0111\xe2\u0300y t\u01a1\u0301, du\u0300 chi\u0301nh \u0111a\u0301ng cu\u0303ng nguy.\n","\n\u4e5d\u56db: \u65c5\u4e8e\u8655, \u5f97\u5176\u8cc7\u65a7, \u6211\u5fc3\u4e0d\u5feb\uff0e\nC\u1eedu t\u01b0\u0301: L\u01b0\u0303 vu x\u01b0\u0309, \u0111\u0103\u0301c ki\u0300 t\u01b0 phu\u0309, nga\u0303 t\xe2m b\xe2\u0301t khoa\u0301i.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: t\u01a1\u0301i \u0111\xe2\u0301t kha\u0301ch, \u0111\u01b0\u01a1\u0323c ch\xf4\u0303 \u01a1\u0309 ta\u0323m, co\u0301 ti\xea\u0300n cu\u0309a va\u0300 \u0111\xf4\u0300 h\xf4\u0323 th\xe2n (t\u01b0\u01a1\u0323ng tr\u01b0ng b\u0103\u0300ng ca\u0301i bu\u0301a), nh\u01b0ng trong lo\u0300ng kh\xf4ng vui.\n","\n\u516d\u4e94: \u5c04\u96c9, \u4e00\u77e2\u4ea1, \u7d42\u4ee5\u8b7d\u547d\uff0e\nL\u1ee5c ngu\u0303: Xa\u0323 tri\u0303, nh\xe2\u0301t thi\u0309 vong, chung di\u0303 d\u01b0\u0323 m\xea\u0323nh.\nD\u1ecbch : Ha\u0300o 5, \xe2m : B\u0103\u0301n con tri\u0303, m\xe2\u0301t m\xf4\u0323t mu\u0303i t\xean, sau \u0111\u01b0\u01a1\u0323c khen va\u0300 phu\u0301c l\xf4\u0323c (ho\u0103\u0323c ch\u01b0\u0301c vi\u0323: m\xea\u0323nh) .\n","\n\u4e0a\u4e5d: \u9ce5\u711a\u5176\u5de2, \u65c5\u4eba\u5148 \u7b11, \u5f8c\u865f\u54b7, \u55aa\u725b\u4e8e\u6613, \u51f6\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: \u0111i\xea\u0309u ph\xe2\u0300n ki\u0300 sa\u0300o, l\u01b0\u0303 nh\xe2n ti\xean ti\xea\u0301u, h\xe2\u0323u ha\u0300o \u0111a\u0300o, ta\u0301ng ng\u01b0u vu di\u0323, hung.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: con chim cha\u0301y m\xe2\u0301t t\xf4\u0309, ng\u01b0\u01a1\u0300i l\u01b0\u0303 ha\u0300nh tr\u01b0\u01a1\u0301c c\u01b0\u01a1\u0300i, sau k\xeau kho\u0301c, vi\u0300 la\u0301u ta\u0301u (v\xf4 y\u0301) \u0111a\u0301nh m\xe2\u0301t con bo\u0300 (\u0111\u01b0\u0301c nhu thu\xe2\u0323n), x\xe2\u0301u.\n")
if(c6&&r.b===0&&r.c===1&&r.d===1&&r.e===0&&r.f===0)c4=A.ct("L\xf4i S\u01a1n Ti\u1ec3u Qu\xe1",c5,r.b,r.c,r.d,r.e,r.f,"C\u1ea4P QU\xc1 \u0110\u1ed8C KI\u1ec0U",b0,i,h,i,h,g,c3,"T\u1eed H\u1ee3i",2,4,4,a3,a4,r.r[26],"\n\u521d\u516d\uff0e\u98db\u9ce5\u4ee5\u51f6\uff0e\nS\u01a1 lu\u0323c: Phi \u0111i\xea\u0309u di\u0303 hung.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Chim (n\xean n\xe2\u0301p ma\u0300 la\u0323i) bay, n\xean x\xe2\u0301u.\n","\n\u516d\u4e8c: \u904e\u5176\u7956, \u9047\u5176\u59a3, \u4e0d\u53ca\u5176\u541b. \u9047\u5176\u81e3, \u65e0\u548e\uff0e\nL\u1ee5c nhi\u0323: Qua\u0301 ki\u0300 t\xf4\u0309, ng\xf4\u0323 ki\u0300 ti\u0309, b\xe2\u0301t c\xe2\u0323p ki\u0300 qu\xe2n.\nNg\xf4\u0323 ki\u0300 th\xe2\u0300n ,v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 2, \xe2m: V\u01b0\u01a1\u0323t qua \xf4ng ma\u0300 g\u0103\u0323p ba\u0300; kh\xf4ng \u0111\u01b0\u01a1\u0323c g\u0103\u0323p vua thi\u0300 n\xean gi\u01b0\u0303 ph\xe2\u0323n b\xea\u0300 t\xf4i, nh\u01b0 v\xe2\u0323y kh\xf4ng l\xf4\u0303i.\n","\n\u4e5d\u4e09\uff0e\u5f17\u904e\u9632\u4e4b, \u5f9e\u6216\u6215\u4e4b, \u51f6\uff0e\nC\u1eedu tam: Ph\xe2\u0301t qua\u0301 pho\u0300ng chi, to\u0300ng ho\u0103\u0323c t\u01b0\u01a1\u0300ng chi, hung.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: Ch\u0103\u0309ng qua\u0301 pho\u0300ng bi\u0323 (ti\xea\u0309u nh\xe2n) thi\u0300 r\xf4\u0300i se\u0303 bi\u0323 chu\u0301ng la\u0300m ha\u0323i \u0111\xe2\u0301y.\n","\n\u4e5d\u56db: \u65e0\u548e, \u5f17\u904e\u9047\u4e4b, \u5f80\u53b2, \u5fc5\u6212; \u52ff\u7528\u6c38\u8c9e\uff0e\nC\u1eedu t\u01b0\u0301: v\xf4 c\u01b0\u0303u, ph\xe2\u0301t qua\u0301 ng\xf4\u0323 chi, va\u0303ng l\xea\u0323, t\xe2\u0301t gi\u01a1\u0301i; v\xe2\u0323t du\u0323ng vi\u0303nh trinh.\nD\u1ecbch: Ha\u0300o 4, d\u01b0\u01a1ng: kh\xf4ng l\xf4\u0303i vi\u0300 kh\xf4ng qua\u0301 d\u01b0\u01a1ng ma\u0300 v\u01b0\u0300a \u0111u\u0301ng v\u01a1\u0301i \u0111a\u0323o ly\u0301 th\u01a1\u0300i Ti\xea\u0309u qua\u0301; n\xea\u0301u ti\xea\u0301n t\u01a1\u0301i thi\u0300 nguy, n\xean r\u0103n v\xea\u0300 \u0111i\xea\u0300u \u0111o\u0301, \u0111\u01b0\u0300ng c\xf4\u0301 gi\u01b0\u0303 \u0111\u01b0\u0301c c\u01b0\u01a1ng cu\u0309a mi\u0300nh, ma\u0300 n\xean bi\xea\u0301n th\xf4ng.\n","\n\u516d\u4e94: \u5bc6\u96f2\u4e0d\u96e8, \u81ea\u6211\u897f\u90ca; \u516c\u5f0b,\u53d6\u5f7c\u5728\u7a74\uff0e\nL\u1ee5c ngu\u0303: M\xe2\u0323t v\xe2n b\xe2\u0301t vu\u0303, t\u01b0\u0323 nga\u0303 t\xe2y giao;\nC\xf4ng d\u0103\u0323c, thu\u0309 bi\u0309 ta\u0323i huy\xea\u0323t.\nD\u1ecbch: Ha\u0300o 5, \xe2m: m\xe2y ki\u0323t ma\u0300 kh\xf4ng m\u01b0a \u01a1\u0309 co\u0303i t\xe2y cu\u0309a ta, c\xf4ng b\u0103\u0301n ma\u0300 b\u0103\u0301t l\xe2\u0301y no\u0301 \u01a1\u0309 hang.\n","\n\u4e0a\u516d: \u5f17\u9047\u904e\u4e4b, \u98db\u9ce5\u96e2\u4e4b. \u51f6, \u662f\u8b02\u707d\u771a\uff0e\nTh\u01b0\u1ee3ng lu\u0323c: ph\xe2\u0301t ng\xf4\u0323 qua\u0301 chi, phi \u0111i\xea\u0309u li chi. Hung, thi\u0323 vi\u0323 tai sa\u0309nh.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, \xe2m: kh\xf4ng \u0111u\u0301ng v\u01a1\u0301i \u0111a\u0323o ma\u0300 la\u0323i sai qua\u0301, nh\u01b0 ca\u0301nh chim bay cao qua\u0301, xa qua\u0301, s\u01a1\u0323 bi\u0323 tai va\u0323.\n")
if(c6&&r.b===0&&r.c===1&&r.d===0&&r.e===1&&r.f===1)c4=A.ct("Phong S\u01a1n Ti\u1ec7m",c5,r.b,r.c,r.d,r.e,r.f,"TU\u1ea4N M\xc3 XU\u1ea4T LUNG",b0,i,h,q,p,o,b6,"",5,0,3,b5,a8,r.r[33],"\n\u521d\u516d: \u9d3b\u6f38\u4e8e\u5e72, \u5c0f\u5b50\u53b2, \u6709\u8a00, \u65e0\u548e\uff0e\nS\u01a1 lu\u0323c: H\xf4\u0300ng ti\xea\u0323m vu can, ti\xea\u0309u nh\xe2n l\xea\u0323, h\u01b0\u0303u ng\xf4n, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 1, \xe2m: Con chim h\xf4\u0300ng ti\xea\u0301n \u0111\xea\u0301n b\u01a1\u0300 n\u01b0\u01a1\u0301c, nho\u0309 da\u0323i (ho\u0103\u0323c ti\xea\u0309u nh\xe2n) cho la\u0300 nguy, than th\u01a1\u0309, nh\u01b0ng kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u516d\u4e8c: \u9d3b\u6f38\u4e8e\u78d0, \u98f2\u98df\u884e\u884e, \u5409\uff0e\nL\u1ee5c nhi\u0323: H\xf4\u0300ng ti\xea\u0323m vu ba\u0300n, \xe2\u0309m th\u01b0\u0323c kha\u0309n kha\u0309n, ca\u0301t.\nD\u1ecbch: Ha\u0300o 2 \xe2m: Chim h\xf4\u0300ng ti\xea\u0301n \u0111\xea\u0301n phi\xea\u0301n \u0111a\u0301 l\u01a1\u0301n, \u0103n u\xf4\u0301ng tha\u0309nh th\u01a1i, t\xf4\u0301t.\n","\n\u4e5d\u4e09: \u9d3b\u6f38\u4e8e\u9678, \u592b\u5f81\u4e0d\u5fa9, \u5a66\u5b55\u4e0d\u80b2, \u51f6. \u5229\u79a6\u5bc7\uff0e\nC\u1eedu tam: H\xf4\u0300ng ti\xea\u0323m vu lu\u0323c, phu chinh b\xe2\u0301t phu\u0323c, phu\u0323 d\u01b0\u0323ng b\xe2\u0301t du\u0323c, hung, l\u01a1\u0323i ng\u01b0\u0323 kh\xe2\u0301u.\nD\u1ecbch: Ha\u0300o 3, d\u01b0\u01a1ng: Chim h\xf4\u0300ng ti\xea\u0301n t\u01a1\u0301i \u0111\xe2\u0301t b\u0103\u0300ng, ch\xf4\u0300ng \u0111i xa kh\xf4ng v\xea\u0300, v\u01a1\u0323 co\u0301 mang (\u0111e\u0309 con ma\u0300) kh\xf4ng nu\xf4i, x\xe2\u0301u; \u0111u\xf4\u0309i c\u01b0\u01a1\u0301p thi\u0300 co\u0301 l\u01a1\u0323i.\n","\n\u516d\u56db: \u9d3b\u6f38\u4e8e\u6728, \u6216\u5f97\u5176\u6877, \u65e0\u548e\uff0e\nL\u1ee5c t\u01b0\u0301: H\xf4\u0300ng ti\xea\u0323m vu m\xf4\u0323c, ho\u0103\u0323c \u0111\u0103\u0301c ky\u0300 gi\xf4\u0301c, v\xf4 c\u01b0\u0303u.\nD\u1ecbch: Ha\u0300o 4 \xe2m: Chim h\xf4\u0300ng nha\u0309y l\xean c\xe2y, may ti\u0300m \u0111\u01b0\u01a1\u0323c ca\u0300nh th\u0103\u0309ng ma\u0300 \u0111\xe2\u0323u, kh\xf4ng co\u0301 l\xf4\u0303i.\n","\n\u4e5d\u4e94: \u9d3b\u6f38\u4e8e\u9675, \u5a66\u4e09\u6b72\u4e0d\u5b55\uff0e\u7d42\u83ab\u4e4b\u52dd, \u5409\uff0e\nC\u1eedu ngu\u0303: H\xf4\u0300ng ti\xea\u0323m vu l\u0103ng, phu\u0323 tam tu\xea\u0301 b\xe2\u0301t d\u01b0\u0323ng. Chung ma\u0323c chi th\u0103\u0301ng, ca\u0301t.\nD\u1ecbch: Ha\u0300o 5, d\u01b0\u01a1ng: chim h\xf4\u0300ng l\xean go\u0300 cao; v\u01a1\u0323 ba n\u0103m kh\xf4ng sinh \u0111e\u0309, nh\u01b0ng cu\xf4\u0301i cu\u0300ng kh\xf4ng gi\u0300 th\u0103\u0301ng n\xf4\u0309i \u0111i\xea\u0300u chi\u0301nh, t\xf4\u0301t.\n","\n\u4e0a\u4e5d: \u9d3b\u6f38\u4e8e\u9678 , \u5176\u7fbd\u53ef\u7528\u70ba\u5100, \u5409\uff0e\nTh\u01b0\u1ee3ng c\u01b0\u0309u: H\xf4\u0300ng ti\xea\u0323m vu qui\u0300 (ch\u01b0\u0303 \u9678 du\u0300ng nh\u01b0 ch\u01b0\u0303 \u9035 qui\u0300 la\u0300 \u0111\u01b0\u01a1\u0300ng m\xe2y), ki\u0300 vu\u0303 kha\u0309 du\u0323ng vi nghi, ca\u0301t.\nD\u1ecbch: Ha\u0300o tr\xean cu\u0300ng, d\u01b0\u01a1ng: Chim h\xf4\u0300ng bay b\xf4\u0309ng \u01a1\u0309 \u0111\u01b0\u01a1\u0300ng m\xe2y, l\xf4ng no\u0301 (r\u01a1\u0301t xu\xf4\u0301ng) co\u0301 th\xea\u0309 du\u0300ng la\u0300m \u0111\xf4\u0300 trang \u0111i\xea\u0309m, t\xf4\u0301t.\n")
